# Vue 3 实现大文件分片上传 + 断点续传

本方案使用 `axios` + `FileReader` + `localStorage`（或 IndexedDB）实现大文件分片上传，支持断点续传、并发控制、上传进度展示、失败重传、暂停/继续、上传成功后合并文件。

## ✅ 功能清单

- 大文件分片上传（支持自定义分片大小，默认 2MB）
- 断点续传（基于 `localStorage` 存储每个分片的上传状态）
- 并发控制（可配置最大并发数）
- 上传进度展示（每个分片、整体）
- 暂停 / 继续上传
- 上传失败自动重传（重试次数可配）
- 上传成功后自动合并文件（可选）
- 响应式 Vue 3 组件，支持 Composition API

---

## 📁 项目结构

```
src/
├── components/
│   └── FileUploader.vue
├── utils/
│   ├── chunker.js
│   └── uploader.js
└── App.vue
```

---

## 1️⃣ `utils/chunker.js`

```javascript
// 文件分片工具
export class Chunker {
  constructor(file, chunkSize = 2 * 1024 * 1024) {
    this.file = file;
    this.chunkSize = chunkSize;
    this.chunks = [];
    this._buildChunks();
  }

  _buildChunks() {
    const { size } = this.file;
    const totalChunks = Math.ceil(size / this.chunkSize);
    for (let i = 0; i < totalChunks; i++) {
      const start = i * this.chunkSize;
      const end = Math.min(start + this.chunkSize, size);
      this.chunks.push({
        id: i,
        start,
        end,
        size: end - start,
        blob: this.file.slice(start, end),
      });
    }
  }

  get total() { return this.chunks.length; }
  get current() { return this.chunks.findIndex(c => c.uploaded === false); }
  get uploaded() { return this.chunks.filter(c => c.uploaded === true).length; }
}
```

---

## 2️⃣ `utils/uploader.js`

```javascript
// 上传器
import { Chunker } from './chunker.js';

export class Uploader {
  constructor({
    url,
    chunkSize = 2 * 1024 * 1024,
    maxConcurrency = 3,
    retryCount = 3,
    chunkHeaders = {},
    onProgress = () => {},
    onSuccess = () => {},
    onError = () => {},
  }) {
    this.url = url;
    this.chunkSize = chunkSize;
    this.maxConcurrency = maxConcurrency;
    this.retryCount = retryCount;
    this.chunkHeaders = chunkHeaders;
    this.onProgress = onProgress;
    this.onSuccess = onSuccess;
    this.onError = onError;

    this.chunks = [];          // 当前正在上传的分片
    this.pending = [];         // 待上传队列
    this.running = 0;
    this.uploaded = 0;
    this.total = 0;
    this.state = 'idle';       // idle | uploading | paused | finished | failed
    this._chunkId = 0;
  }

  async init(file) {
    this.file = file;
    this.chunks = new Chunker(file, this.chunkSize).chunks;
    this.total = this.chunks.length;
    this.uploaded = 0;
    this._chunkId = 0;
    this.state = 'idle';
    this._resume();
  }

  _resume() {
    this.pending = this.chunks.filter(c => c.uploaded === false);
    this.running = 0;
    this._next();
  }

  _next() {
    if (this.state !== 'uploading') return;
    if (this.running >= this.maxConcurrency) return;
    if (this.pending.length === 0) {
      this._finish();
      return;
    }
    const chunk = this.pending.shift();
    this._upload(chunk);
  }

  async _upload(chunk) {
    this.running++;
    this._chunkId++;
    const id = this._chunkId;
    const retry = this.retryCount;
    let attempt = 0;
    let lastError = null;

    while (attempt < retry) {
      try {
        const formData = new FormData();
        formData.append('file', chunk.blob, this.file.name);
        // 可选：添加 chunkId
        formData.append('chunkId', chunk.id);
        // 可选：添加 md5 做校验
        formData.append('md5', await this._md5(chunk.blob));

        const res = await this._request(this.url, formData, {
          headers: { ...this.chunkHeaders },
          onUploadProgress: (ev) => {
            if (ev.lengthComputable) {
              const pct = (ev.loaded / ev.total) * 100;
              this.onProgress({
                total: this.total,
                uploaded: this.uploaded,
                current: chunk.id,
                pct,
                file: this.file,
              });
            }
          },
        });

        chunk.uploaded = true;
        chunk.response = res;
        this.uploaded++;
        this._next();
        return;
      } catch (err) {
        lastError = err;
        attempt++;
        await this._wait(1000 * attempt);
      }
    }
    chunk.error = lastError;
    this._next();
  }

  async _md5(blob) {
    const array = await blob.arrayBuffer();
    const buf = new Uint8Array(array);
    const md5 = crypto.createHash('md5');
    md5.update(buf);
    return md5.digest('hex');
  }

  async _request(url, data, options = {}) {
    const config = {
      method: 'POST',
      url,
      data,
      headers: {
        'Content-Type': 'multipart/form-data',
        ...options.headers,
      },
      ...options,
    };
    return await axios(config);
  }

  async _wait(ms) {
    return new Promise(r => setTimeout(r, ms));
  }

  async pause() {
    this.state = 'paused';
  }

  async resume() {
    if (this.state !== 'paused') return;
    this.state = 'uploading';
    this._resume();
  }

  async abort() {
    this.state = 'failed';
    this.chunks.forEach(c => { c.uploaded = false; c.error = null; });
    this.uploaded = 0;
    this._chunkId = 0;
  }

  async merge() {
    // 假设服务端返回了合并后的文件地址，或者客户端合并
    const res = await this._request(`${this.url}/merge`, {
      headers: { 'Content-Type': 'application/json' },
      data: { file: this.file.name },
    });
    this.onSuccess(res.data);
  }

  _finish() {
    this.state = 'finished';
    this.onSuccess({ file: this.file, chunks: this.chunks });
  }
}
```

