      </button>
      <button v-if="uploading" @click="pauseUpload">暂停</button>
      <button v-if="uploading && paused" @click="resumeUpload">继续</button>
      <button v-if="uploading" @click="abortUpload">取消</button>
      <button v-if="finished" @click="mergeFile">合并文件</button>
    </div>
    <div class="progress" v-if="uploading">
      <div class="bar" :style="{ width: `${progress}%` }"></div>
      <div class="meta">
        <span>{{ uploaded }} / {{ total }} 分片</span>
        <span>{{ formatSize(totalSize) }}</span>
        <span>{{ formatSpeed(speed) }}/s</span>
      </div>
    </div>
    <div class="chunks" v-if="chunks.length">
      <div class="chunk" v-for="(c, i) in chunks" :key="i">
        <span class="idx">#{i + 1}</span>
        <span class="status" :class="c.status">
          {{ c.status }}
        </span>
        <span class="size">{{ formatSize(c.size) }}</span>
        <span class="pct" v-if="c.pct">{{ c.pct }}%</span>
      </div>
    </div>
    <div class="log" v-if="log.length">
      <div v-for="(l, i) in log" :key="i">{{ l }}</div>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted, onUnmounted } from 'vue';
import axios from 'axios';
import crypto from 'crypto';

const props = defineProps({
  url: {
    type: String,
    required: true,
  },
});

const fileInput = ref(null);
const uploader = ref(null);
const uploading = ref(false);
const paused = ref(false);
const finished = ref(false);
const failed = ref(false);
const progress = ref(0);
const total = ref(0);
const uploaded = ref(0);
const totalSize = ref(0);
const speed = ref(0);
const chunks = ref([]);
const log = ref([]);

const state = ref({
  current: 0,
  total: 0,
  pct: 0,
});

function formatSize(bytes) {
  if (bytes === 0) return '0 B';
  const k = 1024;
  const sizes = ['B', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return `${(bytes / Math.pow(k, i)).toFixed(i === 0 ? 0 : 1)} ${sizes[i]}`;
}

function formatSpeed(bytes) {
  if (bytes === 0) return '0 B';
  const k = 1024;
  const sizes = ['B', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return `${(bytes / Math.pow(k, i)).toFixed(i === 0 ? 0 : 1)} ${sizes[i]}`;
}

function onFileChange(e) {
  const file = e.target.files[0];
  if (!file) return;
  totalSize.value = file.size;
  total.value = Math.ceil(file.size / (2 * 1024 * 1024));
  uploaded.value = 0;
  chunks.value = [];
  log.value = [`选择文件: ${file.name} (${formatSize(file.size)})`];
}

async function startUpload() {
  if (!fileInput.value.files[0]) return;
  uploading.value = true;
  paused.value = false;
  finished.value = false;
  failed.value = false;
  log.value = [];
  const u = new Uploader({
    url: props.url,
    chunkSize: 2 * 1024 * 1024,
    maxConcurrency: 3,
    retryCount: 3,
    chunkHeaders: {},
    onProgress: (p) => {
      progress.value = p.pct;
      state.value = p;
      uploaded.value = p.uploaded;
      total.value = p.total;
      // 粗略估算速度
      const diff = Date.now() - (u._lastTime || 0);
      if (diff > 1000) {
        speed.value = Math.round((p.total * p.pct / 100) / (diff / 1000));
      }
      u._lastTime = Date.now();
    },
    onSuccess: (res) => {
      log.value.push(`✅ 上传完成: ${res.file.name}`);
      finished.value = true;
      uploading.value = false;
      log.value.push(`合并文件...`);
      mergeFile();
    },
    onError: (err) => {
      log.value.push(`❌ 上传失败: ${err.message}`);
      failed.value = true;
      uploading.value = false;
    },
  });
  await u.init(fileInput.value.files[0]);
  uploader.value = u;
}

async function pauseUpload() {
  if (!uploader.value) return;
  paused.value = true;
  await uploader.value.pause();
}

async function resumeUpload() {
  if (!uploader.value) return;
  paused.value = false;
  await uploader.value.resume();
}

async function abortUpload() {
  if (!uploader.value) return;
  await uploader.value.abort();
  log.value.push('❌ 上传已取消');
  uploading.value = false;
  paused.value = false;
  finished.value = false;
  failed.value = false;
}

async function mergeFile() {
  if (!uploader.value) return;
  log.value.push('正在合并文件...');
  await uploader.value.merge();
  log.value.push('✅ 合并完成');
}

// 模拟服务端响应（开发调试用）
function mockResponse() {
  return new Promise((resolve) => {
    setTimeout(() => resolve({ data: { url: 'https://example.com/merged/' } }), 1500);
  });
}

async function mergeFile() {
  if (!uploader.value) return;
  const res = await mockResponse();
  log.value.push(`✅ 合并文件: ${res.data.url}`);
}
</script>

