<script>
// ---------- Solar Geometry ----------
// Simplified solar position calculator
// Returns { azimuth: deg, altitude: deg, hourAngle: deg, sunAz: deg }
function solarPosition(date, lat, lon) {
  const year = date.getFullYear();
  const month = date.getMonth() + 1;
  const day = date.getDate();
  const hours = date.getHours();
  const minutes = date.getMinutes();
  const seconds = date.getSeconds();

  // Day of year (1..366)
  const N = Math.floor((day - 1) + (month - 1) * 30.4167 + (year - 1970) * 365.25);
  const dayOfYear = N;

  // Approximate solar declination (simplified)
  const declination = 23.45 * Math.sin((2 * Math.PI / 365.25) * (dayOfYear - 80));

  // Hour angle (simplified — assumes 12h noon)
  const h = (hours - 12 + minutes / 60 + seconds / 3600) * 15;

  // Latitude (positive for N, negative for S)
  const phi = lat * (lat >= 0 ? 1 : -1);

  // Hour angle in radians
  const H = h * Math.PI / 12;

  // Right ascension (simplified — sidereal day)
  const sidereal = 2 * Math.PI * (dayOfYear + 2) / 365.25;

  // Convert to local time
  const localSidereal = sidereal - lon * Math.PI / 12;
  const localH = localSidereal * 15;

  // Altitude (in radians)
  const cosZ = Math.sin(phi) * Math.sin(declination) + Math.cos(phi) * Math.cos(declination) * Math.cos(localH);
  const altitude = Math.max(-1.0, Math.min(1.0, cosZ));
  const altDeg = Math.asin(altitude) * 180 / Math.PI;

  // Azimuth (in radians)
  const sinAz = Math.cos(declination) * Math.sin(localH) / Math.cos(altDeg * Math.PI / 180);
  const azDeg = Math.atan2(sinAz, Math.cos(declination) * Math.cos(localH) - Math.sin(declination) * Math.sin(phi)) * 180 / Math.PI;
  // Convert to 0..360 (east = 0°)
  let az = azDeg;
  if (az < 0) az += 360;

  return { azimuth: az, altitude: altDeg, hourAngle: localH * 15 };
}

// ---------- Moon Phase ----------
function moonPhase(dayOfYear) {
  // New moon on day 0 (Jan 6, 2025)
  const phase = (dayOfYear % 29.53) / 29.53;
  return phase;
}

// ---------- Starfield ----------
function generateStars(count = 180) {
  const container = document.getElementById('stars');
  container.innerHTML = '';
  const dpr = window.devicePixelRatio || 1;
  for (let i = 0; i < count; i++) {
    const el = document.createElement('span');
    el.className = 'star ' + (Math.random() < 0.25 ? 'big' : Math.random() < 0.55 ? 'med' : 'sml');
    el.style.left = Math.random() * 100 + '%';
    el.style.top = Math.random() * 100 + '%';
    el.style.width = (Math.random() * 1.6 + 0.4) + 'px';
    el.style.height = el.style.width;
    container.appendChild(el);
  }
}

// ---------- Animation ----------
const canvas = document.getElementById('sky');
const ctx = canvas.getContext('2d');
let W = 0, H = 0;
let rafId = null;
let paused = true;
let startTime = Date.now();
let elapsed = 0;
let lastTime = 0;

function resize() {
  W = window.innerWidth;
  H = window.innerHeight;
  canvas.width = W * (window.devicePixelRatio || 1);
  canvas.height = H * (window.devicePixelRatio || 1);
  canvas.style.width = W + 'px';
  canvas.style.height = H + 'px';
  ctx.setTransform(window.devicePixelRatio || 1, 0, 0, window.devicePixelRatio || 1, 0, 0);
  generateStars();
  render();
}

function tick(now) {
  if (paused) return;
  const dt = now - lastTime;
  lastTime = now;
  elapsed += dt;
  render();
  rafId = requestAnimationFrame(tick);
}

function render() {
  // Background
  ctx.clearRect(0, 0, W, H);

  // Gradient sky
  const t = elapsed / 10000; // 10s cycle
  const cycle = t % 1;
  const grad = ctx.createLinearGradient(0, 0, 0, H);
  grad.addColorStop(0, '#1a2a4a');
  grad.addColorStop(0.35, '#2a3a6a');
  grad.addColorStop(0.65, '#0a1228');
  grad.addColorStop(1, '#050810');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, W, H);

  // Stars (subtle)
  const stars = document.getElementById('stars').children;
  for (let i = 0; i < stars.length; i++) {
    const s = stars[i];
    const x = s.offsetLeft / W;
    const y = s.offsetTop / H;
    const size = parseFloat(s.style.width);
    // Subtle shimmer
    ctx.fillStyle = `rgba(255,255,255,${0.15 + Math.sin(elapsed * 0.002 + i) * 0.05})`;
    ctx.beginPath();
    ctx.arc(x * W, y * H, size, 0, Math.PI * 2);
    ctx.fill();
  }

  // Horizon glow
  const horizon = document.getElementById('horizon');
  const horizonX = (W - horizon.offsetWidth) / 2;
  ctx.fillStyle = 'rgba(255, 210, 140, 0.25)';
  ctx.beginPath();
  ctx.moveTo(horizonX, H - horizon.offsetHeight);
  ctx.quadraticCurveTo(W, H - horizon.offsetHeight, W, H);
  ctx.lineTo(0, H);
  ctx.quadraticCurveTo(0, H - horizon.offsetHeight, horizonX, H - horizon.offsetHeight);
  ctx.closePath();
  ctx.fill();

  // Sun
  const date = new Date(startTime + elapsed);
  const { azimuth, altitude, hourAngle } = solarPosition(date, parseFloat(document.getElementById('lat').value), parseFloat(document.getElementById('lon').value));
  const sunEl = document.getElementById('sun');
  const sunLabel = document.getElementById('sun-label');

  // Sun size varies with altitude
  const sunSize = 120 + Math.max(0, altitude) * 0.6;
  sunEl.style.width = sunSize + 'px';
  sunEl.style.height = sunSize + 'px';

  // Position
  const horizonY = H - horizon.offsetHeight;
  const sunY = horizonY + Math.max(0, altitude) * (H - horizonY) * 0.55;
  const sunX = (W - sunSize) / 2 + Math.sin(azimuth * Math.PI / 180) * (sunSize / 2);
  sunEl.style.left = sunX + 'px';
  sunEl.style.top = sunY + 'px';

  // Label
  sunLabel.textContent = `${String(Math.round(altitude)).padStart(2,'0')}°`;

  // Moon (optional)
  const moonEl = document.getElementById('moon');
  const moonLabel = document.getElementById('moon-label');
  const moonPhaseVal = parseFloat(document.getElementById('moon').value);
  const moonAz = (azimuth + 90) % 360;
  const moonSize = 48;
  const moonX = (W - moonSize) / 2 + Math.sin(moonAz * Math.PI / 180) * (moonSize / 2);
  const moonY = sunY + (sunSize - moonSize) * 0.5;
  moonEl.style.left = moonX + 'px';
  moonEl.style.top = moonY + 'px';

  // Moon label
  const phaseText = document.getElementById('moon').options[document.getElementById('moon').selectedIndex].text;
  moonLabel.textContent = phaseText;

  // Info
  document.getElementById('time').textContent = date.toTimeString().slice(0, 8);
  document.getElementById('day').textContent = `${dayOfYearLabel(date)}`;
  document.getElementById('loc').textContent = `${document.getElementById('lat').value}°${document.getElementById('lat').value >= 0 ? 'N' : 'S'}, ${document.getElementById('lon').value}°${document.getElementById('lon').value >= 0 ? 'E' : 'W'}`;
  document.getElementById('alt').textContent = `${String(Math.round(altitude)).padStart(2,'0')}°`;
  document.getElementById('az').textContent = `${String(Math.round(moonAz)).padStart(2,'0')}°`;

  // Status
  document.getElementById('statusText').textContent = paused ? 'Paused' : 'Running';
  document.getElementById('statusDot').classList.toggle('active', !paused);
}

function dayOfYearLabel(date) {
  const year = date.getFullYear();
  const month = date.getMonth() + 1;
  const day = date.getDate();
  return `${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`;
}

// ---------- Init ----------
function init() {
  resize();
  // Start at a specific time (10:00 AM)
  startTime = Date.now() - (10 * 3600 + 0) * 1000;
  lastTime = startTime;
  paused = true;
  rafId = requestAnimationFrame(tick);
}

// ---------- Events ----------
window.addEventListener('resize', resize);
document.getElementById('date').addEventListener('change', (e) => {
  const d = new Date(e.target.value + 'T00:00:00');
  if (!isNaN(d)) startTime = Date.now() - (10 * 3600 + 0) * 1000;
});
document.getElementById('reset').addEventListener('click', () => {
  startTime = Date.now() - (10 * 3600 + 0) * 1000;
  paused = true;
});
document.getElementById('lat').addEventListener('change', () => {
  if (rafId) cancelAnimationFrame(rafId);
  paused = true;
  rafId = requestAnimationFrame(tick);
});
document.getElementById('lon').addEventListener('change', () => {
  if (rafId) cancelAnimationFrame(rafId);
  paused = true;
  rafId = requestAnimationFrame(tick);
});
document.getElementById('moon').addEventListener('change', () => {
  if (rafId) cancelAnimationFrame(rafId);
  paused = true;
  rafId = requestAnimationFrame(tick);
});

// Keyboard
window.addEventListener('keydown', (e) => {
  if (e.key === ' ' || e.key === 'Enter') {
    e.preventDefault();
    paused = !paused;
  }
});

init();
</script>
</body>
</html>
