<!-- Toast -->
<div class="toast" id="toast" role="status" aria-live="polite"></div>

<script>
// ---------- State ----------
const STORAGE = {
  users: 'alex_blog_users',
  messages: 'alex_blog_messages',
  followers: 'alex_blog_followers',
  auth: 'alex_blog_auth'
};

const state = {
  user: loadAuth(),
  messages: loadMessages(),
  followers: loadFollowers(),
  currentView: 'home'
};

function loadAuth() {
  try { return JSON.parse(localStorage.getItem(STORAGE.auth)) || null; }
  catch { return null; }
}
function saveAuth(u) { localStorage.setItem(STORAGE.auth, JSON.stringify(u)); }
function loadMessages() {
  try { return JSON.parse(localStorage.getItem(STORAGE.messages)) || []; }
  catch { return []; }
}
function saveMessages(ms) { localStorage.setItem(STORAGE.messages, JSON.stringify(ms)); }
function loadFollowers() {
  try { return JSON.parse(localStorage.getItem(STORAGE.followers)) || []; }
  catch { return []; }
}
function saveFollowers(f) { localStorage.setItem(STORAGE.followers, JSON.stringify(f)); }

// ---------- Helpers ----------
function $$(sel, root=document) { return Array.from(root.querySelectorAll(sel)); }
function $$(id) { return document.getElementById(id); }
function toast(msg, type='success') {
  const t = $$('toast')[0];
  t.textContent = msg;
  t.className = 'toast' + (type === 'error' ? ' alert-danger' : ' alert-success');
  t.classList.add('show');
  clearTimeout(t._timer);
  t._timer = setTimeout(() => t.classList.remove('show'), 2500);
}
function openModal() {
  $$('#loginModal')[0].classList.remove('hidden');
  $$('#loginForm')[0].style.display = 'none';
  $$('#registerForm')[0].style.display = 'block';
  $$('#loginTitle')[0].textContent = 'Welcome back';
  $$('#loginBody')[0].textContent = 'Sign in to continue to Alex\'s blog.';
  $$('#switchToRegister')[0].textContent = 'Create account';
  $$('#loginForm')[0].reset();
  $$('#registerForm')[0].reset();
}
function closeModal() { $$('#loginModal')[0].classList.add('hidden'); }

// ---------- Auth ----------
function loginUser(username) {
  state.user = { username };
  saveAuth(state.user);
  toast(`Welcome back, ${username}!`, 'success');
  render();
}
function logoutUser() {
  state.user = null;
  saveAuth(null);
  toast('You have been logged out', 'success');
  render();
}
function toggleFollow(userId) {
  const idx = state.followers.findIndex(f => f.id === userId);
  if (idx >= 0) {
    state.followers.splice(idx, 1);
    toast('Unfollowed', 'success');
  } else {
    state.followers.push({ id: userId, name: getUserName(userId) });
    toast('Following', 'success');
  }
  saveFollowers(state.followers);
  render();
}

// ---------- Messaging ----------
function sendMessage(from, to, text) {
  const now = new Date();
  const msg = { from, to, text, time: now };
  state.messages.push(msg);
  saveMessages(state.messages);
  toast('Message sent!', 'success');
  render();
}
function getMessagesForUser(user) {
  return state.messages.filter(m => m.from === user || m.to === user);
}

// ---------- Rendering ----------
function render() {
  // Sidebar
  renderSidebar();
  // Header nav active
  $$('.nav a').forEach(a => {
    a.classList.toggle('active', a.dataset.view === state.currentView);
  });
  // View content
  $$('.view').forEach(v => v.classList.toggle('active', v.dataset.view === state.currentView));
  // Profile
  if (state.currentView === 'profile') renderProfile();
  // Messages badge
  updateBadge();
}

function renderSidebar() {
  const u = state.user;
  const followersCount = state.followers.length;
  const followingCount = getFollowingCount();
  const postsCount = 4;
  const likesCount = 4892;
  const commentsCount = 2103;

  $$('.stat-card strong').forEach((el, i) => {
    const vals = [followersCount, followingCount, postsCount, likesCount];
    el.textContent = vals[i];
  });
  $$('.stat-card span').forEach((el, i) => {
    const labels = ['Followers', 'Following', 'Posts', 'Likes'];
    el.textContent = labels[i];
  });

  // Follow button
  const followBtn = $$('.sidebar-follow .follow-btn')[0];
  if (u) {
    followBtn.textContent = 'Unfollow';
    followBtn.classList.add('following');
  } else {
    followBtn.textContent = 'Follow';
    followBtn.classList.remove('following');
  }
}

function renderProfile() {
  const u = state.user;
  const msgList = $$('#msgList')[0];
  const msgEmpty = $$('#msgEmpty')[0];
  const msgs = getMessagesForUser(u.username);
  msgList.innerHTML = '';
  if (msgs.length === 0) {
    msgEmpty.style.display = 'block';
  } else {
    msgEmpty.style.display = 'none';
    msgs.forEach(m => {
      const item = document.createElement('div');
      item.className = 'message-item';
      item.innerHTML = `
        <div class="from">${m.from}</div>
        <div class="time">${formatTime(m.time)}</div>
        <div class="body">${escapeHtml(m.text)}</div>
      `;
      msgList.appendChild(item);
    });
  }
}

function getFollowingCount() {
  return state.followers.filter(f => f.following).length;
}

function formatTime(d) {
  const h = d.getHours().toString().padStart(2,'0');
  const m = d.getMinutes().toString().padStart(2,'0');
  return `${h}:${m}`;
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function updateBadge() {
  const badge = $$('#msgBadge')[0];
  const count = state.messages.filter(m => m.to === state.user.username && !m.read).length;
  badge.textContent = count;
  badge.style.display = count > 0 ? 'inline-flex' : 'none';
}

// ---------- Navigation ----------
$$('.nav a').forEach(a => {
  a.addEventListener('click', e => {
    e.preventDefault();
    const view = a.dataset.view;
    state.currentView = view;
    render();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });
});

$$('[data-view]').forEach(el => {
  el.addEventListener('click', e => {
    if (el.tagName === 'A') {
      e.preventDefault();
      const view = el.dataset.view;
      state.currentView = view;
      render();
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  });
});

// ---------- Article preview ----------
function viewArticle(id) {
  const titles = ['Building Responsive Layouts with CSS Grid', 'The Art of Clean Code: Naming Conventions That Stick',
    'Designing for Dark Mode: A Practical Approach', 'State Management in Modern JavaScript'];
  const body = titles[id - 1] + ' — A comprehensive guide covering everything from fundamentals to advanced patterns. Perfect for developers looking to deepen their craft.';
  toast(body, 'success');
}

// ---------- Photo grid ----------
function initPhotoGrid() {
  const grid = $$('#photoGrid')[0];
  grid.innerHTML = '';
  const photos = ['pic1','pic2','pic3','pic4','pic5','pic6','pic7','pic8','pic9','pic10'];
  photos.forEach(p => {
    const item = document.createElement('div');
    item.className = 'photo-item';
    item.innerHTML = `<img src="https://picsum.photos/seed/${p}/600/400" alt="${p}">`;
    grid.appendChild(item);
  });
}

// ---------- Social follow ----------
$$('.social-item .follow-btn').forEach(btn => {
  btn.addEventListener('click', () => {
    const following = btn.classList.contains('following');
    const name = btn.parentElement.querySelector('.name').textContent;
    const id = name.toLowerCase().replace(/\s+/g,'');
    if (following) {
      state.followers = state.followers.filter(f => f.id !== id);
    } else {
      state.followers.push({ id, name });
    }
    saveFollowers(state.followers);
    btn.classList.toggle('following', !following);
    btn.textContent = following ? 'Follow' : 'Following';
    toast(following ? 'Unfollowed' : 'Following', 'success');
  });
});

// ---------- Messages ----------
$$('.header-right .icon-btn').forEach(btn => {
  btn.addEventListener('click', () => {
    if (state.user) {
      render();
      $$('#msgList')[0].scrollIntoView({ behavior: 'smooth', block: 'start' });
    } else {
      openModal();
    }
  });
});

$$('.compose-form').forEach(form => {
  form.addEventListener('submit', e => {
    e.preventDefault();
    const from = state.user.username;
    const to = form.querySelector('input[type="text"]').value.trim();
    const text = form.querySelector('textarea').value.trim();
    if (!to || !text) return;
    sendMessage(from, to, text);
    form.reset();
    closeModal();
  });
});

// ---------- Login / Register ----------
$$('.nav a').forEach(a => {
  if (a.dataset.view === 'profile' && state.user) {
    a.addEventListener('click', e => {
      e.preventDefault();
      openModal();
    });
  }
});

$$('.btn-outline').forEach(b => {
  b.addEventListener('click', () => {
    const label = b.textContent;
    if (label.includes('Create account')) {
      $$('#loginForm')[0].style.display = 'none';
      $$('#registerForm')[0].style.display = 'block';
      $$('#loginTitle')[0].textContent = 'Create your account';
      $$('#loginBody')[0].textContent = 'Join Alex\'s blog and start connecting.';
      $$('#switchToRegister')[0].textContent = 'Already have an account?';
    } else if (label.includes('Already have')) {
      $$('#loginForm')[0].style.display = 'block';
      $$('#registerForm')[0].style.display = 'none';
      $$('#loginTitle')[0].textContent = 'Welcome back';
      $$('#loginBody')[0].textContent = 'Sign in to continue to Alex\'s blog.';
      $$('#switchToRegister')[0].textContent = 'Create account';
    }
  });
});

$$('form').forEach(f => {
  f.addEventListener('submit', e => {
    e.preventDefault();
    const email = f.querySelector('#loginEmail')?.value;
    const username = f.querySelector('#regUsername')?.value;
    if (f.id === 'loginForm') {
      if (email) loginUser(username || email);
    } else {
      if (username && email) {
        state.user = { username };
        saveAuth(state.user);
        toast(`Account created! Welcome, ${username}!`, 'success');
        render();
      }
    }
  });
});

// ---------- Close modal ----------
$$('body').addEventListener('click', e => {
  if (e.target.id === 'closeModal' || e.target.id === 'loginModal') closeModal();
});

// ---------- Init ----------
initPhotoGrid();
render();
</script>
</body>
</html>
