// ---------- Helpers ----------
function uid() { return Math.random().toString(36).slice(2, 10); }

function loadState() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) state = { ...state, ...JSON.parse(raw) };
  } catch (e) { /* ignore */ }
}

function saveState() {
  try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); } catch (e) { /* ignore */ }
}

function fmt(n) {
  return '$' + n.toFixed(2);
}

// ---------- Account ----------
function getAccount() {
  if (state.account) return state.account;
  const raw = localStorage.getItem('furnispace.account');
  if (raw) {
    try { state.account = JSON.parse(raw); return state.account; }
    catch { /* ignore */ }
  }
  return null;
}

function setAccount(acc) {
  state.account = acc;
  localStorage.setItem('furnispace.account', JSON.stringify(acc));
  renderAccount();
}

function logout() {
  state.account = null;
  localStorage.removeItem('furnispace.account');
  renderAccount();
}

function renderAccount() {
  const a = document.getElementById('avatar');
  const n = document.getElementById('accountName');
  const e = document.getElementById('accountEmail');
  if (state.account) {
    a.textContent = state.account.initials || '👤';
    n.textContent = state.account.username || 'Guest';
    e.textContent = state.account.email || '—';
  } else {
    a.textContent = '👤';
    n.textContent = 'Guest';
    e.textContent = '—';
  }
}

// ---------- Rendering ----------
function renderCatalog() {
  const list = document.getElementById('furnitureList');
  const cat = state.currentCat;
  const items = cat === 'all' ? CATALOG : CATALOG.filter(i => i.cat === cat);
  list.innerHTML = '';
  items.forEach(item => {
    const el = document.createElement('div');
    el.className = 'furniture-item';
    el.draggable = true;
    el.dataset.id = item.id;
    el.innerHTML = `
      <div class="f-img" style="background-image:url('${item.img}')"></div>
      <div class="f-info">
        <div class="f-name">${item.name}</div>
        <div class="f-cat">${item.cat}</div>
      </div>
      <div class="f-price">${fmt(item.price)}</div>
    `;
    el.addEventListener('dragstart', e => onDragStart(e, item));
    el.addEventListener('dragend', onDragEnd);
    list.appendChild(el);
  });
  document.getElementById('itemCount').textContent = `${items.length} item${items.length !== 1 ? 's' : ''}`;
}

function renderRoom() {
  const canvas = document.getElementById('roomCanvas');
  const ctx = canvas.getContext('2d');
  const room = state.room;

  // Resize canvas
  const rect = canvas.parentElement.getBoundingClientRect();
  canvas.width = rect.width;
  canvas.height = rect.height;

  // Background
  ctx.fillStyle = '#d9d4cc';
  ctx.fillRect(0, 0, rect.width, rect.height);

  // Walls
  ctx.fillStyle = '#c9c4bc';
  ctx.fillRect(18, 18, rect.width - 36, 18);
  ctx.fillRect(18, 18, 18, rect.height - 36);
  ctx.fillRect(rect.width - 18, 18, 18, rect.height - 36);
  ctx.fillRect(18, rect.height - 18, rect.width - 36, 18);

  // Floor
  ctx.fillStyle = '#b8b2a8';
  ctx.fillRect(18, rect.height - 18, rect.width - 36, 18);

  // Ceiling
  ctx.fillStyle = '#e6e2da';
  ctx.fillRect(18, 0, rect.width - 36, 18);

  // Items
  room.items.forEach(item => {
    const img = CATALOG.find(c => c.id === item.id);
    if (!img) return;
    const x = item.x * (rect.width - 36) / 100;
    const y = item.y * (rect.height - 36) / 100;
    const w = item.w * (rect.width - 36) / 100;
    const h = item.h * (rect.height - 36) / 100;
    const bw = Math.max(4, w * 0.15);
    const bh = Math.max(4, h * 0.15);
    ctx.save();
    ctx.shadowColor = '#c97b5a';
    ctx.shadowBlur = 12;
    ctx.fillStyle = '#fff';
    ctx.fillRect(x, y, w, h);
    ctx.strokeStyle = '#c97b5a';
    ctx.lineWidth = bw;
    ctx.strokeRect(x + bw/2, y + bh/2, w - bw, h - bh);
    ctx.fillStyle = '#c97b5a';
    ctx.font = '11px Inter, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(img.name, x + w/2, y + h - 4);
    ctx.restore();
  });

  // Room title
  ctx.fillStyle = '#2b2a28';
  ctx.font = '14px Inter, sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText(room.title, rect.width / 2, 24);
}

function renderCart() {
  const list = document.getElementById('cartItems');
  const total = document.getElementById('total');
  const subtotal = document.getElementById('subtotal');
  const shipping = document.getElementById('shipping');
  const tax = document.getElementById('tax');

  if (state.cart.length === 0) {
    list.innerHTML = `<div class="cart-empty">Your cart is empty. Add some furniture to get started.</div>`;
    total.textContent = '$0';
    subtotal.textContent = '$0';
    shipping.textContent = '$0';
    tax.textContent = '$0';
    return;
  }

  list.innerHTML = '';
  let sub = 0;
  state.cart.forEach(item => {
    sub += item.price;
    const el = document.createElement('div');
    el.className = 'cart-row';
    el.innerHTML = `
      <div class="c-img" style="background-image:url('${item.img}')"></div>
      <div class="c-info">
        <div class="c-name">${item.name}</div>
        <div class="c-price">${fmt(item.price)}</div>
      </div>
      <button class="cart-remove" title="Remove" data-id="${item.id}">×</button>
    `;
    el.querySelector('.cart-remove').addEventListener('click', e => {
      e.stopPropagation();
      removeFromCart(item.id);
    });
    list.appendChild(el);
  });

  const shippingVal = sub > 1000 ? 0 : Math.min(sub * 0.05, 25);
  const taxVal = sub * 0.08;
  const totalVal = sub + shippingVal + taxVal;

  subtotal.textContent = fmt(sub);
  shipping.textContent = fmt(shippingVal);
  tax.textContent = fmt(taxVal);
  total.textContent = fmt(totalVal);
}

function removeFromCart(id) {
  state.cart = state.cart.filter(i => i.id !== id);
  saveState();
  renderCart();
  renderRoom();
}

// ---------- Room operations ----------
function placeItem(id, x, y, w, h) {
  const img = CATALOG.find(c => c.id === id);
  if (!img) return;
  const existing = state.room.items.find(i => i.id === id);
  if (existing) {
    existing.x = x; existing.y = y;
  } else {
    state.room.items.push({ id, x, y, w, h });
  }
  saveState();
  renderRoom();
}

function removeItem(id) {
  state.room.items = state.room.items.filter(i => i.id !== id);
  saveState();
  renderRoom();
}

function clearRoom() {
  state.room.items = [];
  saveState();
  renderRoom();
}

function shareRoom() {
  const key = state.room.title || 'my-room';
  const shareUrl = window.location.origin + '#' + encodeURIComponent(key);
  if (navigator.share) {
    navigator.share({ title: 'FurniSpace', text: 'Check out my room!', url: shareUrl });
  } else {
    const url = window.location.href.split('#')[0] + '#' + encodeURIComponent(key);
    navigator.clipboard?.writeText(url);
    alert('Link copied to clipboard:\n' + url);
  }
}

// ---------- Drag & Drop ----------
let dragItem = null;
let dragOffset = { x: 0, y: 0 };

function onDragStart(e, item) {
  dragItem = item;
  dragOffset = { x: e.clientX - item.x, y: e.clientY - item.y };
  e.dataTransfer.effectAllowed = 'move';
  e.dataTransfer.setData('text/plain', item.id);
  e.dataTransfer.setData('text/furniture', JSON.stringify(item));
  e.currentTarget.classList.add('dragging');
}

function onDragEnd(e) {
  if (dragItem) {
    e.currentTarget.classList.remove('dragging');
    dragItem = null;
  }
}

function onDragOver(e) {
  if (!dragItem) return;
  e.preventDefault();
  e.dataTransfer.dropEffect = 'move';
}

function onDrop(e) {
  if (!dragItem) return;
  e.preventDefault();
  const rect = e.currentTarget.getBoundingClientRect();
  const x = ((e.clientX - rect.left) / rect.width) * 100;
  const y = ((e.clientY - rect.top) / rect.height) * 100;
  placeItem(dragItem.id, x, y, dragItem.w, dragItem.h);
}

// ---------- Event wiring ----------
function wireEvents() {
  // Categories
  document.querySelectorAll('.cat-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('.cat-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      state.currentCat = btn.dataset.cat;
      renderCatalog();
    });
  });

  // Login
  document.getElementById('loginBtn').addEventListener('click', () => {
    document.getElementById('loginModal').hidden = false;
  });
  document.getElementById('closeLogin').addEventListener('click', () => {
    document.getElementById('loginModal').hidden = true;
  });
  document.getElementById('submitLogin').addEventListener('click', () => {
    const username = document.getElementById('usernameInput').value.trim();
    const email = document.getElementById('emailInput').value.trim();
    if (!username) { alert('Please enter a username'); return; }
    setAccount({ username, email, initials: username[0].toUpperCase() });
    document.getElementById('loginModal').hidden = true;
  });

  // Theme toggle
  document.getElementById('themeToggle').addEventListener('click', () => {
    state.theme = state.theme === 'light' ? 'dark' : 'light';
    document.body.classList.toggle('dark', state.theme === 'dark');
    saveState();
  });

  // Reset
  document.getElementById('resetBtn').addEventListener('click', () => {
    if (confirm('Reset the room to empty?')) {
      clearRoom();
    }
  });

  // Share
  document.getElementById('shareBtn').addEventListener('click', shareRoom);

  // Checkout
  document.getElementById('checkoutBtn').addEventListener('click', () => {
    if (state.cart.length === 0) {
      alert('Your cart is empty.');
      return;
    }
    const total = state.cart.reduce((s, i) => s + i.price, 0);
    const shipping = total > 1000 ? 0 : Math.min(total * 0.05, 25);
    const tax = total * 0.08;
    alert(`Checkout:\n\nItems: ${state.cart.length}\nSubtotal: ${fmt(total)}\nShipping: ${fmt(shipping)}\nTax: ${fmt(tax)}\n\nTotal: ${fmt(total + shipping + tax)}\n\nThanks for shopping!`);
  });

  // Canvas drop
  document.getElementById('room').addEventListener('dragover', onDragOver);
  document.getElementById('room').addEventListener('drop', onDrop);

  // Room resize
  window.addEventListener('resize', renderRoom);
}

// ---------- Init ----------
function init() {
  loadState();
  renderAccount();
  renderCatalog();
  renderCart();
  renderRoom();
  wireEvents();
}

document.addEventListener('DOMContentLoaded', init);
```

Here is a complete **Bubble Shooter** game implementation in **HTML5 Canvas + JavaScript**. The game features:

- A **hexagonal matrix** of colored bubbles at the top.
- A **cannon** at the bottom controlled by the **mouse** (angle).
- **Click-to-shoot** colored bubbles with trajectory prediction.
- **Physics-based motion** with adhesion to bubbles and walls.
- **Chain elimination** when 3+ same-color bubbles are connected.
- **Smooth animation** with requestAnimationFrame.

---

### ✅ Features Implemented:
- Hexagonal grid layout (tilted).
- Bubble adhesion via spring physics.
- Collision detection between bubbles and cannon.
- Chain reaction: eliminate connected groups.
- Visual trajectory prediction line.
- Score & combo counter.

