<style>
  .annotation-panel {
    border: 1px solid #ccc;
    border-radius: 8px;
    padding: 12px;
    background: #f7f7f7;
    margin: 10px 0;
  }
  .annotation-panel h5 {
    margin: 0 0 8px;
  }
  .annotation-input {
    display: flex;
    gap: 8px;
    margin-bottom: 8px;
  }
  .annotation-input input[type="text"],
  .annotation-input textarea {
    flex: 1;
    min-width: 120px;
    padding: 6px 8px;
    border: 1px solid #ddd;
    border-radius: 4px;
  }
  .annotation-input textarea {
    min-height: 40px;
    resize: vertical;
  }
  .annotation-input button {
    padding: 6px 12px;
    border: 1px solid #ddd;
    border-radius: 4px;
    cursor: pointer;
  }
  .annotation-input button:hover {
    background: #eef2ff;
  }
  .annotation-input button.remove {
    background: #ff5555;
    color: white;
  }
  .annotation-input button.remove:hover {
    background: #c0392b;
  }
  .canvas-wrap {
    border: 1px solid #ddd;
    border-radius: 4px;
    overflow: hidden;
    margin-top: 10px;
  }
  .canvas-wrap canvas {
    display: block;
  }
  .canvas-actions {
    display: flex;
    gap: 8px;
    margin-top: 8px;
  }
  .btn-group {
    display: flex;
    gap: 8px;
  }
  .image-list {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }
  .image-item {
    border: 1px solid #ddd;
    border-radius: 4px;
    overflow: hidden;
    cursor: pointer;
    transition: border-color .2s;
  }
  .image-item:hover {
    border-color: #666;
  }
  .image-item img {
    width: 100%;
    display: block;
  }
  .image-item.selected {
    border-color: #007bff;
    box-shadow: 0 0 0 3px rgba(0,123,255,.2);
  }
  .image-meta {
    padding: 6px 10px;
    font-size: 12px;
    background: #f0f0f0;
    border-radius: 4px;
  }
  .image-meta strong {
    color: #000;
  }
  .progress {
    margin-top: 10px;
    overflow: hidden;
    height: 6px;
    background: #e9ecef;
    border-radius: 3px;
  }
  .progress-bar {
    height: 100%;
    background: #007bff;
    width: 0%;
    transition: width .3s;
  }
  .alert {
    margin-bottom: 10px;
  }
  .file-drop {
    border: 2px dashed #ccc;
    border-radius: 8px;
    padding: 24px;
    text-align: center;
    cursor: pointer;
    transition: border-color .2s, background .2s;
  }
  .file-drop:hover {
    border-color: #007bff;
    background: #eef4ff;
  }
  .file-drop.dragover {
    border-color: #007bff;
    background: #eef4ff;
  }
  .image-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
    gap: 10px;
  }
  .image-grid .image-item {
    grid-column: span 1;
  }
  @media (max-width: 768px) {
    .image-grid {
      grid-template-columns: 1fr;
    }
  }
