<script src="https://cdn.jsdelivr.net/npm/html2canvas@1.4.1/dist/html2canvas.min.js"></script>
<script>
const state = {
  images: [],          // { id, file, name, dataUrl, annotations: [{x,y,text}] }
  currentImageId: null,
  annotations: [],
  canvas: null,
  ctx: null,
  nextId: 1,
};

const canvasEl = document.getElementById('canvas');
const ctx = canvasEl.getContext('2d');
state.canvas = canvasEl;
state.ctx = ctx;

function loadImage(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => resolve(img);
      img.onerror = reject;
      img.src = e.target.result;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

function generateId() {
  return 'id_' + state.nextId++;
}

function addImage(file) {
  return loadImage(file).then((img) => {
    const id = generateId();
    const name = file.name || 'image_' + Date.now();
    const dataUrl = img.src;
    state.images.push({ id, file, name, dataUrl, annotations: [] });
    renderImageList();
    renderImageGrid();
    renderAnnotationPanel();
    return id;
  });
}

function renderImageList() {
  const list = document.getElementById('imageList');
  list.innerHTML = '';
  state.images.forEach((img) => {
    const li = document.createElement('div');
    li.className = 'image-item' + (state.currentImageId === img.id ? ' selected' : '');
    li.innerHTML = `
      <img src="${img.dataUrl}" alt="${img.name}" loading="lazy">
      <div class="image-meta">
        <strong>${img.name}</strong>
        <span class="text-muted">(${img.annotations.length} annotations)</span>
      </div>
    `;
    li.addEventListener('click', () => selectImage(img.id));
    list.appendChild(li);
  });
}

function renderImageGrid() {
  const grid = document.getElementById('imageGrid');
  grid.innerHTML = '';
  state.images.forEach((img) => {
    const item = document.createElement('div');
    item.className = 'image-item' + (state.currentImageId === img.id ? ' selected' : '');
    item.innerHTML = `
      <img src="${img.dataUrl}" alt="${img.name}" loading="lazy">
      <div class="image-meta">
        <strong>${img.name}</strong>
        <span class="text-muted">(${img.annotations.length} annotations)</span>
      </div>
    `;
    item.addEventListener('click', () => selectImage(img.id));
    grid.appendChild(item);
  });
}

function renderAnnotationPanel() {
  const panel = document.getElementById('annotationPanel');
  const current = state.images.find((i) => i.id === state.currentImageId);
  if (!current) {
    panel.innerHTML = '<p class="text-muted">No image selected. Add an image to begin.</p>';
    return;
  }
  panel.innerHTML = '';
  current.annotations.forEach((a, idx) => {
    const row = document.createElement('div');
    row.className = 'annotation-input';
    row.innerHTML = `
      <input type="text" value="${a.text}" placeholder="Annotation text" data-index="${idx}">
      <button type="button" class="btn btn-danger btn-sm remove" data-remove="${idx}">Remove</button>
    `;
    row.addEventListener('click', (e) => {
      if (e.target.classList.contains('remove')) {
        removeAnnotation(idx);
      }
    });
    panel.appendChild(row);
  });
}

function selectImage(id) {
  state.currentImageId = id;
  renderImageList();
  renderImageGrid();
  renderAnnotationPanel();
  renderCanvas();
}

function removeAnnotation(idx) {
  const current = state.images.find((i) => i.id === state.currentImageId);
  if (!current) return;
  current.annotations.splice(idx, 1);
  renderAnnotationPanel();
  renderCanvas();
}

function addAnnotation(text) {
  if (!state.currentImageId) return;
  const current = state.images.find((i) => i.id === state.currentImageId);
  if (!current) return;
  current.annotations.push({ x: 50, y: 50, text });
  renderAnnotationPanel();
  renderCanvas();
}

function renderCanvas() {
  const current = state.images.find((i) => i.id === state.currentImageId);
  if (!current) {
    ctx.clearRect(0, 0, canvasEl.width, canvasEl.height);
    return;
  }
  ctx.clearRect(0, 0, canvasEl.width, canvasEl.height);
  const img = new Image();
  img.onload = () => {
    ctx.drawImage(img, 0, 0, canvasEl.width, canvasEl.height);
    current.annotations.forEach((a) => {
      ctx.fillStyle = '#007bff';
      ctx.strokeStyle = 'rgba(255,255,255,.8)';
      ctx.font = '14px sans-serif';
      ctx.textAlign = 'left';
      ctx.textBaseline = 'top';
      ctx.lineWidth = 1;
      ctx.strokeText(a.text, a.x, a.y);
      ctx.fillText(a.text, a.x, a.y);
    });
  };
  img.src = current.dataUrl;
}

document.getElementById('browseBtn').addEventListener('click', () => {
  document.getElementById('fileInput').click();
});

document.getElementById('fileInput').addEventListener('change', (e) => {
  const files = Array.from(e.target.files);
  files.forEach((file) => addImage(file));
  e.target.value = '';
});

document.getElementById('dropZone').addEventListener('dragover', (e) => {
  e.preventDefault();
  e.dataTransfer.dropEffect = 'copy';
  document.getElementById('dropZone').classList.add('dragover');
});
document.getElementById('dropZone').addEventListener('dragleave', () => {
  document.getElementById('dropZone').classList.remove('dragover');
});
document.getElementById('dropZone').addEventListener('drop', (e) => {
  e.preventDefault();
  document.getElementById('dropZone').classList.remove('dragover');
  const files = Array.from(e.dataTransfer.files);
  files.forEach((file) => addImage(file));
});

document.getElementById('addAnnotationBtn').addEventListener('click', () => {
  const text = document.getElementById('annotationText').value.trim();
  if (text) addAnnotation(text);
});
document.getElementById('addAnnotationBtn2').addEventListener('click', () => {
  const text = document.getElementById('annotationText2').value.trim();
  if (text) addAnnotation(text);
});
document.getElementById('addAnnotationBtn3').addEventListener('click', () => {
  const text = document.getElementById('annotationText3').value.trim();
  if (text) addAnnotation(text);
});
document.getElementById('addAnnotationBtn4').addEventListener('click', () => {
  const text = document.getElementById('annotationText4').value.trim();
  if (text) addAnnotation(text);
});

document.getElementById('clearCanvasBtn').addEventListener('click', () => {
  if (!state.currentImageId) return;
  const current = state.images.find((i) => i.id === state.currentImageId);
  if (!current) return;
  current.annotations = [];
  renderAnnotationPanel();
  renderCanvas();
});

document.getElementById('downloadBtn').addEventListener('click', () => {
  if (!state.currentImageId) return;
  const current = state.images.find((i) => i.id === state.currentImageId);
  if (!current) return;
  const link = document.createElement('a');
  link.download = current.name.replace(/\.[^.]+$/, '') + '_annotated.png';
  link.href = canvasEl.toDataURL('image/png');
  link.click();
});

document.getElementById('batchDownloadBtn').addEventListener('click', () => {
  if (state.images.length === 0) {
    alert('No images to download.');
    return;
  }
  state.images.forEach((img) => {
    const link = document.createElement('a');
    link.download = img.name.replace(/\.[^.]+$/, '') + '_annotated.png';
    link.href = canvasEl.toDataURL('image/png');
    link.click();
  });
  alert('Batch download started.');
});

// Initialize
renderImageList();
renderImageGrid();
renderAnnotationPanel();
renderCanvas();
</script>
</body>
</html>
```

Creating a professional **video subtitle adding tool** with timeline markers, customizable fonts/colors/positions, and embedded subtitle export requires a combination of a frontend (HTML/CSS/JS) for the UI and a backend (Node.js) for handling uploads, processing, and exporting. Below is a **complete working prototype** using modern web technologies. The tool will:

- Allow users to upload a video.
- Add multiple captions with timeline markers (start/end time).
- Customize font, color, position, and background opacity.
- Render a preview with semi-transparent background boxes.
- Export the final video with embedded subtitles (WebVTT format + FFmpeg overlay).

---

## ✅ Tech Stack

- **Frontend**: HTML, CSS, JavaScript (Canvas + Web Audio for seeking)
- **Backend**: Node.js + Express + FFmpeg (via `fluent-ffmpeg`)
- **Storage**: Local (in-browser) for simplicity; production would use S3/cloud.
- **FFmpeg**: Used for overlaying subtitles on the video.

