### `server.js`

```javascript
const express = require('express');
const multer = require('multer');
const path = require('path');
const { v4: uuidv4 } = require('uuid');
const ffmpeg = require('fluent-ffmpeg');
const app = express();
const PORT = process.env.PORT || 3000;

// Serve static files (for uploaded videos)
app.use('/uploads', express.static('uploads'));
app.use('/subtitles', express.static('subtitles'));

// Multer storage
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, 'uploads/');
  },
  filename: (req, file, cb) => {
    cb(null, `${uuidv4()}-${file.originalname}`);
  }
});

const upload = multer({ storage });

// Upload endpoint
app.post('/api/upload', upload.single('video'), (req, res) => {
  if (!req.file) return res.status(400).json({ error: 'No file uploaded' });
  res.json({
    success: true,
    url: `/uploads/${req.file.filename}`,
    id: req.file.filename.replace(/\.[^.]+$/, '')
  });
});

// Generate WebVTT from subtitles array
function generateWebVTT(subtitles, id) {
  const entries = subtitles.map((s, i) => {
    const start = s.start;
    const end = s.end;
    const text = s.text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    return `    ${String(i + 1).padStart(3, '0')}\n    ${formatTime(start)} --> ${formatTime(end)}\n    ${text}\n`;
  }).join('\n\n');
  return `WEBVTT\n\n${entries}`;
}

function formatTime(sec) {
  const h = Math.floor(sec / 3600);
  const m = Math.floor((sec % 3600) / 60);
  const s = Math.floor(sec % 60);
  const ms = Math.floor((sec - Math.floor(sec)) * 100);
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}.${String(ms).padStart(2, '0')}`;
}

// Export with embedded subtitles
app.post('/api/export', (req, res) => {
  const { videoUrl, subtitles, outputName = 'output' } = req.body;
  if (!videoUrl || !subtitles || !subtitles.length) return res.status(400).json({ error: 'Missing video or subtitles' });

  const videoPath = path.resolve('uploads', path.basename(videoUrl));
  const outPath = path.resolve('subtitles', `${outputName}.mp4`);

  // Generate WebVTT
  const vttContent = generateWebVTT(subtitles, path.basename(videoUrl, path.extname(videoUrl)));
  const vttPath = path.resolve('subtitles', `${outputName}.vtt`);

  fs.writeFileSync(vttPath, vttContent, 'utf-8');

  ffmpeg(videoPath)
    .outputOptions([`-vf "subtitles=${vttPath}"`])
    .output(outPath)
    .on('end', () => {
      res.json({ success: true, url: `/subtitles/${path.basename(outPath)}` });
    })
    .on('error', (err) => {
      console.error(err);
      res.status(500).json({ error: err.message });
    })
    .run();
});

app.get('/api/preview', (req, res) => {
  const { videoUrl, subtitles } = req.query;
  if (!videoUrl || !subtitles) return res.status(400).json({ error: 'Missing video or subtitles' });
  // Simple: return a static preview image (not real-time rendering)
  res.json({ message: 'Preview endpoint — would render with Canvas here.' });
});

app.get('/', (req, res) => res.sendFile(__dirname + '/index.html'));

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
