### `script.js`

```javascript
(() => {
  'use strict';

  const $ = (id) => document.getElementById(id);
  const uploadForm = $('uploadForm');
  const videoInput = $('videoInput');
  const browseBtn = $('browseBtn');
  const uploadResult = $('uploadResult');
  const subtitleList = $('subtitleList');
  const subtitleText = $('subtitleText');
  const subtitleStart = $('subtitleStart');
  const subtitleEnd = $('subtitleEnd');
  const subtitleFont = $('subtitleFont');
  const subtitleColor = $('subtitleColor');
  const subtitleBg = $('subtitleBg');
  const subtitleOpacity = $('subtitleOpacity');
  const opacityVal = $('opacityVal');
  const subtitlePos = $('subtitlePos');
  const addBtn = $('addBtn');
  const clearBtn = $('clearBtn');
  const previewVideo = $('previewVideo');
  const previewCanvas = $('previewCanvas');
  const exportForm = $('exportForm');
  const exportName = $('exportName');
  const exportBtn = $('exportBtn');

  const state = {
    videoUrl: null,
    subtitles: [],
    previewCtx: null
  };

  // ---------- Upload ----------
  browseBtn.addEventListener('click', () => videoInput.click());
  uploadForm.addEventListener('submit', (e) => {
    e.preventDefault();
    const file = videoInput.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      const url = URL.createObjectURL(file);
      state.videoUrl = url;
      uploadResult.innerHTML = `
        <strong>Video uploaded successfully!</strong>
        <div class="url">${url}</div>
        <button type="button" onclick="window.location.reload()">Upload another</button>
      `;
    };
    reader.readAsArrayBuffer(file);
  });

  // ---------- Subtitles ----------
  addBtn.addEventListener('click', () => {
    const text = subtitleText.value.trim();
    const start = parseFloat(subtitleStart.value);
    const end = parseFloat(subtitleEnd.value);
    const font = subtitleFont.value;
    const color = subtitleColor.value;
    const bg = subtitleBg.value;
    const opacity = parseInt(subtitleOpacity.value, 10) / 100;
    const pos = subtitlePos.value;

    if (!text || isNaN(start) || isNaN(end) || start >= end) return;

    state.subtitles.push({
      id: Date.now() + Math.random(),
      text,
      start,
      end,
      font,
      color,
      bg,
      opacity,
      pos
    });

    renderSubtitleList();
    subtitleText.value = '';
    subtitleStart.value = 0;
    subtitleEnd.value = 3;
  });

  clearBtn.addEventListener('click', () => {
    state.subtitles = [];
    renderSubtitleList();
  });

  function renderSubtitleList() {
    subtitleList.innerHTML = '';
    state.subtitles.forEach((s) => {
      const item = document.createElement('div');
      item.className = 'subtitle-item';
      item.innerHTML = `
        <div class="subtitle-text">${escapeHtml(s.text)}</div>
        <div class="subtitle-meta">
          <span>⏱ ${formatTime(s.start)} → ${formatTime(s.end)}</span>
          <span>🎨 ${s.font}</span>
          <span>📍 ${s.pos}</span>
          <span class="del" title="Delete" data-id="${s.id}">×</span>
        </div>
      `;
      item.querySelector('.del').addEventListener('click', () => {
        state.subtitles = state.subtitles.filter((x) => x.id !== s.id);
        renderSubtitleList();
      });
      subtitleList.appendChild(item);
    });
  }

  function escapeHtml(str) {
    return String(str).replace(/[&<>"']/g, (c) => ({
      '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    }[c]));
  }

  function formatTime(sec) {
    const h = Math.floor(sec / 3600);
    const m = Math.floor((sec % 3600) / 60);
    const s = Math.floor(sec % 60);
    const ms = Math.floor((sec - Math.floor(sec)) * 100);
    return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}.${String(ms).padStart(2, '0')}`;
  }

  subtitleOpacity.addEventListener('input', () => {
    opacityVal.textContent = `${subtitleOpacity.value}%`;
  });

  // ---------- Preview ----------
  function setupPreview() {
    if (!state.videoUrl) return;
    previewVideo.src = state.videoUrl;
    previewVideo.load();
    previewVideo.addEventListener('timeupdate', drawCanvas);
    previewVideo.addEventListener('seeked', drawCanvas);
    previewVideo.addEventListener('loadedmetadata', () => {
      previewCanvas.classList.remove('hidden');
      drawCanvas();
    });
    previewVideo.addEventListener('error', () => {
      previewCanvas.classList.add('hidden');
    });
  }

  function drawCanvas() {
    if (!state.previewCtx) return;
    const dpr = window.devicePixelRatio || 1;
    const rect = previewCanvas.getBoundingClientRect();
    const w = rect.width;
    const h = rect.height;
    state.previewCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
    state.previewCtx.clearRect(0, 0, w, h);

    const time = previewVideo.currentTime || 0;
    const subs = state.subtitles.filter((s) => s.start <= time && time <= s.end);

    subs.forEach((s) => {
      const rect = computeRect(s, w, h);
      if (!rect) return;
      const bgAlpha = s.opacity * 0.6;
      state.previewCtx.fillStyle = `rgba(0,0,0,${bgAlpha})`;
      state.previewCtx.fillRect(rect.x, rect.y, rect.w, rect.h);

      state.previewCtx.fillStyle = s.color;
      state.previewCtx.font = `bold ${s.font}`;
      state.previewCtx.textBaseline = 'top';
      state.previewCtx.textAlign = 'left';
      state.previewCtx.fillText(s.text, rect.x, rect.y);
    });
  }

  function computeRect(s, w, h) {
    const pos = s.pos;
    const pad = 10;
    let x, y, w2, h2;

    if (pos === 'top-left') { x = pad; y = pad; w2 = w - pad; h2 = h * 0.08; }
    else if (pos === 'top-center') { x = w / 2 - w2 / 2; y = pad; w2 = w - pad; h2 = h * 0.08; }
    else if (pos === 'top-right') { x = w - pad - w2; y = pad; w2 = w - pad; h2 = h * 0.08; }
    else if (pos === 'center') { x = w / 2 - w2 / 2; y = h / 2 - h2 / 2; w2 = w - pad; h2 = h * 0.08; }
    else if (pos === 'bottom-left') { x = pad; y = h - pad - h2; w2 = w - pad; h2 = h * 0.08; }
    else if (pos === 'bottom-center') { x = w / 2 - w2 / 2; y = h - pad - h2; w2 = w - pad; h2 = h * 0.08; }
    else if (pos === 'bottom-right') { x = w - pad - w2; y = h - pad - h2; w2 = w - pad; h2 = h * 0.08; }

    return { x, y, w: w2, h: h2 };
  }

  previewCanvas.addEventListener('click', (e) => {
    if (!state.videoUrl) return;
    const rect = previewCanvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const time = previewVideo.currentTime || 0;
    const subs = state.subtitles.filter((s) => s.start <= time && time <= s.end);
    subs.forEach((s) => {
      const r = computeRect(s, rect.width, rect.height);
      if (x >= r.x && x <= r.x + r.w && y >= r.y && y <= r.y + r.h) {
        alert(`Subtitle: "${s.text}"\nStart: ${formatTime(s.start)}\nEnd: ${formatTime(s.end)}`);
      }
    });
  });

  // ---------- Export ----------
  exportBtn.addEventListener('click', () => {
    if (!state.videoUrl || !state.subtitles.length) {
      alert('Upload a video and add subtitles first.');
      return;
    }
    const name = exportName.value.trim() || 'output';
    const url = state.videoUrl;
    const subs = state.subtitles;

    const data = {
      videoUrl: url,
      subtitles: subs,
      outputName: name
    };

    // Simulate async call to backend
    fetch('/api/export', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data)
    })
    .then((r) => r.json())
    .then((res) => {
      if (res.success) {
        alert(`Exported: ${res.url}`);
        window.open(res.url, '_blank');
      } else {
        alert('Export failed: ' + res.error);
      }
    })
    .catch((err) => {
      alert('Export failed: ' + err.message);
    });
  });

  // ---------- Resize ----------
  window.addEventListener('resize', () => {
    if (state.previewCtx) drawCanvas();
  });

  // ---------- Init ----------
  previewCanvas.addEventListener('click', (e) => {
    if (!state.videoUrl) return;
    const rect = previewCanvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const time = previewVideo.currentTime || 0;
    const subs = state.subtitles.filter((s) => s.start <= time && time <= s.end);
    subs.forEach((s) => {
      const r = computeRect(s, rect.width, rect.height);
      if (x >= r.x && x <= r.x + r.w && y >= r.y && y <= r.y + r.h) {
        alert(`Subtitle: "${s.text}"\nStart: ${formatTime(s.start)}\nEnd: ${formatTime(s.end)}`);
      }
    });
  });

  // Render canvas on load
  window.addEventListener('load', () => {
    if (state.videoUrl) setupPreview();
  });
})();
