<script>
  const FFMPEG = FFmpeg();
  const toast = document.getElementById('toast');
  const toastMsg = document.getElementById('toastMsg');
  const status = document.getElementById('status');
  const statusText = document.getElementById('statusText');
  const progressBar = document.getElementById('progressBar');

  let audioCtx = null;
  let currentAudio = null;
  let currentBlob = null;
  let currentFileName = '';

  // Initialize FFmpeg
  async function initFFmpeg() {
    try {
      await FFMPEG.load();
      await FFMPEG.run('-version');
      console.log('FFmpeg initialized');
    } catch (e) {
      showToast('error', 'FFmpeg failed to load', e.message);
    }
  }

  // Toast
  function showToast(type, msg, detail = '') {
    toastMsg.textContent = msg;
    toast.className = 'toast show ' + type;
    const icon = type === 'success' ? 'fa-circle-check' : 'fa-circle-exclamation';
    toast.querySelector('i').className = 'fa-solid ' + icon;
    clearTimeout(showToast._t);
    showToast._t = setTimeout(() => {
      toast.className = 'toast ' + type;
    }, 3000);
  }

  // Audio preview
  function updatePreview() {
    const info = document.getElementById('audioInfo');
    const player = document.getElementById('audioPlayer');
    if (!currentAudio) {
      info.textContent = 'No file selected';
      player.src = '';
      return;
    }
    const name = currentFileName || 'audio.mp3';
    info.textContent = `File: ${name} · Duration: ${currentAudio.duration.toFixed(2)}s`;
    player.src = URL.createObjectURL(currentAudio);
  }

  // File handling
  async function handleAudioFile(file) {
    if (!file) return;
    if (!file.type.startsWith('audio/')) {
      showToast('error', 'Invalid file type', 'Please select an audio file.');
      return;
    }
    const arrayBuffer = await file.arrayBuffer();
    const audio = new Audio();
    audio.src = URL.createObjectURL(new Blob([arrayBuffer], { type: file.type }));
    currentAudio = audio;
    currentFileName = file.name;
    currentBlob = new Blob([arrayBuffer], { type: file.type });
    updatePreview();
    showToast('success', 'File loaded', file.name);
  }

  document.getElementById('audioFile').addEventListener('change', (e) => {
    const file = e.target.files[0];
    if (file) handleAudioFile(file);
  });

  // Watermark options
  const typeSelect = document.getElementById('watermarkType');
  const textFields = document.getElementById('textFields');
  const audioFields = document.getElementById('audioFields');
  const customFields = document.getElementById('customFields');

  typeSelect.addEventListener('change', () => {
    if (typeSelect.value === 'text') {
      textFields.style.display = '';
      audioFields.style.display = 'none';
      customFields.style.display = '';
    } else {
      textFields.style.display = 'none';
      audioFields.style.display = '';
      customFields.style.display = '';
    }
  });

  document.getElementById('customTime').addEventListener('input', () => {
    const val = document.getElementById('customTime').value;
    document.getElementById('customTimeVal').textContent = val + '.0s';
  });

  document.getElementById('volume').addEventListener('input', () => {
    const val = document.getElementById('volume').value;
    document.getElementById('volumeVal').textContent = val + '%';
  });

  // Start processing
  async function startProcessing() {
    const file = document.getElementById('audioFile').files[0];
    if (!file) {
      showToast('error', 'No audio file', 'Please upload an audio file first.');
      return;
    }
    if (!currentAudio) {
      showToast('error', 'Audio not ready', 'Please wait for the audio to load.');
      return;
    }
    if (typeSelect.value === 'text' && !document.getElementById('watermarkText').value.trim()) {
      showToast('error', 'No watermark text', 'Enter a watermark text.');
      return;
    }
    if (typeSelect.value === 'audio') {
      const wf = document.getElementById('watermarkAudio').files[0];
      if (!wf) {
        showToast('error', 'No watermark audio', 'Select an embedded audio file.');
        return;
      }
    }

    status.className = 'status';
    statusText.textContent = 'Processing...';
    progressBar.style.width = '0%';

    // Generate watermark audio (text to audio)
    let watermarkAudioBlob = null;
    if (typeSelect.value === 'text') {
      watermarkAudioBlob = await generateTextWatermark();
    } else {
      watermarkAudioBlob = await handleWatermarkAudio();
    }

    // Merge audio
    const mergedBlob = await mergeAudio(currentBlob, watermarkAudioBlob);

    // Save
    const saveBlob = await createSaveBlob(mergedBlob);
    await saveFile(saveBlob);

    // Reset progress
    progressBar.style.width = '0%';
    statusText.textContent = 'Done';
    showToast('success', 'Watermark applied', 'File saved to your device.');
  }

  function generateTextWatermark() {
    return new Promise((resolve) => {
      const text = document.getElementById('watermarkText').value.trim();
      const volume = parseFloat(document.getElementById('volume').value) / 100;
      const placement = document.getElementById('watermarkPlacement').value;
      const customTime = parseFloat(document.getElementById('customTime').value);

      const ctx = new (window.AudioContext || window.webkitAudioContext)();
      const bufferSize = ctx.sampleRate * 3;
      const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
      const data = buffer.getChannelData(0);
      const now = ctx.currentTime;

      const speak = new SpeechSynthesisUtterance(text);
      speak.rate = 0.6;
      speak.pitch = 1;
      speak.volume = volume;

      let startTime = 0;
      if (placement === 'custom') startTime = customTime;
      else if (placement === 'middle') startTime = currentAudio.duration / 3;
      else if (placement === 'end') startTime = currentAudio.duration;

      speak.startTime = startTime;

      speak.onend = () => {
        resolve(speak.audioData);
      };
      speak.onerror = () => {
        showToast('error', 'Speech synthesis failed', 'Try a different browser or text.');
        resolve(null);
      };
    });
  }

  function handleWatermarkAudio() {
    return new Promise((resolve) => {
      const file = document.getElementById('watermarkAudio').files[0];
      if (!file) return resolve(null);
      const reader = new FileReader();
      reader.onload = () => {
        const audio = new Audio();
        audio.src = reader.result;
        audio.addEventListener('loadedmetadata', () => {
          const ctx = new (window.AudioContext || window.webkitAudioContext)();
          const source = ctx.createBufferSource();
          source.buffer = audio.buffer;
          const gain = ctx.createGain();
          gain.gain.value = parseFloat(document.getElementById('volume').value) / 100;
          source.connect(gain).connect(ctx.destination);
          source.start();
          audio.addEventListener('ended', () => resolve(audio.buffer));
        });
      };
      reader.readAsArrayBuffer(file);
    });
  }

  async function mergeAudio(mainBlob, watermarkBlob) {
    return new Promise((resolve) => {
      if (!mainBlob || !watermarkBlob) return resolve(mainBlob);
      const reader = new FileReader();
      reader.onload = () => {
        const ctx = new (window.AudioContext || window.webkitAudioContext)();
        const mainBuffer = ctx.createBuffer(reader.result);
        const mainDuration = mainBuffer.duration;

        const waterBuffer = ctx.createBuffer(watermarkBlob);
        const waterDuration = waterBuffer.duration;

        const totalDuration = mainDuration + waterDuration;
        const mergedBuffer = ctx.createBuffer(mainBuffer.numberOfChannels, Math.ceil(totalDuration * ctx.sampleRate), mainBuffer.sampleRate);

        const mainData = mainBuffer.getChannelData(0);
        const waterData = waterBuffer.getChannelData(0);

        const placement = document.getElementById('watermarkPlacement').value;
        let startOffset = 0;
        if (placement === 'middle') startOffset = mainDuration / 3;
        else if (placement === 'end') startOffset = mainDuration;

        const waterStart = startOffset;
        const waterEnd = waterStart + waterDuration;

        const writeMain = (t) => {
          const i = Math.floor(t * ctx.sampleRate);
          if (i < mainData.length) mergedBuffer.getChannelData(0)[i] = mainData[i];
        };
        const writeWater = (t) => {
          const i = Math.floor((t - waterStart) * ctx.sampleRate);
          if (i < waterData.length) mergedBuffer.getChannelData(0)[i] = waterData[i];
        };

        const now = ctx.currentTime;
        const end = now + totalDuration;

        const mainSource = ctx.createBufferSource();
        mainSource.buffer = mergedBuffer;
        mainSource.start(now);
        mainSource.stop(now + totalDuration);

        const gain = ctx.createGain();
        gain.gain.value = 1;
        mainSource.connect(gain).connect(ctx.destination);

        resolve(mergedBuffer);
      };
      reader.readAsArrayBuffer(mainBlob);
    });
  }

  async function createSaveBlob(mergedBuffer) {
    const ctx = new (window.AudioContext || window.webkitAudioContext)();
    const audioData = ctx.createBuffer(mergedBuffer);
    const arrayBuffer = await audioData.arrayBuffer();
    return new Blob([arrayBuffer], { type: 'audio/mpeg' });
  }

  async function saveFile(blob) {
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = currentFileName.replace(/\.[^.]+$/, '') + '_watermarked.mp3';
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }

  // UI wiring
  document.getElementById('startBtn').addEventListener('click', startProcessing);
  document.getElementById('resetBtn').addEventListener('click', () => {
    document.getElementById('audioFile').value = '';
    document.getElementById('watermarkText').value = '© Watermark 2025';
    document.getElementById('watermarkAudio').value = '';
    currentAudio = null;
    currentBlob = null;
    currentFileName = '';
    updatePreview();
    showToast('info', 'Reset', 'All fields cleared.');
  });

  // Init
  initFFmpeg();
  updatePreview();
</script>
</body>
</html>
```

Here is a **professional audio segmentation labeling tool** built with **React**, **Web Audio API**, **Web Speech API (for speech-to-text optional)**, and **FileReader** for audio upload. The tool lets users:

- Upload an audio file.
- Visualize the waveform.
- Click/tap on the waveform to add or edit labels with text and time ranges.
- Export a JSON file containing all labels.

