import React from 'react';
import { useAudioStore } from '../store/audioStore';
import { AudioFile } from '../types';

interface HeaderProps {
  audioFile: AudioFile | null;
}

export const Header: React.FC<HeaderProps> = ({ audioFile }) => {
  const { labels, addLabel, updateLabel, deleteLabel, clearLabels, importLabels, exportLabels } = useAudioStore();

  const handleAddLabel = () => {
    if (!audioFile) return;
    const newLabel: Label = {
      id: crypto.randomUUID(),
      text: '',
      startTime: 0,
      endTime: audioFile.duration,
      color: '#4f46e5',
    };
    addLabel(newLabel);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      try {
        const data = JSON.parse(reader.result as string);
        if (Array.isArray(data) && data.length) {
          importLabels(data);
        }
      } catch (err) {
        console.error(err);
      }
    };
    reader.readAsText(file);
  };

  const handleExport = () => {
    if (!audioFile) return;
    const json = { audioFileId: audioFile.id, labels };
    const blob = new Blob([JSON.stringify(json, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `labels-${audioFile.name.replace(/\.[^.]+$/, '')}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <header className="header">
      <div className="header-left">
        <h1>Audio Labeler</h1>
        <p className="subtitle">Segment and label audio clips</p>
      </div>
      <div className="header-right">
