## 📄 `components/LabelEditor.tsx`

```tsx
import React from 'react';
import { Label } from '../types';

interface LabelEditorProps {
  label: Label;
  audioDuration: number;
  onMove: (id: string, startTime: number, endTime: number) => void;
  onEdit: (id: string, text: string) => void;
  onDelete: (id: string) => void;
  editingId: string | null;
  setEditingId: (id: string | null) => void;
  editText: string;
  setEditText: (text: string) => void;
}

export const LabelEditor: React.FC<LabelEditorProps> = ({
  label,
  audioDuration,
  onMove,
  onEdit,
  onDelete,
  editingId,
  setEditingId,
  editText,
  setEditText,
}) => {
  const handleMouseDown = (e: React.MouseEvent) => {
    e.stopPropagation();
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!editingId) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const percent = x / rect.width;
    const time = percent * audioDuration;
    if (time >= 0 && time <= audioDuration) {
      onMove(editingId, Math.max(0, time), label.endTime);
    }
  };

  const handleMouseUp = () => {
    setEditingId(null);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      onEdit(label.id, editText);
      setEditingId(null);
    }
  };

  const handleDelete = (e: React.MouseEvent) => {
    e.stopPropagation();
    onDelete(label.id);
  };

  return (
    <div
      className="label-editor"
      style={{
        left: `${(label.startTime / audioDuration) * 100}%`,
        width: `${((label.endTime - label.startTime) / audioDuration) * 100}%`,
        backgroundColor: label.color,
      }}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
      onKeyDown={handleKeyDown}
      tabIndex={0}
      role="button"
      aria-label={`Label: ${label.text}, ${label.startTime.toFixed(2)}s-${label.endTime.toFixed(2)}s`}
    >
      <div className="label-text" style={{ color: '#fff' }}>
        {editingId === label.id ? (
          <input
            type="text"
            value={editText}
            onChange={(e) => setEditText(e.target.value)}
            onBlur={() => onEdit(label.id, editText)}
            onKeyDown={(e) => {
              if (e.key === 'Enter') onEdit(label.id, editText);
            }}
            autoFocus
          />
        ) : (
          label.text
        )}
      </div>
      <button
        className="label-delete"
        onClick={handleDelete}
        aria-label="Delete label"
      >
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"></polyline><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"></path><path d="M10 11v6"></path><path d="M14 11v6"></path></svg>
      </button>
    </div>
  );
};
