## 📄 `components/Waveform.tsx`

```tsx
import React, { useRef, useEffect, useState } from 'react';
import { useAudioStore } from '../store/audioStore';
import { AudioFile } from '../types';

interface WaveformProps {
  audioFile: AudioFile;
  labels: Label[];
  onLabelMove: (id: string, startTime: number, endTime: number) => void;
  onLabelEdit: (id: string, text: string) => void;
  onLabelDelete: (id: string) => void;
}

export const Waveform: React.FC<WaveformProps> = ({
  audioFile,
  labels,
  onLabelMove,
  onLabelEdit,
  onLabelDelete,
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const [audioBuffer, setAudioBuffer] = useState<AudioBuffer | null>(null);
  const [canvasSize, setCanvasSize] = useState({ width: 0, height: 0 });
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);

  const handleFileLoad = async (file: File) => {
    try {
      const arrayBuffer = await file.arrayBuffer();
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const buffer = await ctx.decodeAudioData(arrayBuffer.slice(0));
      setAudioBuffer(buffer);
      audioCtxRef.current = ctx;
      setCanvasSize({ width: window.innerWidth, height: 240 });
    } catch (err) {
      console.error(err);
    }
  };

  const renderWaveform = () => {
    if (!audioBuffer || !canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const duration = audioBuffer.duration;
    const channels = audioBuffer.numberOfChannels;
    const sampleRate = audioBuffer.sampleRate;

    const width = canvasSize.width;
    const height = canvasSize.height;
    const barWidth = width / sampleRate;

    // Clear
    ctx.clearRect(0, 0, width, height);

    // Background
    ctx.fillStyle = '#0f172a';
    ctx.fillRect(0, 0, width, height);

    // Grid
    ctx.strokeStyle = 'rgba(255,255,255,0.06)';
    ctx.lineWidth = 1;
    const gridStep = Math.max(1, Math.floor(width / (duration * 2)));
    for (let i = 0; i < duration; i += gridStep) {
      ctx.beginPath();
      ctx.moveTo(i * sampleRate, 0);
      ctx.lineTo(i * sampleRate, height);
      ctx.stroke();
    }

    // Labels
    const labelBars: { x: number; y: number; h: number; color: string; text: string; id: string }[] = [];
    labels.forEach((label) => {
      const start = (label.startTime / duration) * sampleRate;
      const end = (label.endTime / duration) * sampleRate;
      const durationPx = (end - start) * barWidth;
      labelBars.push({
        x: start,
        y: height - 20,
        h: 20,
        color: label.color,
        text: label.text,
        id: label.id,
      });
    });

    // Sort by x
    labelBars.sort((a, b) => a.x - b.x);

    // Draw bars
    labelBars.forEach((bar) => {
      ctx.fillStyle = bar.color;
      ctx.fillRect(bar.x, bar.y, durationPx, bar.h);
    });

    // Playhead
    if (isPlaying && audioBuffer) {
      const playheadX = (currentTime / duration) * sampleRate;
      ctx.fillStyle = 'rgba(255,255,255,0.85)';
      ctx.fillRect(playheadX - 1, 0, 2, height);
    }
  };

  useEffect(() => {
    renderWaveform();
  }, [audioBuffer, canvasSize, labels, currentTime, isPlaying]);

  useEffect(() => {
    const handleResize = () => {
      setCanvasSize({ width: window.innerWidth, height: 240 });
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const play = () => {
    if (!audioBuffer || !audioCtxRef.current) return;
    const ctx = audioCtxRef.current;
    if (ctx.state === 'suspended') ctx.resume();
    const source = ctx.createBufferSource();
    source.buffer = audioBuffer;
    source.connect(ctx.destination);
    source.start(0);
    setIsPlaying(true);
    setCurrentTime(0);
    source.onended = () => {
      setIsPlaying(false);
      setCurrentTime(audioBuffer.duration);
    };
  };

  const stop = () => {
    if (!audioCtxRef.current) return;
    audioCtxRef.current.suspend();
    setIsPlaying(false);
    setCurrentTime(0);
  };

  return (
    <div className="waveform">
      <canvas
        ref={canvasRef}
        width={canvasSize.width}
        height={canvasSize.height}
        style={{ width: '100%', height: '100%', display: 'block' }}
      />
      <div className="waveform-controls">
        <button className="btn btn-ghost" onClick={play} disabled={isPlaying}>
          <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><polygon points="6 4 20 12 6 20 6 4"></polygon></svg>
          {isPlaying ? 'Pause' : 'Play'}
        </button>
        <span className="time-display">
          {currentTime.toFixed(2)} / {audioFile.duration.toFixed(2)}s
        </span>
      </div>
    </div>
  );
};
```

