## 📄 `store/audioStore.ts`

```typescript
import { create } from 'zustand';
import { Label, AudioFile } from '../types';

interface AudioStore {
  audioFile: AudioFile | null;
  labels: Label[];
  setAudioFile: (file: AudioFile) => void;
  addLabel: (label: Label) => void;
  updateLabel: (id: string, label: Partial<Label>) => void;
  deleteLabel: (id: string) => void;
  clearLabels: () => void;
  importLabels: (labels: Label[]) => void;
  exportLabels: () => void;
}

export const useAudioStore = create<AudioStore>((set, get) => ({
  audioFile: null,
  labels: [],
  setAudioFile: (file) => set({ audioFile: file }),
  addLabel: (label) => set((state) => {
    if (!state.audioFile) return state;
    const existing = state.labels.find((l) => l.id === label.id);
    if (existing) return { ...state, labels: state.labels.map((l) => l.id === label.id ? { ...existing, ...label } : l) };
    return { ...state, labels: [...state.labels, label] };
  }),
  updateLabel: (id, label) => set((state) => {
    if (!state.audioFile) return state;
    return { ...state, labels: state.labels.map((l) => l.id === id ? { ...l, ...label } : l) };
  }),
  deleteLabel: (id) => set((state) => {
    if (!state.audioFile) return state;
    return { ...state, labels: state.labels.filter((l) => l.id !== id) };
  }),
  clearLabels: () => set((state) => {
    if (!state.audioFile) return state;
    return { ...state, labels: [] };
  }),
  importLabels: (labels) => set((state) => {
    if (!state.audioFile) return state;
    return { ...state, labels };
  }),
  exportLabels: () => {
    const state = get();
    if (!state.audioFile) return;
    const json = { audioFileId: state.audioFile.id, labels: state.labels };
    const blob = new Blob([JSON.stringify(json, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `labels-${state.audioFile.name.replace(/\.[^.]+$/, '')}.json`;
    a.click();
    URL.revokeObjectURL(url);
  },
}));
