## 🎁 Bonus: Add Speech-to-Text Auto-labeling (optional)

You can optionally integrate the Web Speech API to auto-generate labels from the audio transcript. Add a button that triggers:

```typescript
// In App.tsx or a component
const handleAutoLabel = async () => {
  if (!audioFile || !audioBuffer) return;
  const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
  const source = ctx.createBufferSource();
  source.buffer = audioBuffer;
  const analyser = ctx.createAnalyser();
  analyser.fftSize = 2048;
  source.connect(analyser);
  analyser.connect(ctx.destination);
  source.start(0);

  const recognition = new (window.SpeechRecognition || (window as any).webkitSpeechRecognition)();
  recognition.lang = 'en-US';
  recognition.interimResults = false;
  recognition.maxAlternatives = 1;

  const results: string[] = [];
  recognition.onresult = (e) => {
    const transcript = e.results[0][0].transcript;
    results.push(transcript);
  };

  recognition.onerror = () => {
    console.log('Recognition error');
  };

  setTimeout(() => {
    recognition.stop();
    source.onended = () => {
      // Create labels from results
      results.forEach((text, i) => {
        const start = i * 1.5;
        const end = start + 1.5;
        addLabel({
          id: crypto.randomUUID(),
          text,
          startTime: start,
          endTime: end,
          color: '#f472b6',
        });
      });
    };
  }, 5000);
};
```

