## 📄 `app.py`

```python
from flask import Flask, render_template, request, redirect, url_for, flash
from flask_sqlalchemy import SQLAlchemy
from datetime import datetime

app = Flask(__name__)
app.config['SECRET_KEY'] = 'your-secret-key-here'
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///inventory.db'
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False

db = SQLAlchemy(app)

class Product(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False)
    price = db.Column(db.Float, nullable=False)
    quantity = db.Column(db.Integer, nullable=False)
    threshold = db.Column(db.Integer, nullable=False, default=10)
    created_at = db.Column(db.DateTime, default=datetime.utcnow)
    updated_at = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

    def __repr__(self):
        return f'<Product {self.name}>'

@app.route('/')
def index():
    products = Product.query.all()
    low_stock = [p for p in products if p.quantity <= p.threshold]
    return render_template('index.html', products=products, low_stock=low_stock)

@app.route('/add', methods=['GET', 'POST'])
def add():
    if request.method == 'POST':
        name = request.form.get('name').strip()
        price = float(request.form.get('price'))
        quantity = int(request.form.get('quantity'))
        threshold = int(request.form.get('threshold', 10))
        if not name:
            flash('Product name is required.', 'danger')
        else:
            product = Product(name=name, price=price, quantity=quantity, threshold=threshold)
            db.session.add(product)
            db.session.commit()
            flash('Product added successfully!', 'success')
            return redirect(url_for('index'))
    return render_template('add.html')

@app.route('/edit/<int:id>', methods=['GET', 'POST'])
def edit(id):
    product = Product.query.get_or_404(id)
    if request.method == 'POST':
        product.name = request.form.get('name').strip()
        product.price = float(request.form.get('price'))
        product.quantity = int(request.form.get('quantity'))
        product.threshold = int(request.form.get('threshold', 10))
        db.session.commit()
        flash('Product updated successfully!', 'success')
        return redirect(url_for('index'))
    return render_template('edit.html', product=product)

@app.route('/delete/<int:id>')
def delete(id):
    product = Product.query.get_or_404(id)
    db.session.delete(product)
    db.session.commit()
    flash('Product deleted.', 'info')
    return redirect(url_for('index'))

@app.route('/alert')
def alert():
    products = Product.query.all()
    low_stock = [p for p in products if p.quantity <= p.threshold]
    return render_template('alert.html', low_stock=low_stock)

if __name__ == '__main__':
    with app.app_context():
        db.create_all()
    app.run(debug=True)
```

