```python
from datetime import datetime, timedelta
from typing import List, Dict, Optional
import uuid
import json
import os

# ---------- Data Models ----------
class Device:
    def __init__(self, id: str, name: str, category: str, register_date: datetime, cycle_type: str, cycle_value: int, next_maintenance: datetime):
        self.id = id
        self.name = name
        self.category = category
        self.register_date = register_date
        self.cycle_type = cycle_type  # "hours" | "days"
        self.cycle_value = cycle_value
        self.next_maintenance = next_maintenance
        self.status = self._calculate_status()
        self.history: List[MaintenanceRecord] = []

    def _calculate_status(self) -> str:
        """Calculate maintenance status based on cycle type and current time."""
        now = datetime.now()
        if self.cycle_type == "hours":
            hours_since_register = (now - self.register_date).total_seconds() / 3600
            if hours_since_register >= self.cycle_value:
                days_overdue = max(0, (hours_since_register - self.cycle_value) / 24)
                if days_overdue < 7:
                    return "yellow"
                return "red"
            return "green"
        else:  # days
            days_since_register = (now - self.register_date).days
            if days_since_register >= self.cycle_value:
                days_overdue = max(0, days_since_register - self.cycle_value)
                if days_overdue < 7:
                    return "yellow"
                return "red"
            return "green"

    def update_status(self):
        """Update status when device info changes."""
        self.status = self._calculate_status()

    def add_maintenance(self, record: MaintenanceRecord):
        """Add a maintenance record."""
        self.history.append(record)
        # Recalculate next maintenance based on cycle
        if self.cycle_type == "hours":
            self.next_maintenance = self.register_date + timedelta(hours=self.cycle_value)
        else:
            self.next_maintenance = self.register_date + timedelta(days=self.cycle_value)
        self.update_status()

    def get_maintenance_summary(self) -> Dict:
        """Get summary for display."""
        return {
            "id": self.id,
            "name": self.name,
            "category": self.category,
            "status": self.status,
            "next_maintenance": self.next_maintenance.strftime("%Y-%m-%d %H:%M"),
            "history_count": len(self.history),
            "cycle_type": self.cycle_type,
            "cycle_value": self.cycle_value,
            "register_date": self.register_date.strftime("%Y-%m-%d"),
        }

    def get_history_summary(self) -> List[Dict]:
        """Get summary of maintenance history."""
        return [
            {
                "date": r.date.strftime("%Y-%m-%d %H:%M"),
                "personnel": r.personnel,
                "consumables": r.consumables,
                "notes": r.notes,
            }
            for r in sorted(self.history, key=lambda x: x.date, reverse=True)
        ]


class MaintenanceRecord:
    def __init__(self, id: str, device_id: str, date: datetime, personnel: str, consumables: List[str], notes: str = ""):
        self.id = id
        self.device_id = device_id
        self.date = date
        self.personnel = personnel
        self.consumables = consumables
        self.notes = notes


# ---------- Persistence ----------
class Persistence:
    """Simple JSON-based persistence."""
    FILE = "devices.json"

    @staticmethod
    def load() -> List[Device]:
        try:
            if os.path.exists(Persistence.FILE):
                with open(Persistence.FILE, "r", encoding="utf-8") as f:
                    data = json.load(f)
                    return [Device(**d) for d in data]
            return []
        except Exception:
            return []

    @staticmethod
    def save(devices: List[Device]):
        try:
            with open(Persistence.FILE, "w", encoding="utf-8") as f:
                json.dump([d.__dict__ for d in devices], f, ensure_ascii=False, default=str)
        except Exception:
            pass

    @staticmethod
    def get_device(device_id: str) -> Optional[Device]:
        devices = Persistence.load()
        for d in devices:
            if d.id == device_id:
                return d
        return None

    @staticmethod
    def create_device(device: Device):
        devices = Persistence.load()
        devices.append(device)
        Persistence.save(devices)

    @staticmethod
    def update_device(device: Device):
        devices = Persistence.load()
        for i, d in enumerate(devices):
            if d.id == device.id:
                devices[i] = device
                break
        Persistence.save(devices)

    @staticmethod
    def add_maintenance_record(record: MaintenanceRecord):
        device = Persistence.get_device(record.device_id)
        if device:
            device.add_maintenance(record)
            Persistence.update_device(device)


# ---------- Business Logic ----------
class MaintenanceSystem:
    def __init__(self):
        self.devices = Persistence.load()

    def register_device(self, name: str, category: str, register_date: datetime, cycle_type: str, cycle_value: int) -> Device:
        """Register a new device."""
        id = str(uuid.uuid4())
        next_maintenance = register_date
        if cycle_type == "hours":
            next_maintenance = register_date + timedelta(hours=cycle_value)
        else:
            next_maintenance = register_date + timedelta(days=cycle_value)
        device = Device(id, name, category, register_date, cycle_type, cycle_value, next_maintenance)
        Persistence.create_device(device)
        return device

    def add_maintenance_record(self, device_id: str, date: datetime, personnel: str, consumables: List[str], notes: str = "") -> MaintenanceRecord:
        """Add a maintenance record for a device."""
        record = MaintenanceRecord(
            id=str(uuid.uuid4()),
            device_id=device_id,
            date=date,
            personnel=personnel,
            consumables=consumables,
            notes=notes,
        )
        Persistence.add_maintenance_record(record)
        return record

    def get_all_devices(self) -> List[Device]:
        """Get all devices with updated status."""
        devices = Persistence.load()
        for d in devices:
            d.update_status()
        return devices

    def get_device_by_id(self, device_id: str) -> Optional[Device]:
        """Get a device by ID."""
        device = Persistence.get_device(device_id)
        if device:
            device.update_status()
        return device

    def get_overdue_devices(self) -> List[Device]:
        """Get devices that are overdue."""
        return [d for d in self.get_all_devices() if d.status == "red"]

    def get_due_soon_devices(self) -> List[Device]:
        """Get devices due within 7 days."""
        return [d for d in self.get_all_devices() if d.status == "yellow"]

    def get_normal_devices(self) -> List[Device]:
        """Get devices in normal status."""
        return [d for d in self.get_all_devices() if d.status == "green"]

    def get_devices_by_category(self, category: str) -> List[Device]:
        """Get devices by category."""
        return [d for d in self.get_all_devices() if d.category == category]


# ---------- CLI Interface ----------
class CLI:
    def __init__(self, system: MaintenanceSystem):
        self.system = system

    def print_banner(self):
        print("\n" + "="*60)
        print("        🔧 Device Maintenance Reminder System")
        print("="*60)

    def print_menu(self):
        print("\n" + "-"*40)
        print("   📋 Main Menu")
        print("-"*40)
        print("1. Register a new device")
        print("2. View all devices")
        print("3. View overdue devices")
        print("4. View devices due soon")
        print("5. View devices in normal status")
        print("6. View devices by category")
        print("7. Add maintenance record")
        print("8. View maintenance history for a device")
        print("9. Exit")
        print("-"*40)

    def get_input(self, prompt: str) -> str:
        return input(prompt).strip()

    def register_device(self):
        print("\n" + "-"*40)
        print("   📝 Register a New Device")
        print("-"*40)
        name = self.get_input("Enter device name: ").strip()
        if not name:
            print("⚠ Device name cannot be empty.")
            return

        category = self.get_input("Enter device category: ").strip()
        if not category:
            print("⚠ Category cannot be empty.")
            return

        try:
            register_date_str = self.get_input("Enter register date (YYYY-MM-DD): ").strip()
            register_date = datetime.strptime(register_date_str, "%Y-%m-%d")
        except ValueError:
            print("⚠ Invalid date format. Using today's date.")
            register_date = datetime.now()

        cycle_type = self.get_input("Cycle type (hours/days): ").strip().lower()
        if cycle_type not in ["hours", "days"]:
            print("⚠ Invalid cycle type. Defaulting to days.")
            cycle_type = "days"

        try:
            cycle_value = int(self.get_input("Cycle value: ").strip())
            if cycle_value <= 0:
                print("⚠ Cycle value must be greater than 0.")
                return
        except ValueError:
            print("⚠ Invalid cycle value.")
            return

        # Calculate next maintenance
        next_maintenance = register_date
        if cycle_type == "hours":
            next_maintenance = register_date + timedelta(hours=cycle_value)
        else:
            next_maintenance = register_date + timedelta(days=cycle_value)

        device = self.system.register_device(name, category, register_date, cycle_type, cycle_value)
        print(f"✅ Device '{device.name}' registered successfully!")
        print(f"   Next maintenance: {next_maintenance.strftime('%Y-%m-%d %H:%M')}")

    def view_all_devices(self):
        devices = self.system.get_all_devices()
        if not devices:
            print("📭 No devices registered yet.")
            return

        print(f"\n📊 Total devices: {len(devices)}")
        print("-"*80)
        print(f"{'ID':<12} {'Name':<20} {'Category':<15} {'Status':<12} {'Next Maintenance':<20}")
        print("-"*80)
        for d in devices:
            print(f"{d.id[:10]:<12} {d.name:<20} {d.category:<15} {d.status:<12} {d.next_maintenance.strftime('%Y-%m-%d %H:%M'):<20}")
        print("-"*80)

    def view_by_status(self, status: str):
        devices = self.system.get_all_devices()
        filtered = [d for d in devices if d.status == status]
        if not filtered:
            print(f"📭 No devices in status '{status}'.")
            return
        print(f"\n📊 Devices in status '{status}': {len(filtered)}")
        print("-"*80)
        print(f"{'ID':<12} {'Name':<20} {'Category':<15} {'Next Maintenance':<20}")
        print("-"*80)
        for d in filtered:
            print(f"{d.id[:10]:<12} {d.name:<20} {d.category:<15} {d.next_maintenance.strftime('%Y-%m-%d %H:%M'):<20}")
        print("-"*80)

    def view_by_category(self):
        categories = set(d.category for d in self.system.get_all_devices())
        if not categories:
            print("📭 No devices registered yet.")
            return
        print(f"\n📊 Available categories: {list(categories)}")
        cat = self.get_input("Enter category to filter: ").strip()
        if not cat:
            return
        devices = self.system.get_devices_by_category(cat)
        if not devices:
            print(f"📭 No devices in category '{cat}'.")
            return
        print(f"\n📊 Devices in category '{cat}': {len(devices)}")
        print("-"*80)
        print(f"{'ID':<12} {'Name':<20} {'Status':<12} {'Next Maintenance':<20}")
        print("-"*80)
        for d in devices:
            print(f"{d.id[:10]:<12} {d.name:<20} {d.status:<12} {d.next_maintenance.strftime('%Y-%m-%d %H:%M'):<20}")
        print("-"*80)

    def add_maintenance_record(self):
        print("\n" + "-"*40)
        print("   🛠 Add Maintenance Record")
        print("-"*40)
        device_id = self.get_input("Enter device ID: ").strip()
        if not device_id:
            print("⚠ Device ID cannot be empty.")
            return

        device = self.system.get_device_by_id(device_id)
        if not device:
            print(f"⚠ Device '{device_id}' not found.")
            return

        print(f"Device: {device.name} ({device.category})")
        print(f"Status: {device.status}")
        print(f"Next maintenance: {device.next_maintenance.strftime('%Y-%m-%d %H:%M')}")

        try:
            date_str = self.get_input("Enter maintenance date (YYYY-MM-DD HH:MM): ").strip()
            date = datetime.strptime(date_str, "%Y-%m-%d %H:%M")
        except ValueError:
            print("⚠ Invalid date format. Using today's date.")
            date = datetime.now()

        personnel = self.get_input("Maintenance personnel: ").strip()
        if not personnel:
            print("⚠ Personnel name cannot be empty.")
            return

        consumables = self.get_input("Consumables used (comma separated): ").strip()
        consumables = [c.strip() for c in consumables.split(",") if c.strip()]

        notes = self.get_input("Notes: ").strip()

        record = self.system.add_maintenance_record(device_id, date, personnel, consumables, notes)
        print(f"✅ Maintenance record added for device '{device.name}'.")
        print(f"   ID: {record.id}")
        print(f"   Date: {record.date.strftime('%Y-%m-%d %H:%M')}")
        print(f"   Personnel: {record.personnel}")
        print(f"   Consumables: {', '.join(record.consumables) if record.consumables else 'None'}")
        print(f"   Notes: {record.notes}")

    def view_device_history(self):
        device_id = self.get_input("Enter device ID: ").strip()
        if not device_id:
            print("⚠ Device ID cannot be empty.")
            return

        device = self.system.get_device_by_id(device_id)
        if not device:
            print(f"⚠ Device '{device_id}' not found.")
            return

        print(f"\n📋 Maintenance History for '{device.name}'")
        print("-"*80)
        print(f"{'Date':<20} {'Personnel':<15} {'Consumables':<30} {'Notes':<25}")
        print("-"*80)
        history = device.get_history_summary()
        if not history:
            print("📭 No maintenance records yet.")
        else:
            for h in history:
                print(f"{h['date'][:19]:<20} {h['personnel']:<15} {', '.join(h['consumables']) if h['consumables'] else 'None':<30} {h['notes'][:25]:<25}")
        print("-"*80)
        print(f"📊 Total records: {len(history)}")

    def run(self):
        self.print_banner()
        while True:
            self.print_menu()
            choice = self.get_input("\nEnter your choice (1-9): ").strip()

            if choice == "1":
                self.register_device()
            elif choice == "2":
                self.view_all_devices()
            elif choice == "3":
                self.view_by_status("red")
            elif choice == "4":
                self.view_by_status("yellow")
            elif choice == "5":
                self.view_by_status("green")
            elif choice == "6":
                self.view_by_category()
            elif choice == "7":
                self.add_maintenance_record()
            elif choice == "8":
                self.view_device_history()
            elif choice == "9":
                print("\n👋 Thank you for using the Device Maintenance Reminder System!")
                break
            else:
                print("⚠ Invalid choice. Please try again.")


# ---------- Entry Point ----------
def main():
    system = MaintenanceSystem()
    cli = CLI(system)
    cli.run()


if __name__ == "__main__":
    main()
