const express = require('express');
const multer = require('multer');
const cors = require('cors');
const path = require('path');
const fs = require('fs').promises;

const app = express();
const PORT = process.env.PORT || 3001;

// Multer storage
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    const dir = path.join(__dirname, 'uploads');
    if (!fs.existsSync(dir)) fs.mkdir(dir, { recursive: true });
    cb(null, dir);
  },
  filename: (req, file, cb) => {
    const ext = path.extname(file.originalname);
    const name = path.basename(file.originalname, ext);
    cb(null, `${Date.now()}-${name}${ext}`);
  }
});

const upload = multer({ storage });

app.use(cors());
app.use(express.json());

// Upload route
app.post('/api/upload', upload.array('files', 20), (req, res) => {
  try {
    const files = req.files;
    const metadata = files.map(f => ({
      id: f.filename,
      name: f.originalname,
      type: f.mimetype.startsWith('video') ? 'video' : 'audio',
      duration: 0, // filled by frontend via ffprobe
      width: 0,
      height: 0,
      url: `/uploads/${f.filename}`
    }));
    res.json({ success: true, files: metadata });
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});

// Health check
app.get('/', (req, res) => res.send('Video Editor Server'));

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
