### `main.js`

```javascript
(() => {
  'use strict';

  const state = {
    clips: [],          // { id, name, type, duration, width, height, url, lane }
    timeline: { start: 0, end: 0 },
    playhead: 0,
    drag: null,
    lane: 'video',
    exported: false
  };

  const $ = (sel) => document.querySelector(sel);
  const timelineBody = $('#timelineBody');
  const timeline = $('#timeline');
  const playhead = $('#playhead');
  const statusEl = $('#status');
  const progressEl = $('#progress');
  const progressFill = $('#progressFill');
  const progressText = $('#progressText');
  const exportBtn = $('#exportBtn');

  // ---------- Upload ----------
  const uploadZone = $('#uploadZone');
  const fileInput = $('#fileInput');
  const clipsList = $('#clipsList');

  uploadZone.addEventListener('click', (e) => {
    if (e.target.closest('.upload-icon')) fileInput.click();
  });
  $('#browseBtn').addEventListener('click', () => fileInput.click());

  fileInput.addEventListener('change', (e) => {
    handleFiles(e.target.files);
    fileInput.value = '';
  });

  uploadZone.addEventListener('dragover', (e) => {
    e.preventDefault();
    uploadZone.classList.add('drag');
  });
  uploadZone.addEventListener('dragleave', () => uploadZone.classList.remove('drag'));
  uploadZone.addEventListener('drop', (e) => {
    e.preventDefault();
    uploadZone.classList.remove('drag');
    handleFiles(e.dataTransfer.files);
  });

  async function handleFiles(files) {
    const allowed = Array.from(files).filter(f => {
      const ext = f.name.split('.').pop().toLowerCase();
      return ['mp4', 'mov', 'webm', 'm4v', 'ogg', 'wav', 'mp3', 'm4a'].includes(ext);
    });
    if (allowed.length === 0) {
      statusEl.textContent = 'No valid files selected.';
      return;
    }
    statusEl.textContent = `Uploading ${allowed.length} file${allowed.length > 1 ? 's' : ''}...`;
    const promises = allowed.map(f => {
      return new Promise((resolve, reject) => {
        const xhr = new XMLHttpRequest();
        xhr.open('POST', '/api/upload', true);
        xhr.onload = () => {
          if (xhr.status === 200) resolve(xhr.response);
          else reject(new Error(xhr.statusText));
        };
        xhr.onerror = () => reject(new Error('Network error'));
        const fd = new FormData();
        fd.append('files', f);
        xhr.send(fd);
      });
    });
    const results = await Promise.all(promises);
    results.forEach(r => {
      try {
        const data = JSON.parse(r);
        if (data.success) {
          const m = data.files[0];
          state.clips.push({ id: m.id, name: m.name, type: m.type, duration: 0, width: 0, height: 0, url: m.url, lane: 'video' });
          renderClipsList();
        }
      } catch (e) { /* ignore */ }
    });
    statusEl.textContent = 'Files uploaded. Analyzing...';
    await Promise.all(state.clips.map(c => analyzeClip(c)));
    renderTimeline();
    statusEl.textContent = 'Ready';
  }

  // ---------- FFprobe ----------
  async function analyzeClip(c) {
    if (c.duration > 0) return;
    try {
      const ffprobe = require('fluent-ffmpeg');
      const probe = ffprobe.ffprobe;
      const info = await probe(c.url);
      const stream = info.streams.find(s => s.codec_type === 'video');
      const audio = info.streams.find(s => s.codec_type === 'audio');
      c.duration = info.format.duration || 0;
      c.width = stream ? stream.width : 0;
      c.height = stream ? stream.height : 0;
      c.audioDuration = audio ? audio.duration || 0 : 0;
    } catch (e) {
      c.duration = 0;
      c.width = 0;
      c.height = 0;
    }
  }

  // ---------- Render ----------
  function renderClipsList() {
    clipsList.innerHTML = '';
    state.clips.forEach(c => {
      const card = document.createElement('div');
      card.className = 'clip-card';
      card.draggable = true;
      card.dataset.id = c.id;
      card.innerHTML = `
        <div class="name">${escapeHtml(c.name)}</div>
        <div class="meta">${c.type} · ${c.duration.toFixed(2)}s</div>
      `;
      card.addEventListener('dragstart', onDragStart);
      card.addEventListener('dragend', onDragEnd);
      clipsList.appendChild(card);
    });
  }

  function renderTimeline() {
    timelineBody.innerHTML = '';
    state.clips.forEach(c => {
      const clip = document.createElement('div');
      clip.className = `clip ${c.type}`;
      clip.dataset.id = c.id;
      clip.dataset.lane = c.lane;
      clip.dataset.start = 0;
      clip.dataset.duration = c.duration;
      clip.dataset.width = c.width;
      clip.dataset.height = c.height;
      clip.dataset.audioDuration = c.audioDuration || 0;
      clip.dataset.url = c.url;
      clip.dataset.type = c.type;

      clip.innerHTML = `
        <div class="clip-info">
          <span class="name">${escapeHtml(c.name)}</span>
          <span class="dur">${c.duration.toFixed(2)}s</span>
        </div>
        <div class="clip-handle"></div>
      `;
      clip.addEventListener('dragstart', onDragStart);
      clip.addEventListener('dragend', onDragEnd);
      clip.addEventListener('click', () => selectClip(clip));
      timelineBody.appendChild(clip);
    });

    // Update playhead position
    updatePlayhead();
  }

  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, c => ({
      '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    }[c]));
  }

  // ---------- Drag & Drop ----------
  function onDragStart(e) {
    const el = e.currentTarget;
    if (!el.dataset.id) return;
    state.drag = { type: 'clip', id: el.dataset.id, lane: el.dataset.lane, start: parseFloat(el.dataset.start), duration: parseFloat(el.dataset.duration) };
    el.classList.add('dragging');
    e.dataTransfer.effectAllowed = 'move';
    try { e.dataTransfer.setData('text/plain', el.dataset.id); } catch (_) {}
  }
  function onDragEnd() {
    state.drag = null;
    document.querySelectorAll('.clip-card, .clip').forEach(el => el.classList.remove('dragging'));
  }

  timeline.addEventListener('dragover', (e) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  });
  timeline.addEventListener('drop', (e) => {
    e.preventDefault();
    if (!state.drag) return;
    const rect = timeline.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const duration = state.drag.duration;
    const clip = document.querySelector(`.clip[data-id="${state.drag.id}"]`);
    if (!clip) return;

    // Lane swap
    if (state.drag.lane !== state.lane) {
      clip.dataset.lane = state.lane;
      clip.classList.toggle('video', state.lane === 'video');
      clip.classList.toggle('audio', state.lane === 'audio');
    }

    // Position
    clip.dataset.start = Math.max(0, Math.min(state.timeline.end - duration, x / timelineBody.offsetWidth * state.timeline.end));
    clip.dataset.duration = duration;
    clip.dataset.width = state.timeline.end * 100;
    clip.dataset.height = state.timeline.end * 100;
    clip.dataset.audioDuration = duration;

    renderTimeline();
    statusEl.textContent = `Moved "${clip.querySelector('.name').textContent}" to ${state.lane} lane`;
  });

  timelineBody.addEventListener('dragover', (e) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  });
  timelineBody.addEventListener('drop', (e) => {
    e.preventDefault();
    if (!state.drag) return;
    const rect = timelineBody.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const duration = state.drag.duration;
    const clip = document.querySelector(`.clip[data-id="${state.drag.id}"]`);
    if (!clip) return;

    clip.dataset.start = Math.max(0, Math.min(state.timeline.end - duration, x / timelineBody.offsetWidth * state.timeline.end));
    clip.dataset.duration = duration;
    clip.dataset.width = state.timeline.end * 100;
    clip.dataset.height = state.timeline.end * 100;
    clip.dataset.audioDuration = duration;

    renderTimeline();
    statusEl.textContent = `Moved "${clip.querySelector('.name').textContent}" to ${state.lane} lane`;
  });

  // ---------- Playhead ----------
  function updatePlayhead() {
    const rect = timeline.getBoundingClientRect();
    const ratio = state.playhead / state.timeline.end;
    playhead.style.left = `${ratio * rect.width}px`;
  }

  timeline.addEventListener('mousedown', (e) => {
    if (e.target.closest('.playhead')) {
      state.drag = { type: 'playhead', start: state.playhead, lane: 'video' };
      playhead.classList.add('dragging');
      e.preventDefault();
    }
  });
  document.addEventListener('mousemove', (e) => {
    if (!state.drag) return;
    const rect = timeline.getBoundingClientRect();
    let x = e.clientX - rect.left;
    if (state.drag.type === 'playhead') {
      state.playhead = Math.max(0, Math.min(state.timeline.end, x / rect.width * state.timeline.end));
      updatePlayhead();
    }
  });
  document.addEventListener('mouseup', () => {
    if (state.drag && state.drag.type === 'playhead') {
      state.drag = null;
      playhead.classList.remove('dragging');
      statusEl.textContent = `Playhead at ${state.playhead.toFixed(2)}s`;
    }
  });

  // ---------- Selection ----------
  function selectClip(clip) {
    document.querySelectorAll('.clip').forEach(c => c.classList.remove('selected'));
    clip.classList.add('selected');
    statusEl.textContent = `Selected "${clip.querySelector('.name').textContent}"`;
  }

  // ---------- Export ----------
  exportBtn.addEventListener('click', () => {
    if (state.clips.length === 0) {
      statusEl.textContent = 'No clips to export';
      return;
    }
    if (state.exported) {
      statusEl.textContent = 'Already exporting';
      return;
    }
    state.exported = true;
    exportBtn.disabled = true;
    progressEl.hidden = false;
    progressFill.style.width = '0%';
    progressText.textContent = 'Preparing export...';

    const output = 'output.mp4';
    const totalDuration = state.timeline.end || state.clips.reduce((s, c) => s + c.duration, 0);
    const ffmpeg = require('fluent-ffmpeg');

    const videoStreams = [];
    const audioStreams = [];
    state.clips.forEach(c => {
      const start = parseFloat(c.dataset.start);
      const duration = parseFloat(c.dataset.duration);
      const url = c.url;
      if (c.type === 'video') {
        videoStreams.push({ start, duration, url });
      } else {
        audioStreams.push({ start, duration, url });
      }
    });

    // Video track
    const videoTrack = videoStreams.map(s => ({
      start: s.start,
      duration: s.duration,
      url: s.url
    }));

    // Audio track
    const audioTrack = audioStreams.map(s => ({
      start: s.start,
      duration: s.duration,
      url: s.url
    }));

    // Merge audio into video
    ffmpeg(videoTrack)
      .outputOptions('-c:v copy')
      .outputOptions('-c:a aac')
      .audioCodec('aac')
      .audioBitrate(128000)
      .audioChannels(2)
      .audioSampleRate(44100)
      .audioVolume('0dB')
      .output(output)
      .on('start', () => {
        progressText.textContent = 'Merging audio and video...';
        progressFill.style.width = '50%';
      })
      .on('progress', (p) => {
        const pct = Math.min(100, Math.round(p.percent));
        progressFill.style.width = `${pct}%`;
      })
      .on('end', () => {
        progressText.textContent = 'Export complete!';
        progressFill.style.width = '100%';
        setTimeout(() => {
          progressEl.hidden = true;
          progressFill.style.width = '0%';
          statusEl.textContent = `Exported ${output}`;
          state.exported = false;
          exportBtn.disabled = false;
        }, 1500);
      })
      .on('error', (err) => {
        progressText.textContent = 'Export failed: ' + err.message;
        progressFill.style.width = '100%';
        setTimeout(() => {
          progressEl.hidden = true;
          progressFill.style.width = '0%';
          state.exported = false;
          exportBtn.disabled = false;
        }, 1500);
      })
      .run();

    statusEl.textContent = `Exporting ${output}...`;
  });

  // ---------- Init ----------
  renderTimeline();
})();
```

