## 🧠 script.js

```javascript
(() => {
  'use strict';

  const canvas = document.getElementById('editor');
  const ctx = canvas.getContext('2d');
  const canvasWrap = document.getElementById('canvasWrap');
  const overlay = document.querySelector('.canvas-overlay');
  const cursorDrag = document.getElementById('cursorDrag');
  const cursorCross = document.getElementById('cursorCross');
  const modeLabel = document.getElementById('modeLabel');
  const modeHint = document.getElementById('modeHint');
  const modeBtns = document.querySelectorAll('.mode');
  const toolBtns = document.querySelectorAll('.tool-btn');
  const colorSwatches = document.querySelectorAll('.color-swatch');
  const textSize = document.getElementById('textSize');
  const textFont = document.getElementById('textFont');
  const saveBtn = document.getElementById('saveBtn');
  const clearBtn = document.getElementById('clearBtn');
  const undoBtn = document.getElementById('undoBtn');
  const redoBtn = document.getElementById('redoBtn');
  const toast = document.createElement('div');
  document.body.appendChild(toast);

  // ---------- State ----------
  const state = {
    mode: 'area',
    tool: 'rect',
    color: '#000',
    fontSize: 24,
    fontFamily: 'Arial',
    startX: 0, startY: 0,
    endX: 0, endY: 0,
    dragging: false,
    dragHandle: null,
    dragOffset: { x: 0, y: 0 },
    selection: null,
    history: [],
    redoStack: [],
    currentId: 0,
  };

  // ---------- Canvas sizing ----------
  function resizeCanvas() {
    const rect = canvasWrap.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    canvas.width = rect.width * dpr;
    canvas.height = rect.height * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }
  window.addEventListener('resize', resizeCanvas);
  resizeCanvas();

  // ---------- Capture overlay ----------
  function showCaptureOverlay() {
    const overlayEl = document.createElement('div');
    overlayEl.className = 'capture-overlay';
    overlayEl.innerHTML = `
      <div class="capture-box" id="captureBox" style="width:0;height:0;">
        <div class="handle top-left"></div>
        <div class="handle top-right"></div>
        <div class="handle bottom-left"></div>
        <div class="handle bottom-right"></div>
      </div>
    `;
    document.body.appendChild(overlayEl);
    const box = overlayEl.querySelector('.capture-box');
    state.dragging = false;
    state.dragHandle = null;

    const mode = state.mode;
    let x = 0, y = 0, w = 0, h = 0;
    if (mode === 'area') {
      const r = canvasWrap.getBoundingClientRect();
      x = r.left; y = r.top; w = r.width; h = r.height;
    } else if (mode === 'window') {
      const wRect = window.outerWidth;
      const hRect = window.outerHeight;
      const left = window.screenX;
      const top = window.screenY;
      x = left; y = top; w = wRect; h = hRect;
    } else if (mode === 'page') {
      const doc = document.documentElement;
      x = doc.scrollLeft; y = doc.scrollTop; w = doc.scrollWidth; h = doc.scrollHeight;
    }
    box.style.left = x + 'px';
    box.style.top = y + 'px';
    box.style.width = w + 'px';
    box.style.height = h + 'px';

    box.addEventListener('mousedown', (e) => {
      const handle = e.target.closest('.handle');
      if (handle) {
        state.dragging = true;
        state.dragHandle = handle;
        state.dragOffset.x = e.clientX - (box.getBoundingClientRect().left + 7);
        state.dragOffset.y = e.clientY - (box.getBoundingClientRect().top + 7);
        e.preventDefault();
      }
    });
    document.addEventListener('mousemove', onCaptureMove);
    document.addEventListener('mouseup', onCaptureUp);
  }

  function onCaptureMove(e) {
    if (!state.dragging) return;
    const box = document.querySelector('.capture-box');
    if (!box) return;
    const rect = box.getBoundingClientRect();
    const x = e.clientX - state.dragOffset.x;
    const y = e.clientY - state.dragOffset.y;
    box.style.left = x + 'px';
    box.style.top = y + 'px';
    box.style.width = Math.max(0, rect.width) + 'px';
    box.style.height = Math.max(0, rect.height) + 'px';
    state.startX = x; state.startY = y;
    state.endX = x + rect.width; state.endY = y + rect.height;
  }
  function onCaptureUp() {
    state.dragging = false;
    state.dragHandle = null;
    const box = document.querySelector('.capture-box');
    if (box) box.remove();
    state.selection = { mode: state.mode, startX: state.startX, startY: state.startY, endX: state.endX, endY: state.endY };
    hideCaptureOverlay();
    render();
    showToast('Selection ready');
  }
  function hideCaptureOverlay() {
    const ov = document.querySelector('.capture-overlay');
    if (ov) ov.remove();
  }

  // ---------- Canvas drawing ----------
  function getPixelData() {
    const rect = canvasWrap.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    const w = Math.floor(rect.width * dpr);
    const h = Math.floor(rect.height * dpr);
    const img = new Image();
    img.src = canvas.toDataURL('image/png');
    return { img, w, h, dpr };
  }

  function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    const { img, w, h, dpr } = getPixelData();
    const imgW = w / dpr;
    const imgH = h / dpr;
    ctx.drawImage(img, 0, 0, imgW, imgH);
    drawSelection();
    drawHistory();
  }

  function drawSelection() {
    if (!state.selection) return;
    const s = state.selection;
    const rect = canvasWrap.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    const x = s.startX * dpr;
    const y = s.startY * dpr;
    const w = Math.abs(s.endX - s.startX) * dpr;
    const h = Math.abs(s.endY - s.startY) * dpr;
    if (w < 2 || h < 2) return;

    ctx.save();
    ctx.strokeStyle = state.color;
    ctx.lineWidth = 2;
    ctx.setLineDash([]);
    ctx.strokeRect(x, y, w, h);
    ctx.restore();
  }

  function drawHistory() {
    ctx.save();
    state.history.forEach((item) => {
      ctx.fillStyle = item.color;
      ctx.font = `${item.fontSize}px ${item.fontFamily}`;
      ctx.textAlign = 'left';
      ctx.textBaseline = 'top';
      ctx.fillText(item.text, item.x, item.y);
    });
    ctx.restore();
  }

  // ---------- Drawing ----------
  let drawing = false;
  let drawingData = null;
  let drawingText = null;

  function startDraw(e) {
    const rect = canvasWrap.getBoundingClientRect();
    const x = (e.clientX - rect.left) * (window.devicePixelRatio || 1);
    const y = (e.clientY - rect.top) * (window.devicePixelRatio || 1);
    if (state.tool === 'text') {
      drawingText = { x, y, tool: 'text' };
    } else {
      drawingData = { x, y, tool: state.tool, color: state.color, size: state.fontSize, font: state.fontFamily };
    }
    drawing = true;
    drawSelection();
  }
  function moveDraw(e) {
    if (!drawing) return;
    const rect = canvasWrap.getBoundingClientRect();
    const x = (e.clientX - rect.left) * (window.devicePixelRatio || 1);
    const y = (e.clientY - rect.top) * (window.devicePixelRatio || 1);
    if (drawingData) {
      drawingData.x2 = x; drawingData.y2 = y;
      drawSelection();
    }
    if (drawingText) {
      drawingText.x = x; drawingText.y = y;
      drawSelection();
    }
  }
  function endDraw() {
    drawing = false;
    if (drawingData) {
      state.history.push({
        id: ++state.currentId,
        x: drawingData.x,
        y: drawingData.y,
        x2: drawingData.x2,
        y2: drawingData.y2,
        tool: drawingData.tool,
        color: drawingData.color,
        size: drawingData.size,
        font: drawingData.font,
      });
      drawingData = null;
      drawSelection();
    }
    if (drawingText) {
      state.history.push({
        id: ++state.currentId,
        x: drawingText.x,
        y: drawingText.y,
        tool: 'text',
        color: state.color,
        size: state.fontSize,
        font: state.fontFamily,
        text: drawingText.text || '',
      });
      drawingText = null;
      drawSelection();
    }
  }

  canvas.addEventListener('mousedown', (e) => {
    if (e.button !== 0) return;
    if (state.mode === 'area' && !state.selection) {
      state.startX = e.clientX; state.startY = e.clientY;
      state.endX = e.clientX; state.endY = e.clientY;
      showCaptureOverlay();
    } else {
      startDraw(e);
    }
  });
  window.addEventListener('mousemove', moveDraw);
  window.addEventListener('mouseup', endDraw);

  // ---------- Tools ----------
  function setTool(tool) {
    state.tool = tool;
    toolBtns.forEach(b => {
      b.classList.toggle('active', b.dataset.tool === tool);
    });
    if (tool === 'text') {
      drawingText = { x: state.startX, y: state.startY, tool: 'text' };
      drawSelection();
    }
  }
  toolBtns.forEach(b => b.addEventListener('click', () => setTool(b.dataset.tool)));

  // ---------- Colors ----------
  colorSwatches.forEach(sw => {
    sw.addEventListener('click', () => {
      colorSwatches.forEach(s => s.classList.remove('active'));
      sw.classList.add('active');
      state.color = sw.dataset.color;
    });
  });

  // ---------- Text input ----------
  canvas.addEventListener('click', (e) => {
    if (state.tool === 'text' && drawingText) {
      const rect = canvasWrap.getBoundingClientRect();
      const x = (e.clientX - rect.left) * (window.devicePixelRatio || 1);
      const y = (e.clientY - rect.top) * (window.devicePixelRatio || 1);
      drawingText.x = x; drawingText.y = y;
      drawSelection();
    }
  });
  textSize.addEventListener('input', (e) => {
    state.fontSize = parseInt(e.target.value, 10);
    if (state.tool === 'text' && drawingText) {
      drawingText.size = state.fontSize;
      drawSelection();
    }
  });
  textFont.addEventListener('change', (e) => {
    state.fontFamily = e.target.value;
    if (state.tool === 'text' && drawingText) {
      drawingText.font = state.fontFamily;
      drawSelection();
    }
  });

  // ---------- Mode ----------
  modeBtns.forEach(b => {
    b.addEventListener('click', () => {
      modeBtns.forEach(m => m.classList.remove('active'));
      b.classList.add('active');
      state.mode = b.dataset.mode;
      modeLabel.textContent = b.textContent.trim();
      if (state.mode === 'area' && !state.selection) {
        state.startX = 0; state.startY = 0; state.endX = 0; state.endY = 0;
        showCaptureOverlay();
      } else {
        hideCaptureOverlay();
        state.selection = null;
        render();
      }
    });
  });

  // ---------- Undo/Redo ----------
  function pushHistory() {
    const snapshot = { history: state.history.slice(), selection: state.selection, tool: state.tool, color: state.color, fontSize: state.fontSize, fontFamily: state.fontFamily };
    state.history = [];
    state.redoStack = [];
    state.currentId = 0;
    state.history.push(snapshot);
  }
  function undo() {
    if (state.history.length === 0) return;
    const item = state.history.pop();
    state.redoStack.push(item);
    if (state.history.length === 0) {
      state.tool = item.tool || 'rect';
      state.color = item.color || '#000';
      state.fontSize = item.size || 24;
      state.fontFamily = item.font || 'Arial';
    }
    render();
  }
  function redo() {
    if (state.redoStack.length === 0) return;
    const item = state.redoStack.pop();
    state.history.push(item);
    state.tool = item.tool || 'rect';
    state.color = item.color || '#000';
    state.fontSize = item.size || 24;
    state.fontFamily = item.font || 'Arial';
    render();
  }
  undoBtn.addEventListener('click', undo);
  redoBtn.addEventListener('click', redo);

  // ---------- Save PNG ----------
  saveBtn.addEventListener('click', async () => {
    try {
      const { img, w, h, dpr } = getPixelData();
      const a = document.createElement('a');
      a.download = `quickscreenshot-${Date.now()}.png`;
      a.href = img.src;
      a.click();
      showToast('Screenshot saved');
    } catch (err) {
      showToast('Save failed');
    }
  });

  // ---------- Clear ----------
  clearBtn.addEventListener('click', () => {
    if (state.history.length === 0) return;
    state.history = [];
    state.redoStack = [];
    state.currentId = 0;
    render();
    showToast('Canvas cleared');
  });

  // ---------- Toast ----------
  let toastTimer;
  function showToast(msg) {
    toast.textContent = msg;
    toast.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => toast.classList.remove('show'), 1800);
  }

  // ---------- Keyboard shortcuts ----------
  document.addEventListener('keydown', (e) => {
    if (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT') return;
    if (e.key === 'Escape') {
      if (state.selection) {
        state.selection = null;
        render();
      }
      hideCaptureOverlay();
    }
    if (e.key === 'z' && (e.ctrlKey || e.metaKey)) {
      e.preventDefault();
      undo();
    }
    if (e.key === 'y' && (e.ctrlKey || e.metaKey)) {
      e.preventDefault();
      redo();
    }
    if (e.key === 'Delete' || e.key === 'Backspace') {
      if (state.history.length > 0) {
        state.history.pop();
        render();
      }
    }
  });

  // ---------- Init ----------
  setTool('rect');
  render();
})();
