```python
from typing import List, Dict, Optional, Any
from datetime import datetime, timedelta
from enum import Enum
from dataclasses import dataclass
from uuid import uuid4
import json
import pickle

# ---------- Enums ----------
class Role(Enum):
    CUSTOMER = "customer"
    AGENT = "agent"
    ADMIN = "admin"

class PolicyType(Enum):
    LIFE = "life"
    HEALTH = "health"
    AUTO = "auto"
    HOME = "home"

class ClaimStatus(Enum):
    SUBMITTED = "submitted"
    UNDER_REVIEW = "under_review"
    APPROVED = "approved"
    PAID = "paid"
    REJECTED = "rejected"

# ---------- Dataclasses ----------
@dataclass
class InsuranceProduct:
    id: str
    name: str
    description: str
    premium: float
    coverage: float
    type: PolicyType

@dataclass
class Customer:
    id: str
    first_name: str
    last_name: str
    email: str
    phone: str
    date_of_birth: str  # YYYY-MM-DD
    address: str
    role: Role = Role.CUSTOMER

@dataclass
class Policy:
    id: str
    customer_id: str
    product_id: str
    start_date: str
    end_date: str
    premium_amount: float
    status: str = "active"  # active | expired | cancelled

@dataclass
class Claim:
    id: str
    customer_id: str
    policy_id: str
    claim_amount: float
    description: str
    status: ClaimStatus
    submitted_at: str
    reviewed_at: Optional[str] = None
    approved_at: Optional[str] = None
    paid_at: Optional[str] = None
    reason: Optional[str] = None

# ---------- Storage ----------
class Storage:
    """In-memory storage using dictionaries."""
    def __init__(self):
        self.customers: Dict[str, Customer] = {}
        self.policies: Dict[str, Policy] = {}
        self.products: Dict[str, InsuranceProduct] = {}
        self.claims: Dict[str, Claim] = {}
        self.next_id = lambda: str(uuid4())[:8]

    def save(self):
        """Save to disk (demo)."""
        data = {
            "customers": {k: v.__dict__ for k, v in self.customers.items()},
            "policies": {k: v.__dict__ for k, v in self.policies.items()},
            "products": {k: v.__dict__ for k, v in self.products.items()},
            "claims": {k: v.__dict__ for k, v in self.claims.items()},
            "next_id": self.next_id.__name__,
        }
        with open("insurance.db", "wb") as f:
            pickle.dump(data, f)

    def load(self):
        try:
            with open("insurance.db", "rb") as f:
                data = pickle.load(f)
                self.customers = {
                    k: Customer(**v) for k, v in data.get("customers", {}).items()
                }
                self.policies = {
                    k: Policy(**v) for k, v in data.get("policies", {}).items()
                }
                self.products = {
                    k: InsuranceProduct(**v) for k, v in data.get("products", {}).items()
                }
                self.claims = {
                    k: Claim(**v) for k, v in data.get("claims", {}).items()
                }
        except FileNotFoundError:
            pass

    def get_customer(self, customer_id: str) -> Optional[Customer]:
        return self.customers.get(customer_id)

    def get_policy(self, policy_id: str) -> Optional[Policy]:
        return self.policies.get(policy_id)

    def get_product(self, product_id: str) -> Optional[InsuranceProduct]:
        return self.products.get(product_id)

    def get_claim(self, claim_id: str) -> Optional[Claim]:
        return self.claims.get(claim_id)

    def get_all_customers(self) -> List[Customer]:
        return list(self.customers.values())

    def get_all_policies(self) -> List[Policy]:
        return list(self.policies.values())

    def get_all_products(self) -> List[InsuranceProduct]:
        return list(self.products.values())

    def get_all_claims(self) -> List[Claim]:
        return list(self.claims.values())

    def create_customer(self, customer: Customer):
        self.customers[customer.id] = customer

    def create_policy(self, policy: Policy):
        self.policies[policy.id] = policy

    def create_claim(self, claim: Claim):
        self.claims[claim.id] = claim

    def update_claim(self, claim_id: str, **updates):
        claim = self.claims.get(claim_id)
        if claim:
            for k, v in updates.items():
                if hasattr(claim, k):
                    setattr(claim, k, v)

    def delete_claim(self, claim_id: str):
        self.claims.pop(claim_id, None)

    def add_product(self, product: InsuranceProduct):
        self.products[product.id] = product

    def add_customer(self, customer: Customer):
        self.customers[customer.id] = customer

    def add_policy(self, policy: Policy):
        self.policies[policy.id] = policy

    def add_claim(self, claim: Claim):
        self.claims[claim.id] = claim

    def update_customer(self, customer_id: str, **updates):
        customer = self.customers.get(customer_id)
        if customer:
            for k, v in updates.items():
                if hasattr(customer, k):
                    setattr(customer, k, v)

    def update_policy(self, policy_id: str, **updates):
        policy = self.policies.get(policy_id)
        if policy:
            for k, v in updates.items():
                if hasattr(policy, k):
                    setattr(policy, k, v)

    def delete_customer(self, customer_id: str):
        self.customers.pop(customer_id, None)
        for pid in list(self.policies.keys()):
            if self.policies[pid].customer_id == customer_id:
                self.policies.pop(pid)

    def delete_policy(self, policy_id: str):
        self.policies.pop(policy_id, None)

    def find_customer_by_email(self, email: str) -> Optional[Customer]:
        for c in self.customers.values():
            if c.email == email:
                return c
        return None

    def find_customer_by_phone(self, phone: str) -> Optional[Customer]:
        for c in self.customers.values():
            if c.phone == phone:
                return c
        return None

# ---------- Managers ----------
class CustomerManager:
