    def update_policy(self, policy_id: str, **updates) -> bool:
        if self.storage.update_policy(policy_id, **updates):
            return True
        return False

    def delete_policy(self, policy_id: str) -> bool:
        if self.storage.delete_policy(policy_id):
            return True
        return False

    def get_active_policies_for_customer(self, customer_id: str) -> List[Policy]:
        return [
            p for p in self.storage.get_all_policies()
            if p.customer_id == customer_id and p.status == "active"
        ]

class ClaimManager:
    def __init__(self, storage: Storage):
        self.storage = storage

    def submit_claim(self, customer_id: str, policy_id: str, claim_amount: float, description: str) -> Claim:
        policy = self.storage.get_policy(policy_id)
        if not policy:
            raise ValueError(f"Policy {policy_id} not found")
        if policy.customer_id != customer_id:
            raise ValueError("Policy does not belong to customer")
        claim = Claim(
            id=self.storage.next_id(),
            customer_id=customer_id,
            policy_id=policy_id,
            claim_amount=claim_amount,
            description=description,
            status=ClaimStatus.SUBMITTED,
            submitted_at=datetime.now().isoformat(),
        )
        self.storage.add_claim(claim)
        return claim

    def get_claim_by_id(self, claim_id: str) -> Optional[Claim]:
        return self.storage.get_claim(claim_id)

    def get_all_claims(self) -> List[Claim]:
        return self.storage.get_all_claims()

    def update_claim_status(self, claim_id: str, status: ClaimStatus, reason: str = None) -> bool:
        claim = self.storage.get_claim(claim_id)
        if not claim:
            return False
        if claim.status == status:
            return True
        if status == ClaimStatus.APPROVED:
            claim.reviewed_at = datetime.now().isoformat()
            claim.status = status
        elif status == ClaimStatus.PAID:
            claim.approved_at = claim.reviewed_at or datetime.now().isoformat()
            claim.paid_at = datetime.now().isoformat()
            claim.status = status
        elif status == ClaimStatus.REJECTED:
            claim.reviewed_at = datetime.now().isoformat()
            claim.status = status
            claim.reason = reason or "Insufficient documentation"
        return True

    def get_claims_by_customer(self, customer_id: str) -> List[Claim]:
        return [c for c in self.storage.get_all_claims() if c.customer_id == customer_id]

    def get_pending_claims(self) -> List[Claim]:
        return [c for c in self.storage.get_all_claims() if c.status == ClaimStatus.SUBMITTED]

    def get_reviewed_claims(self) -> List[Claim]:
        return [c for c in self.storage.get_all_claims() if c.status in [ClaimStatus.APPROVED, ClaimStatus.REJECTED]]

class ProductManager:
    def __init__(self, storage: Storage):
