class ReportManager:
    def __init__(self, storage: Storage):
        self.storage = storage

    def customer_count(self) -> int:
        return len(self.storage.get_all_customers())

    def policy_count(self) -> int:
        return len(self.storage.get_all_policies())

    def claim_count_by_status(self) -> Dict[ClaimStatus, int]:
        counts = {s: 0 for s in ClaimStatus}
        for c in self.storage.get_all_claims():
            counts[c.status] += 1
        return counts

    def total_claim_amount(self) -> float:
        return sum(c.claim_amount for c in self.storage.get_all_claims())

    def total_premium_earned(self) -> float:
        return sum(p.premium_amount for p in self.storage.get_all_policies() if p.status == "active")

    def customers_by_age_group(self) -> Dict[str, int]:
        """Age groups: <18, 18-35, 36-55, 56+"""
        today = datetime.now()
        groups = {
            "Under 18": 0,
            "18-35": 0,
            "36-55": 0,
            "56+": 0,
        }
        for c in self.storage.get_all_customers():
            dob = datetime.strptime(c.date_of_birth, "%Y-%m-%d")
            age = (today - dob).days // 365
            if age < 18:
                groups["Under 18"] += 1
            elif age <= 35:
                groups["18-35"] += 1
            elif age <= 55:
                groups["36-55"] += 1
            else:
                groups["56+"] += 1
        return groups

    def top_products_by_sales(self) -> List[tuple]:
        """Count active policies per product."""
        product_counts = {}
        for p in self.storage.get_all_policies():
            if p.status == "active":
                product_counts[p.product_id] = product_counts.get(p.product_id, 0) + 1
        return sorted(
            [(self.storage.products[pid].name, count) for pid, count in product_counts.items()],
            key=lambda x: x[1],
            reverse=True,
        )

