// ============================================================
// Equestrian Show Jumping Game
// ============================================================
// A browser-based game where the player controls a horse over obstacles.
// Controls: Arrow keys to steer, Space to jump.
// ============================================================

(() => {
  'use strict';

  // ---------- Canvas Setup ----------
  const canvas = document.createElement('canvas');
  canvas.width = 800;
  canvas.height = 500;
  canvas.style.display = 'block';
  canvas.style.margin = '0 auto';
  canvas.style.border = '2px solid #333';
  document.body.appendChild(canvas);
  const ctx = canvas.getContext('2d');

  // ---------- Constants ----------
  const GRAVITY = 0.6;
  const MAX_FALL = 22;
  const JUMP_VELOCITY = -14;
  const MAX_VELOCITY = 10;
  const MAX_TURN = 1.2; // radians
  const HORSE_SIZE = 48;
  const RAIL_HEIGHT = 100;
  const RAIL_WIDTH = 80;
  const RAIL_GAP = 140;
  const WATER_HEIGHT = 60;
  const WATER_WIDTH = 100;
  const FINISH_X = 760;
  const FINISH_Y = 400;
  const FINISH_COLOR = '#FFD700';
  const OBSTACLE_SPEED = 5;

  // ---------- State ----------
  const state = {
    width: canvas.width,
    height: canvas.height,
    obstacles: [],
    rider: null,
    horse: null,
    score: 0,
    bestScore: parseInt(localStorage.getItem('showJumpingBest') || '0', 10),
    gameOver: false,
    paused: false,
    frame: 0,
    time: 0,
  };

  // ---------- Obstacle Types ----------
  const OBSTACLE_TYPES = ['rail', 'water', 'rail'];
  const OBSTACLE_COLORS = {
    rail: ['#C0C0C0', '#A9A9A9'],
    water: ['#00BFFF', '#1E90FF'],
  };

  // ---------- Obstacle Factory ----------
  function createObstacle(type) {
    const colors = OBSTACLE_COLORS[type] || ['#888', '#666'];
    const color = colors[Math.floor(Math.random() * colors.length)];
    const x = Math.random() * (state.width - RAIL_WIDTH);
    const y = type === 'rail' ? 120 : 200;
    const w = type === 'rail' ? RAIL_WIDTH : WATER_WIDTH;
    const h = type === 'rail' ? RAIL_HEIGHT : WATER_HEIGHT;
    return { type, x, y, w, h, color, knockedDown: false };
  }

  // ---------- Rider ----------
  function createRider() {
    const x = 120;
    const y = state.height - 180;
    return { x, y, width: 40, height: 60, color: '#4A4A4A' };
  }

  // ---------- Horse ----------
  function createHorse() {
    return {
      x: 140,
      y: state.height - 180,
      vx: 0,
      vy: 0,
      angle: 0,
      speed: 0,
      jumping: false,
      jumpHeight: 0,
      maxJumpHeight: 0,
      baseY: state.height - 180,
      size: HORSE_SIZE,
      color: '#8B4513',
      maneColor: '#6B8E4A',
      eyeColor: '#2B1B1B',
      bodyColor: '#A0522D',
      tailColor: '#3A2412',
      frame: 0,
      animSpeed: 6,
    };
  }

  // ---------- Game Init ----------
  function init() {
    state.obstacles = [];
    state.rider = createRider();
    state.horse = createHorse();
    state.score = 0;
    state.gameOver = false;
    state.paused = false;
    state.frame = 0;
    state.time = 0;

    // Place obstacles
    const obstacleCount = 6;
    for (let i = 0; i < obstacleCount; i++) {
      state.obstacles.push(createObstacle(OBSTACLE_TYPES[i % OBSTACLE_TYPES.length]));
    }

    // Reset horse position
    state.horse.x = 140;
    state.horse.y = state.height - 180;
    state.horse.vx = 0;
    state.horse.vy = 0;
    state.horse.angle = 0;
    state.horse.speed = 0;
    state.horse.jumping = false;
    state.horse.jumpHeight = 0;
    state.horse.maxJumpHeight = 0;
    state.horse.baseY = state.height - 180;
  }

  // ---------- Input ----------
  window.addEventListener('keydown', (e) => {
    if (e.key === ' ' && !state.gameOver && !state.paused) {
      e.preventDefault();
      if (!state.horse.jumping) {
        state.horse.jumping = true;
        state.horse.vy = JUMP_VELOCITY;
        state.horse.maxJumpHeight = state.horse.y - state.horse.baseY;
      }
    } else if (e.key === 'Enter' && state.gameOver) {
      init();
    } else if (e.key === 'p' || e.key === 'P') {
      state.paused = !state.paused;
    }
  });

  // ---------- Update ----------
  function update(dt) {
    state.frame++;
    state.time += dt;

    if (state.gameOver || state.paused) return;

    // Player input
    const keys = {};
    const pressed = {};
    ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', ' '].forEach(k => {
      if (k === ' ') pressed[k] = false;
      else pressed[k] = false;
    });
    window.addEventListener('keydown', (e) => {
      if (pressed[e.key]) return;
      pressed[e.key] = true;
      if (e.key === ' ') {
        e.preventDefault();
        if (!state.horse.jumping) {
          state.horse.jumping = true;
          state.horse.vy = JUMP_VELOCITY;
          state.horse.maxJumpHeight = state.horse.y - state.horse.baseY;
        }
      }
    });
    window.addEventListener('keyup', (e) => {
      pressed[e.key] = false;
    });

    // Steer
    if (pressed['ArrowLeft']) {
      state.horse.angle += MAX_TURN * dt;
    } else if (pressed['ArrowRight']) {
      state.horse.angle -= MAX_TURN * dt;
    } else {
      state.horse.angle = Math.max(0, Math.min(Math.PI / 2, state.horse.angle));
    }

    // Move forward
    state.horse.speed = Math.min(MAX_VELOCITY, state.horse.speed + 0.15 * dt);
    const forward = { x: Math.cos(state.horse.angle), y: Math.sin(state.horse.angle) };
    state.horse.vx += forward.x * state.horse.speed * dt;
    state.horse.vy += forward.y * state.horse.speed * dt;

    // Apply gravity
    if (!state.horse.jumping) {
      state.horse.vy += GRAVITY * dt;
      if (state.horse.vy > MAX_FALL) state.horse.vy = MAX_FALL;
    }

    // Jump height
    if (state.horse.jumping) {
      state.horse.y += state.horse.vy * dt;
      state.horse.jumpHeight += state.horse.vy * dt;
      if (state.horse.jumpHeight >= state.horse.maxJumpHeight) {
        state.horse.jumping = false;
        state.horse.jumpHeight = 0;
      }
    } else {
      state.horse.y = Math.max(state.horse.baseY, state.horse.y);
    }

    // Update rider
    state.rider.x = state.horse.x - state.rider.width / 2;
    state.rider.y = state.horse.y - state.rider.height / 2;

    // Update obstacles
    for (const o of state.obstacles) {
      o.x -= OBSTACLE_SPEED * dt;
      if (o.type === 'rail' && o.knockedDown) {
        // animate falling rail
        o.y += 2 * dt;
      }
    }

    // Remove off-screen obstacles
    state.obstacles = state.obstacles.filter(o => o.x + o.w > -20);

    // Check collisions
    for (const o of state.obstacles) {
      if (o.knockedDown) continue;
      if (checkCollision(state.horse, o)) {
        knockDownObstacle(o);
      }
    }

    // Check finish
    if (!state.gameOver && state.horse.x > FINISH_X) {
      endGame(true);
    }
  }

  function checkCollision(horse, obstacle) {
    const horseRight = horse.x + horse.size;
    const horseLeft = horse.x;
    const horseTop = horse.y;
    const horseBottom = horse.y + horse.size;

    const obstacleRight = obstacle.x + obstacle.w;
    const obstacleLeft = obstacle.x;
    const obstacleTop = obstacle.y;
    const obstacleBottom = obstacle.y + obstacle.h;

    return (
      horseRight > obstacleLeft &&
      horseLeft < obstacleRight &&
      horseBottom > obstacleTop &&
      horseTop < obstacleBottom
    );
  }

  function knockDownObstacle(obstacle) {
    obstacle.knockedDown = true;
    state.score -= 10;
    if (state.score < 0) state.score = 0;
    // Update best score
    if (state.score > state.bestScore) {
      state.bestScore = state.score;
      localStorage.setItem('showJumpingBest', String(state.bestScore));
    }
  }

  function endGame(success) {
    state.gameOver = true;
    if (success) {
      state.score += 100;
    }
    if (state.score > state.bestScore) {
      state.bestScore = state.score;
      localStorage.setItem('showJumpingBest', String(state.bestScore));
    }
  }

  // ---------- Render ----------
  function render() {
    ctx.clearRect(0, 0, state.width, state.height);

    // Background
    const gradient = ctx.createLinearGradient(0, 0, 0, state.height);
    gradient.addColorStop(0, '#E8F5E9');
    gradient.addColorStop(1, '#81C784');
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, state.width, state.height);

    // Ground
    ctx.fillStyle = '#66BB6A';
    ctx.fillRect(0, state.height - 60, state.width, 60);

    // Grass strip
    ctx.fillStyle = '#43A047';
    ctx.fillRect(0, state.height - 55, state.width, 5);

    // Finish line
    if (!state.gameOver) {
      ctx.fillStyle = FINISH_COLOR;
      ctx.fillRect(FINISH_X - 10, FINISH_Y - 4, 20, 8);
      ctx.fillStyle = '#8B5A2B';
      ctx.fillRect(FINISH_X - 10, FINISH_Y - 8, 20, 2);
    }

    // Obstacles
    for (const o of state.obstacles) {
      if (o.knockedDown) {
        // Falling rail animation
        const fallProgress = Math.min(1, o.y / (state.height - 100));
        const fallHeight = (state.height - 100) * fallProgress;
        const fallY = o.y + fallHeight;
        ctx.fillStyle = '#A9A9A9';
        ctx.fillRect(o.x, fallY, o.w, o.h);
        ctx.fillStyle = '#696969';
        ctx.fillRect(o.x + 5, fallY + 5, o.w - 10, o.h - 10);
        continue;
      }
      if (o.type === 'rail') {
        ctx.fillStyle = o.color;
        ctx.fillRect(o.x, o.y, o.w, o.h);
        ctx.fillStyle = '#333';
        ctx.fillRect(o.x + 4, o.y + 4, o.w - 8, o.h - 8);
        ctx.fillStyle = '#8B0000';
        ctx.fillRect(o.x + 8, o.y + 8, o.w - 16, 4);
      } else {
        // Water
        ctx.fillStyle = '#1E90FF';
        ctx.fillRect(o.x, o.y, o.w, o.h);
        ctx.fillStyle = '#0066CC';
        ctx.fillRect(o.x + 4, o.y + 4, o.w - 8, o.h - 8);
        ctx.fillStyle = '#FFFFFF';
        ctx.fillRect(o.x + 8, o.y + 8, o.w - 16, 4);
      }
    }

    // Horse
    renderHorse();

    // Rider
    ctx.fillStyle = state.rider.color;
    ctx.fillRect(state.rider.x, state.rider.y, state.rider.width, state.rider.height);
    ctx.fillStyle = '#2B1B1B';
    ctx.fillRect(state.rider.x + 8, state.rider.y + 10, 10, 8);
    ctx.fillRect(state.rider.x + 22, state.rider.y + 10, 10, 8);

    // HUD
    renderHUD();
  }

  function renderHorse() {
    const h = state.horse;
    h.frame++;
    const anim = Math.floor(h.frame / h.animSpeed) % 4;

    // Body
    ctx.save();
    ctx.translate(h.x, h.y);
    ctx.rotate(h.angle);

    const bodyColors = {
      0: h.bodyColor,
      1: '#8B3A1F',
      2: h.bodyColor,
      3: '#8B4513',
    };
    const maneColors = {
      0: h.maneColor,
      1: '#4A7A3A',
      2: h.maneColor,
      3: '#5A8A4A',
    };

    // Body
    ctx.fillStyle = bodyColors[anim];
    ctx.beginPath();
    ctx.moveTo(0, -h.size / 2);
    ctx.lineTo(h.size / 2, -h.size / 2 + 10);
    ctx.lineTo(h.size / 2, h.size / 2 - 10);
    ctx.lineTo(-h.size / 2, h.size / 2 - 10);
    ctx.lineTo(-h.size / 2, -h.size / 2 + 10);
    ctx.closePath();
    ctx.fill();

    // Mane
    ctx.fillStyle = maneColors[anim];
    ctx.beginPath();
    ctx.moveTo(-h.size / 2, -h.size / 2);
    ctx.lineTo(-h.size / 2 + 12, -h.size / 2 - 12);
    ctx.lineTo(-h.size / 2 + 24, -h.size / 2 - 24);
    ctx.lineTo(-h.size / 2 + 18, -h.size / 2 - 32);
    ctx.lineTo(-h.size / 2 + 4, -h.size / 2 - 28);
    ctx.lineTo(-h.size / 2 + 10, -h.size / 2 - 20);
    ctx.closePath();
    ctx.fill();

    // Tail
    ctx.fillStyle = h.tailColor;
    ctx.beginPath();
    ctx.moveTo(h.size / 2, -h.size / 2);
    ctx.lineTo(h.size / 2 - 8, -h.size / 2 - 8);
    ctx.lineTo(h.size / 2 - 20, -h.size / 2 - 20);
    ctx.lineTo(h.size / 2 - 28, -h.size / 2 - 12);
    ctx.lineTo(h.size / 2 - 22, -h.size / 2 - 4);
    ctx.closePath();
    ctx.fill();

    // Head details
    ctx.fillStyle = '#3A2412';
    ctx.beginPath();
    ctx.arc(0, -h.size / 2 + 10, 8, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#1A1008';
    ctx.beginPath();
    ctx.arc(6, -h.size / 2 + 12, 2, 0, Math.PI * 2);
    ctx.arc(-6, -h.size / 2 + 12, 2, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#FFFFFF';
    ctx.beginPath();
    ctx.arc(4, -h.size / 2 + 14, 1, 0, Math.PI * 2);
    ctx.arc(-4, -h.size / 2 + 14, 1, 0, Math.PI * 2);
    ctx.fill();

    ctx.restore();
  }

  function renderHUD() {
    ctx.fillStyle = 'rgba(0, 0, 0, 0.55)';
    ctx.fillRect(0, 0, state.width, 30);
    ctx.fillStyle = '#FFD700';
    ctx.font = 'bold 20px Arial';
    ctx.textAlign = 'left';
    ctx.fillText(`Score: ${state.score}`, 10, 25);
    ctx.font = 'bold 16px Arial';
    ctx.fillText(`Best: ${state.bestScore}`, 10, 50);

    if (state.gameOver) {
      ctx.fillStyle = 'rgba(0, 0, 0, 0.75)';
      ctx.fillRect(0, 0, state.width, state.height);
      ctx.fillStyle = '#FFD700';
      ctx.font = 'bold 48px Arial';
      ctx.textAlign = 'center';
      ctx.fillText(state.score >= state.bestScore ? '🎉 NEW RECORD!' : 'Game Over', state.width / 2, state.height / 2 - 40);
      ctx.font = 'bold 20px Arial';
      ctx.fillText('Press ENTER to restart', state.width / 2, state.height / 2 + 20);
      ctx.fillText('SPACE to jump', state.width / 2, state.height / 2 + 50);
      ctx.fillText('ARROW KEYS to steer', state.width / 2, state.height / 2 + 80);
    } else if (state.paused) {
      ctx.fillStyle = 'rgba(0, 0, 0, 0.75)';
      ctx.fillRect(0, 0, state.width, state.height);
      ctx.fillStyle = '#FFD700';
      ctx.font = 'bold 48px Arial';
      ctx.textAlign = 'center';
      ctx.fillText('Paused', state.width / 2, state.height / 2 - 40);
      ctx.font = 'bold 20px Arial';
      ctx.fillText('Press P to resume', state.width / 2, state.height / 2 + 20);
    }
  }

  // ---------- Main Loop ----------
  let lastTime = performance.now();
  function loop(now) {
    const dt = Math.min(50, now - lastTime);
    lastTime = now;
    update(dt);
    render();
    requestAnimationFrame(loop);
  }

  // ---------- Start ----------
  init();
  requestAnimationFrame((t) => { lastTime = t; loop(t); });
})();
```

Creating a **sandbox-style shooting game editor** involves several components:

1. **Scene Editor** — Drag-and-drop placement of entities (enemies, obstacles, props).
2. **Properties Panel** — Adjust properties per entity (health, speed, spawn rate, etc.).
3. **Level Objectives** — Define win/lose conditions (e.g., kill 10 enemies, reach flag).
4. **Preview Mode** — Test the level in real time.
5. **Save/Load** — Export/import level data (JSON).
6. **UI** — Toolbars, panels, inspector, viewport.

---

## ✅ Tech Stack

We'll use **HTML5 Canvas + vanilla JS** for a lightweight, embeddable editor. It's not a full game engine, but it's sandbox-friendly and runs in any modern browser.

---

## 🧩 Features Implemented

- Drag-and-drop entities onto the canvas.
- Properties panel per selected entity.
- Level objectives (flags, counters).
- Real-time preview.
- Save/load JSON.
- Undo stack (basic).
- Entity types: Player, Enemy, Obstacle, Prop.

---

## 📁 File Structure

We'll keep everything in a single HTML file for simplicity.

---

