<!doctype html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Modular Synth Studio</title>
<link rel="stylesheet" href="style.css">
</head>
<body>
<div class="app">
  <header class="topbar">
    <div class="brand">
      <div class="logo">◈</div>
      <h1>Modular Synth Studio</h1>
    </div>
    <div class="status" id="status">Ready</div>
    <div class="controls">
      <button id="playBtn" class="btn" title="Play/Pause">▶</button>
      <button id="stopBtn" class="btn" title="Stop">■</button>
      <button id="exportBtn" class="btn" title="Export WAV">💾</button>
      <button id="resetBtn" class="btn" title="Reset">↺</button>
    </div>
  </header>

  <div class="canvas-wrap">
    <canvas id="patchCanvas"></canvas>
    <div id="canvasOverlay" class="canvas-overlay"></div>
  </div>

  <aside class="sidebar">
    <section class="panel">
      <h2>Modules</h2>
      <div id="moduleList"></div>
    </section>

    <section class="panel">
      <h2>Library</h2>
