<div class="app">
  <aside class="sidebar">
    <div class="panel">
      <h2><i class="fa-solid fa-image"></i> Image</h2>
      <div class="btn" id="btnUpload"><i class="fa-solid fa-cloud-arrow-up"></i> Upload Image</div>
      <input type="file" id="fileInput" accept="image/*" hidden>
    </div>

    <div class="panel">
      <h2><i class="fa-solid fa-face-smile"></i> Stickers</h2>
      <div class="emoji-list" id="emojiList"></div>
    </div>

    <div class="panel">
      <h2><i class="fa-solid fa-pen"></i> Controls</h2>
      <div class="btn-group">
        <button class="btn" id="btnAdd" title="Add sticker"><i class="fa-solid fa-plus"></i> Add</button>
        <button class="btn danger" id="btnDelete" title="Delete selected"><i class="fa-solid fa-trash"></i> Delete</button>
        <button class="btn" id="btnUndo" title="Undo"><i class="fa-solid fa-rotate-left"></i> Undo</button>
        <button class="btn" id="btnRedo" title="Redo"><i class="fa-solid fa-rotate-right"></i> Redo</button>
      </div>
      <div class="controls">
        <div class="label">X</div>
        <input type="number" id="posX" value="0" min="-500" max="500">
        <div class="label">Y</div>
        <input type="number" id="posY" value="0" min="-500" max="500">
      </div>
      <div class="controls">
        <div class="label">W</div>
        <input type="number" id="sizeW" value="100" min="10" max="500">
        <div class="label">H</div>
        <input type="number" id="sizeH" value="100" min="10" max="500">
      </div>
      <div class="controls">
        <div class="label">Rotation</div>
        <input type="number" id="rot" value="0" min="-180" max="180">
      </div>
      <div class="controls">
        <div class="label">Opacity</div>
        <input type="range" id="opacity" min="0" max="1" step="0.05" value="1">
      </div>
      <div class="controls">
        <div class="label">Effect</div>
        <select id="effect">
          <option value="none">None</option>
          <option value="bounce">Bounce</option>
          <option value="wiggle">Wiggle</option>
          <option value="pulse">Pulse</option>
          <option value="float">Float</option>
          <option value="spin">Spin</option>
        </select>
      </div>
      <div class="controls">
        <div class="label">Duration (s)</div>
        <input type="number" id="duration" value="3" min="0.5" max="10" step="0.1">
      </div>
      <div class="controls">
        <div class="label">Speed</div>
        <input type="range" id="speed" min="0" max="3" step="0.1" value="1">
      </div>
      <button class="btn" id="btnClear" title="Clear all"><i class="fa-solid fa-trash"></i> Clear All</button>
    </div>

    <div class="panel">
      <h2><i class="fa-solid fa-layer-group"></i> Layers</h2>
      <div id="layersList"></div>
    </div>

    <div class="panel">
      <h2><i class="fa-solid fa-cog"></i> Settings</h2>
      <div class="btn-group">
        <button class="btn" id="btnGrid" title="Toggle grid"><i class="fa-solid fa-grid-2"></i> Grid</button>
        <button class="btn" id="btnSnap" title="Snap to grid"><i class="fa-solid fa-magnifying-glass"></i> Snap</button>
      </div>
      <div class="controls">
        <div class="label">Grid size</div>
        <input type="number" id="gridSize" value="20" min="5" max="100">
      </div>
    </div>
  </aside>

  <main class="main">
    <div class="toolbar">
      <button class="btn" id="btnPlay" title="Play/Pause"><i class="fa-solid fa-play"></i> Play</button>
      <button class="btn" id="btnPause" title="Pause"><i class="fa-solid fa-pause"></i> Pause</button>
      <button class="btn" id="btnStop" title="Stop"><i class="fa-solid fa-stop"></i> Stop</button>
      <button class="btn" id="btnFrame" title="Take frame"><i class="fa-solid fa-camera"></i> Frame</button>
      <button class="btn" id="btnRecord" title="Record video"><i class="fa-solid fa-film"></i> Record</button>
      <button class="btn" id="btnGif" title="Export GIF"><i class="fa-solid fa-gif"></i> GIF</button>
      <button class="btn" id="btnWebm" title="Export WebM"><i class="fa-solid fa-video"></i> WebM</button>
      <button class="btn" id="btnDownload" title="Download"><i class="fa-solid fa-download"></i> Download</button>
      <button class="btn" id="btnReset" title="Reset"><i class="fa-solid fa-rotate"></i> Reset</button>
    </div>
    <div id="stage">
      <canvas id="stageCanvas"></canvas>
      <div class="canvas-overlay" id="canvasOverlay">
        <i class="fa-solid fa-image"></i> <span id="canvasOverlayText">Drop image or click upload</span>
      </div>
    </div>
    <div class="preview-controls">
      <button class="btn" id="btnPreview" title="Preview mode"><i class="fa-solid fa-eye"></i> Preview</button>
      <span id="previewInfo" style="color: var(--primary); font-weight: 500; margin: 0 8px;">Ready</span>
      <button class="btn" id="btnClearCanvas" title="Clear canvas"><i class="fa-solid fa-eraser"></i> Clear</button>
    </div>
    <div class="export-panel">
      <button class="btn" id="btnExport" title="Export PNG"><i class="fa-solid fa-file-image"></i> PNG</button>
      <button class="btn" id="btnShare" title="Share"><i class="fa-solid fa-share-nodes"></i> Share</button>
    </div>
  </main>
</div>

<div class="toast" id="toast" hidden></div>

