<script>
// ---------- Shape Definitions ----------
const SHAPES = {
  circle: {
    label: 'Circle',
    params: [{ key: 'r', label: 'Radius', step: 0.1 }],
    formulas: {
      area: 'A = π × r²',
      circumference: 'C = 2 × π × r'
    },
    compute: (params) => {
      const r = parseFloat(params.r);
      return { area: Math.PI * r * r, circumference: 2 * Math.PI * r };
    },
    draw: (ctx, params) => {
      const r = parseFloat(params.r);
      const x = 300, y = 200;
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fillStyle = '#dbeafe';
      ctx.fill();
      ctx.strokeStyle = '#93c5fd';
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.fillStyle = '#1e3a8a';
      ctx.font = '11px "JetBrains Mono", monospace';
      ctx.fillText('r', x + r + 4, y + 3);
    }
  },
  triangle: {
    label: 'Triangle',
    params: [{ key: 'a', label: 'Side a', step: 0.1 }],
    formulas: {
      area: 'A = √[s(s−a)(s−b)(s−c)]',
      perimeter: 'P = a + b + c'
    },
    compute: (params) => {
      const a = parseFloat(params.a);
      const b = a, c = a;
      const s = (a + b + c) / 2;
      const area = Math.sqrt(s * (s - a) * (s - b) * (s - c));
      return { area, perimeter: a + b + c };
    },
    draw: (ctx, params) => {
      const a = parseFloat(params.a);
      const x = 300, y = 200;
      ctx.beginPath();
      ctx.moveTo(x, y - a);
      ctx.lineTo(x - a, y + a);
      ctx.lineTo(x + a, y + a);
      ctx.closePath();
      ctx.fillStyle = '#f3e8ff';
      ctx.fill();
      ctx.strokeStyle = '#c7a2f7';
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.fillStyle = '#4c1d95';
      ctx.font = '10px "JetBrains Mono", monospace';
      ctx.fillText('a', x - a + 3, y + a - 3);
      ctx.fillText('a', x + a - 3, y + a - 3);
      ctx.fillText('a', x + 3, y - a - 3);
    }
  },
  rectangle: {
    label: 'Rectangle',
    params: [
      { key: 'w', label: 'Width', step: 0.1 },
      { key: 'h', label: 'Height', step: 0.1 }
    ],
    formulas: {
      area: 'A = w × h',
      perimeter: 'P = 2 × (w + h)'
    },
    compute: (params) => {
      const w = parseFloat(params.w), h = parseFloat(params.h);
      return { area: w * h, perimeter: 2 * (w + h) };
    },
    draw: (ctx, params) => {
      const w = parseFloat(params.w), h = parseFloat(params.h);
      const x = 300, y = 200;
      ctx.beginPath();
      ctx.rect(x - w / 2, y - h / 2, w, h);
      ctx.fillStyle = '#f1f5f9';
      ctx.fill();
      ctx.strokeStyle = '#94a3b8';
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.fillStyle = '#475569';
      ctx.font = '10px "JetBrains Mono", monospace';
      ctx.fillText('w', x + w / 2 - 4, y + h / 2 + 3);
      ctx.fillText('h', x + w / 2 - 4, y - h / 2 - 3);
    }
  },
  polygon: {
    label: 'Regular Polygon',
    params: [
      { key: 'n', label: 'Sides (3–12)', step: 1, type: 'number', min: 3, max: 12, value: 6 },
      { key: 's', label: 'Side Length', step: 0.1 }
    ],
    formulas: {
      area: 'A = (n × s²) / (4 × tan(π/n))',
      perimeter: 'P = n × s'
    },
    compute: (params) => {
      const n = parseInt(params.n, 10);
      const s = parseFloat(params.s);
      const apothem = s / (2 * Math.tan(Math.PI / n));
      const area = (n * s * apothem) / 2;
      return { area, perimeter: n * s };
    },
    draw: (ctx, params) => {
      const n = parseInt(params.n, 10);
      const s = parseFloat(params.s);
      const cx = 300, cy = 200;
      const radius = s / (2 * Math.sin(Math.PI / n));
      const angle = (Math.PI * 2) / n;
      ctx.beginPath();
      ctx.moveTo(cx + radius * Math.cos(-angle / 2), cy + radius * Math.sin(-angle / 2));
      for (let i = 1; i <= n; i++) {
        const x = cx + radius * Math.cos(-angle / 2 + i * angle);
        const y = cy + radius * Math.sin(-angle / 2 + i * angle);
        ctx.lineTo(x, y);
      }
      ctx.closePath();
      ctx.fillStyle = '#ede9fe';
      ctx.fill();
      ctx.strokeStyle = '#a78bfa';
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.fillStyle = '#7c3aed';
      ctx.font = '10px "JetBrains Mono", monospace';
      ctx.fillText('s', cx + radius * Math.cos(-angle / 2 + angle * 0.5), cy + radius * Math.sin(-angle / 2 + angle * 0.5) + 3);
    }
  },
  sphere: {
    label: 'Sphere',
    params: [{ key: 'r', label: 'Radius', step: 0.1 }],
    formulas: {
      surfaceArea: 'A = 4 × π × r²',
      volume: 'V = (4/3) × π × r³'
    },
    compute: (params) => {
      const r = parseFloat(params.r);
      return { surfaceArea: 4 * Math.PI * r * r, volume: (4 / 3) * Math.PI * r * r * r };
    },
    draw: (ctx, params) => {
      const r = parseFloat(params.r);
      const x = 300, y = 200;
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fillStyle = '#fde68a';
      ctx.fill();
      ctx.strokeStyle = '#f59e0b';
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.fillStyle = '#b45309';
      ctx.font = '11px "JetBrains Mono", monospace';
      ctx.fillText('r', x + r + 4, y + 3);
    }
  },
  cylinder: {
    label: 'Cylinder',
    params: [
      { key: 'r', label: 'Base Radius', step: 0.1 },
      { key: 'h', label: 'Height', step: 0.1 }
    ],
    formulas: {
      surfaceArea: 'A = 2 × π × r² + 2 × π × r × h',
      volume: 'V = π × r² × h'
    },
    compute: (params) => {
      const r = parseFloat(params.r), h = parseFloat(params.h);
      return {
        surfaceArea: 2 * Math.PI * r * r + 2 * Math.PI * r * h,
        volume: Math.PI * r * r * h
      };
    },
    draw: (ctx, params) => {
      const r = parseFloat(params.r), h = parseFloat(params.h);
      const x = 300, y = 200;
      // Top ellipse
      ctx.beginPath();
      ctx.ellipse(x, y - h / 2, r, r / 2, 0, 0, Math.PI * 2);
      ctx.fillStyle = '#f3e8ff';
      ctx.fill();
      ctx.strokeStyle = '#c7a2f7';
      ctx.lineWidth = 2;
      ctx.stroke();
      // Body
      ctx.beginPath();
      ctx.ellipse(x, y, r, r / 2, 0, 0, Math.PI * 2);
      ctx.fillStyle = '#ede9fe';
      ctx.fill();
      ctx.strokeStyle = '#94a3b8';
      ctx.lineWidth = 2;
      ctx.stroke();
      // Bottom ellipse
      ctx.beginPath();
      ctx.ellipse(x, y + h / 2, r, r / 2, 0, 0, Math.PI * 2);
      ctx.fillStyle = '#f3e8ff';
      ctx.fill();
      ctx.strokeStyle = '#c7a2f7';
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.fillStyle = '#4c1d95';
      ctx.font = '10px "JetBrains Mono", monospace';
      ctx.fillText('r', x + r + 4, y + 3);
      ctx.fillText('h', x + r + 4, y + h / 2 + 3);
    }
  },
  cone: {
    label: 'Cone',
    params: [
      { key: 'r', label: 'Base Radius', step: 0.1 },
      { key: 'h', label: 'Height', step: 0.1 }
    ],
    formulas: {
      surfaceArea: 'A = π × r² + π × r × l',
      volume: 'V = (1/3) × π × r² × h',
      slantHeight: 'l = √(r² + h²)'
    },
    compute: (params) => {
      const r = parseFloat(params.r), h = parseFloat(params.h);
      const l = Math.sqrt(r * r + h * h);
      return {
        surfaceArea: Math.PI * r * r + Math.PI * r * l,
        volume: (1 / 3) * Math.PI * r * r * h,
        slantHeight: l
      };
    },
    draw: (ctx, params) => {
      const r = parseFloat(params.r), h = parseFloat(params.h);
      const x = 300, y = 200;
      // Base ellipse
      ctx.beginPath();
      ctx.ellipse(x, y - h / 2, r, r / 2, 0, 0, Math.PI * 2);
      ctx.fillStyle = '#f3e8ff';
      ctx.fill();
      ctx.strokeStyle = '#c7a2f7';
      ctx.lineWidth = 2;
      ctx.stroke();
      // Body
      ctx.beginPath();
      ctx.moveTo(x - r, y - h / 2);
      ctx.lineTo(x, y + h);
      ctx.lineTo(x + r, y - h / 2);
      ctx.closePath();
      ctx.fillStyle = '#ede9fe';
      ctx.fill();
      ctx.strokeStyle = '#94a3b8';
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.fillStyle = '#4c1d95';
      ctx.font = '10px "JetBrains Mono", monospace';
      ctx.fillText('r', x + r + 4, y + 3);
      ctx.fillText('h', x + r + 4, y + h / 2 + 3);
    }
  },
  prism: {
    label: 'Rectangular Prism',
    params: [
      { key: 'l', label: 'Length', step: 0.1 },
      { key: 'w', label: 'Width', step: 0.1 },
      { key: 'h', label: 'Height', step: 0.1 }
    ],
    formulas: {
      surfaceArea: 'A = 2 × (lw + lh + wh)',
      volume: 'V = l × w × h'
    },
    compute: (params) => {
      const l = parseFloat(params.l), w = parseFloat(params.w), h = parseFloat(params.h);
      return {
        surfaceArea: 2 * (l * w + l * h + w * h),
        volume: l * w * h
      };
    },
    draw: (ctx, params) => {
      const l = parseFloat(params.l), w = parseFloat(params.w), h = parseFloat(params.h);
      const x = 300, y = 200;
      // Front face
      ctx.beginPath();
      ctx.moveTo(x - l / 2, y - h / 2);
      ctx.lineTo(x + l / 2, y - h / 2);
      ctx.lineTo(x + l / 2, y + h / 2);
      ctx.lineTo(x - l / 2, y + h / 2);
      ctx.closePath();
      ctx.fillStyle = '#f1f5f9';
      ctx.fill();
      ctx.strokeStyle = '#94a3b8';
      ctx.lineWidth = 2;
      ctx.stroke();
      // Top face
      ctx.beginPath();
      ctx.moveTo(x - l / 2, y - h / 2);
      ctx.lineTo(x + l / 2, y - h / 2);
      ctx.lineTo(x + l / 2, y - h / 2 - w / 2);
      ctx.lineTo(x - l / 2, y - h / 2 - w / 2);
      ctx.closePath();
      ctx.fillStyle = '#e2e8f0';
      ctx.fill();
      ctx.strokeStyle = '#94a3b8';
      ctx.lineWidth = 2;
      ctx.stroke();
      // Right face
      ctx.beginPath();
      ctx.moveTo(x + l / 2, y - h / 2);
      ctx.lineTo(x + l / 2, y + h / 2);
      ctx.lineTo(x + l / 2 + w / 2, y + h / 2);
      ctx.lineTo(x + l / 2 + w / 2, y - h / 2);
      ctx.closePath();
      ctx.fillStyle = '#e2e8f0';
      ctx.fill();
      ctx.strokeStyle = '#94a3b8';
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.fillStyle = '#475569';
      ctx.font = '10px "JetBrains Mono", monospace';
      ctx.fillText('l', x + l / 2 - 3, y + h / 2 + 3);
      ctx.fillText('w', x + l / 2 + w / 2 - 3, y + h / 2 + 3);
      ctx.fillText('h', x + l / 2 - 3, y - h / 2 - 3);
    }
  }
};

