// ---------- Build UI ----------
function buildShapeButtons() {
  shapeGroup.innerHTML = '';
  Object.entries(SHAPES).forEach(([key, shape]) => {
    const btn = document.createElement('button');
    btn.className = 'shape-btn' + (key === currentShape ? ' active' : '');
    btn.textContent = shape.label;
    btn.dataset.shape = key;
    btn.addEventListener('click', () => selectShape(key));
    shapeGroup.appendChild(btn);
  });
}

function selectShape(key) {
  currentShape = key;
  params = {};
  Object.entries(SHAPES[key].params).forEach(([pKey, p]) => {
    params[pKey] = p.value ?? (p.type === 'number' ? 1 : '');
  });
  buildInputs();
  buildFormula();
  draw();
}

function buildInputs() {
  const container = document.getElementById('shapeInputs');
  container.innerHTML = '';
  Object.entries(SHAPES[currentShape].params).forEach(([pKey, p]) => {
    const row = document.createElement('div');
    row.className = 'input-row';
    row.dataset.param = pKey;
    row.innerHTML = `
      <label for="${pKey}">${p.label}</label>
      <input id="${pKey}" type="${p.type || 'number'}" step="${p.step}" min="${p.min || ''}" max="${p.max || ''}" value="${params[pKey]}" />
    `;
    container.appendChild(row);
  });
  attachInputHandlers();
}

function attachInputHandlers() {
  const container = document.getElementById('shapeInputs');
  container.querySelectorAll('input').forEach(input => {
    input.addEventListener('input', () => {
      const key = input.dataset.param;
      params[key] = input.value;
      validateInput(input);
      draw();
    });
    input.addEventListener('keydown', (e) => {
      if (e.key === 'ArrowUp') { e.target.step = e.target.step * 10 || 1; e.target.step = parseFloat(e.target.step); e.target.value = parseFloat(e.target.value) + parseFloat(e.target.step); e.target.dispatchEvent(new Event('input')); e.preventDefault(); }
      else if (e.key === 'ArrowDown') { e.target.step = e.target.step * 10 || 1; e.target.step = parseFloat(e.target.step); e.target.value = parseFloat(e.target.value) - parseFloat(e.target.step); e.target.dispatchEvent(new Event('input')); e.preventDefault(); }
    });
  });
}

function validateInput(input) {
  const key = input.dataset.param;
  const p = SHAPES[currentShape].params.find(x => x.key === key);
  const val = parseFloat(input.value);
  if (!Number.isFinite(val) || (p.min !== undefined && val < p.min) || (p.max !== undefined && val > p.max)) {
    input.classList.add('invalid');
  } else {
    input.classList.remove('invalid');
  }
}

function buildFormula() {
  const shape = SHAPES[currentShape];
  formulaTitle.textContent = `${shape.label} Formulas`;
  formulaContent.innerHTML = '';
  Object.entries(shape.formulas).forEach(([key, formula]) => {
    const div = document.createElement('div');
    div.innerHTML = `<code>${formula}</code>`;
    formulaContent.appendChild(div);
  });
}

function draw() {
  const shape = SHAPES[currentShape];
  const paramsObj = {};
  Object.entries(params).forEach(([k, v]) => { paramsObj[k] = parseFloat(v); });
  const result = shape.compute(paramsObj);

  canvasLabel.textContent = `${shape.label} — ${Object.entries(params).map(([k, v]) => `${k}: ${v}`).join(', ')}`;
  canvasEl.width = 600;
  canvasEl.height = 400;
  ctx = canvasEl.getContext('2d');
  ctx.clearRect(0, 0, 600, 400);
  shape.draw(ctx, params);

  renderResults(result, shape);
}

function renderResults(result, shape) {
  resultsEl.innerHTML = '';
  const keys = Object.keys(result);
  keys.forEach(k => {
    const card = document.createElement('div');
    card.className = 'result-card';
    const label = k.charAt(0).toUpperCase() + k.slice(1);
    const value = result[k] === undefined ? '' : result[k].toFixed(2);
    card.innerHTML = `
      <h4>${label}</h4>
      <div class="result-value">${value}</div>
      <div class="result-unit">${shape.label.includes('Solid') ? 'm³' : 'm²'}</div>
    `;
    resultsEl.appendChild(card);
  });
}

function copyResults() {
  const shape = SHAPES[currentShape];
  const keys = Object.keys(result);
  const lines = [];
  keys.forEach(k => {
    const label = k.charAt(0).toUpperCase() + k.slice(1);
    const value = result[k] === undefined ? '' : result[k].toFixed(2);
    lines.push(`${label}: ${value} ${shape.label.includes('Solid') ? 'm³' : 'm²'}`);
  });
  navigator.clipboard?.writeText(lines.join('\n'))?.then(() => {
    copyBtn.textContent = '✓ Copied';
    setTimeout(() => { copyBtn.textContent = '📋 Copy Results'; }, 1500);
  });
}

// ---------- Init ----------
function init() {
  canvas = canvasEl;
  buildShapeButtons();
  buildInputs();
  buildFormula();
  draw();
  canvasWrap.addEventListener('click', () => {
    if (canvasWrap.contains(event.target)) {
      canvasEl.focus();
    }
  });
  formulaToggle.addEventListener('click', () => {
    formulaPanel.classList.toggle('collapsed');
    const icon = document.getElementById('formulaIcon');
    if (formulaPanel.classList.contains('collapsed')) {
      icon.innerHTML = '<path d="M4 15s1-1 4-1 5 2 8 2 4-1 4-1V3s-1 1-4 1-5-2-8-2-4 1-4 1z"/><line x1="4" y1="22" x2="4" y2="15"/>';
      formulaToggle.querySelector('span').textContent = 'Hide Formulas';
    } else {
      icon.innerHTML = '<path d="M4 15s1-1 4-1 5 2 8 2 4-1 4-1V3s-1 1-4 1-5-2-8-2-4 1-4 1z"/><line x1="12" y1="19" x2="20" y2="11"/><line x1="12" y1="5" x2="20" y2="13"/></svg>';
      formulaToggle.querySelector('span').textContent = 'Formulas';
    }
  });
  copyBtn.addEventListener('click', copyResults);
  resetBtn.addEventListener('click', () => {
    selectShape('circle');
  });
}

document.addEventListener('DOMContentLoaded', init);
</script>
</body>
</html>
