## ⚙️ scheduler.js

```javascript
(() => {
  'use strict';

  const STORAGE_KEY = 'scheduler.tasks.v1';
  const POLL_INTERVAL = 30000; // 30 seconds
  const PERIODIC_INTERVAL = 60000; // check for hourly recurrence every minute

  const form = document.getElementById('task-form');
  const nameInput = document.getElementById('task-name');
  const descInput = document.getElementById('task-desc');
  const timeInput = document.getElementById('task-time');
  const recurInput = document.getElementById('task-recur');
  const jsInput = document.getElementById('task-js');
  const listEl = document.getElementById('tasks-list');
  const emptyEl = document.getElementById('empty-state');

  const tasks = loadTasks();

  // --- Storage ---
  function loadTasks() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return [];
      const parsed = JSON.parse(raw);
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  }

  function saveTasks() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
    } catch {
      // ignore
    }
  }

  // --- Task model ---
  class Task {
    constructor(id, name, description, time, recur, js) {
      this.id = id;
      this.name = name.trim();
      this.description = description.trim();
      this.time = time; // HH:MM 24h
      this.recur = recur;
      this.js = js.trim();
      this.createdAt = Date.now();
    }

    isDue(now) {
      const [h, m] = this.time.split(':').map(Number);
      const dueHour = h + (m / 60);
      const nowHour = now.getHours() + (now.getMinutes() / 60);

      // Due today at the specified time
      const todayDue = nowHour >= dueHour;
      // For recurring, also check if it's the right day of week
      const isRightDay = this.recur === 'daily' ||
                         (this.recur === 'weekly' && now.getDay() === this.dayOfWeek);

      if (this.recur === 'once') return todayDue && nowHour >= dueHour;
      if (this.recur === 'hourly') return nowHour >= dueHour;
      if (this.recur === 'daily') return todayDue && nowHour >= dueHour;
      if (this.recur === 'weekly') return todayDue && nowHour >= dueHour && isRightDay;

      return false;
    }

    // For weekly: store the dayOfWeek as a number (0..6)
    static fromJSON(obj) {
      if (!obj.dayOfWeek && obj.recur === 'weekly') {
        obj.dayOfWeek = new Date(obj.createdAt).getDay();
      }
      return new Task(
        obj.id,
        obj.name,
        obj.description,
        obj.time,
        obj.recur,
        obj.js
      );
    }
  }

  // --- UI ---
  function renderTasks() {
    listEl.innerHTML = '';
    if (tasks.length === 0) {
      emptyEl.style.display = '';
      return;
    }
    emptyEl.style.display = 'none';

    tasks.forEach(t => listEl.appendChild(renderTaskElement(t)));
  }

  function renderTaskElement(t) {
    const el = document.createElement('div');
    el.className = 'task';
    el.innerHTML = `
      <div class="task-name">${escapeHtml(t.name)}</div>
      <div class="task-meta">
        ${t.description ? `<span class="dot">·</span> ${escapeHtml(t.description)}</div>` : ''}
        <span class="task-meta">Due: ${formatTime(t.time)} · Recur: ${escapeHtml(t.recur)}</span>
        ${t.js ? `<div class="task-js">${escapeHtml(t.js)}</div>` : ''}
      </div>
    `;
    return el;
  }

  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, c => ({
      '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    }[c]));
  }

  function formatTime(t) {
    const [h, m] = t.split(':').map(Number);
    const ampm = h >= 12 ? 'PM' : 'AM';
    const hour12 = ((h + 11) % 12) + 1;
    return `${hour12}:${String(m).padStart(2, '0')} ${ampm}`;
  }

  // --- Notification ---
  function showNotification(task) {
    if (!('Notification' in window)) return;
    if (Notification.permission !== 'granted') {
      Notification.requestPermission().then(p => {
        if (p === 'granted') showNotification(task);
      });
      return;
    }
    const icon = 'data:image/svg+xml;utf8,' +
      encodeURIComponent(
        '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="M12 8v4"/><path d="M12 16h.01"/></svg>'
      );
    const n = new Notification(
      task.name,
      {
        body: task.description || task.js || 'Task is due!',
        icon,
        silent: false
      }
    );
    n.onclick = () => {
      try { eval(task.js); } catch (e) { /* ignore */ }
    };
  }

  // --- Execution ---
  function executeJs(task) {
    try {
      // Wrap in a try/catch to avoid crashing the whole page
      const fn = new Function('task', 'console.log("Executing task:", task);' + task.js);
      fn(task);
    } catch (e) {
      console.warn('Task JS execution failed:', e);
    }
  }

  // --- Polling ---
  let lastPoll = Date.now();
  function poll() {
    const now = Date.now();
    if (now - lastPoll < POLL_INTERVAL) return;
    lastPoll = now;

    tasks.forEach(t => {
      if (t.isDue(now)) {
        // Mark as executed (optional)
        t.createdAt = now;
        showNotification(t);
        executeJs(t);
        saveTasks();
      }
    });
  }

  // --- Hourly recurrence check ---
  function checkHourlyRecurrences() {
    const now = new Date();
    const hour = now.getHours();
    tasks.forEach(t => {
      if (t.recur === 'hourly' && t.time === '00:00') {
        if (hour === 0) {
          showNotification(t);
          executeJs(t);
          saveTasks();
        }
      }
    });
  }

  // --- Add task ---
  form.addEventListener('submit', (e) => {
    e.preventDefault();
    const name = nameInput.value;
    const desc = descInput.value;
    const time = timeInput.value;
    const recur = recurInput.value;
    const js = jsInput.value;

    if (!name || !time) {
      alert('Please fill in name and time.');
      return;
    }

    const id = 't_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7);
    const task = new Task(id, name, desc, time, recur, js);
    tasks.push(task);
    saveTasks();
    renderTasks();
    form.reset();
    nameInput.focus();
  });

  // --- Cleanup ---
  window.addEventListener('beforeunload', () => {
    // Save before leaving
    saveTasks();
  });

  // --- Init ---
  function init() {
    renderTasks();
    // Start polling
    setInterval(poll, POLL_INTERVAL);
    setInterval(checkHourlyRecurrences, PERIODIC_INTERVAL);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
