// =========================================================
// Geometric Proof System
// =========================================================
// A web-based interactive geometric proof assistant.
// Users draw figures, add conditions, and the system
// automatically builds a proof tree with derivations.
// =========================================================

(function () {
  'use strict';

  // ---------- Canvas & UI ----------
  const canvas = document.getElementById('canvas');
  const ctx = canvas.getContext('2d');
  const toolSelect = document.getElementById('tool');
  const conditionInput = document.getElementById('condition-input');
  const conditionBtn = document.getElementById('condition-btn');
  const conditionList = document.getElementById('condition-list');
  const proofTree = document.getElementById('proof-tree');
  const verifyBtn = document.getElementById('verify-btn');
  const verifyResult = document.getElementById('verify-result');
  const clearBtn = document.getElementById('clear-btn');
  const zoomInBtn = document.getElementById('zoom-in');
  const zoomOutBtn = document.getElementById('zoom-out');

  let scale = 1;
  let offsetX = 0;
  let offsetY = 0;
  let currentTool = 'point';
  let points = [];
  let segments = [];
  let conditions = [];
  let selectedSegment = null;
  let selectedPoint = null;
  let currentProof = []; // {step, premise, conclusion, explanation}

  // ---------- Coordinate helpers ----------
  function worldToScreen(x, y) {
    return {
      x: (x - offsetX) * scale,
      y: (y - offsetY) * scale
    };
  }
  function screenToWorld(x, y) {
    return {
      x: (x / scale) + offsetX,
      y: (y / scale) + offsetY
    };
  }
  function snapToGrid(p, gridSize = 20) {
    return {
      x: Math.round(p.x / gridSize) * gridSize,
      y: Math.round(p.y / gridSize) * gridSize
    };
  }

  // ---------- Drawing ----------
  function drawGrid() {
    const w = canvas.width / scale;
    const h = canvas.height / scale;
    const gridSize = 20;
    ctx.strokeStyle = '#e0e0e0';
    ctx.lineWidth = 1;
    ctx.setLineDash([]);
    for (let x = -gridSize; x <= w; x += gridSize) {
      ctx.beginPath();
      ctx.moveTo(x + offsetX * scale, 0);
      ctx.lineTo(x + offsetX * scale, h);
      ctx.stroke();
    }
    for (let y = -gridSize; y <= h; y += gridSize) {
      ctx.beginPath();
      ctx.moveTo(0 + offsetX * scale, y + offsetY * scale);
      ctx.lineTo(w + offsetX * scale, y + offsetY * scale);
      ctx.stroke();
    }
  }

  function drawPoints() {
    ctx.fillStyle = '#333';
    ctx.strokeStyle = '#666';
    ctx.lineWidth = 2;
    for (const p of points) {
      const s = worldToScreen(p.x, p.y);
      ctx.beginPath();
      ctx.arc(s.x, s.y, 6 * scale, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
      // Label
      ctx.fillStyle = '#000';
      ctx.font = '11px "Consolas", monospace';
      ctx.textAlign = 'left';
      ctx.textBaseline = 'top';
      ctx.fillText(`P${points.indexOf(p)}`, s.x + 10 * scale, s.y - 10 * scale);
    }
  }

  function drawSegments() {
    ctx.strokeStyle = '#222';
    ctx.lineWidth = 2 * scale;
    ctx.lineCap = 'round';
    for (const seg of segments) {
      const a = worldToScreen(seg.a.x, seg.a.y);
      const b = worldToScreen(seg.b.x, seg.b.y);
      ctx.beginPath();
      ctx.moveTo(a.x, a.y);
      ctx.lineTo(b.x, b.y);
      ctx.stroke();
    }
  }

  function drawConditions() {
    ctx.fillStyle = '#333';
    ctx.font = '12px "Consolas", monospace';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    for (const c of conditions) {
      const a = worldToScreen(c.a.x, c.a.y);
      const b = worldToScreen(c.b.x, c.b.y);
      ctx.beginPath();
      ctx.moveTo(a.x, a.y);
      ctx.lineTo(b.x, b.y);
      ctx.stroke();
      ctx.fillText(c.text, a.x + 12 * scale, a.y - 10 * scale);
    }
  }

  function drawSelected() {
    if (selectedSegment) {
      const a = worldToScreen(selectedSegment.a.x, selectedSegment.a.y);
      const b = worldToScreen(selectedSegment.b.x, selectedSegment.b.y);
      ctx.strokeStyle = '#ff5555';
      ctx.lineWidth = 3 * scale;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(a.x, a.y);
      ctx.lineTo(b.x, b.y);
      ctx.stroke();
    }
    if (selectedPoint) {
      const s = worldToScreen(selectedPoint.x, selectedPoint.y);
      ctx.fillStyle = '#ff5555';
      ctx.strokeStyle = '#fff';
      ctx.lineWidth = 2 * scale;
      ctx.beginPath();
      ctx.arc(s.x, s.y, 10 * scale, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
    }
  }

  function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawGrid();
    drawPoints();
    drawSegments();
    drawConditions();
    drawSelected();
  }

  // ---------- Interaction ----------
  function setTool(tool) {
    currentTool = tool;
    toolSelect.value = tool;
    if (tool === 'point') {
      canvas.style.cursor = 'crosshair';
    } else {
      canvas.style.cursor = 'default';
    }
  }

  function addPoint(x, y) {
    points.push({ x, y });
    render();
  }

  function addSegment(aIdx, bIdx) {
    if (aIdx === bIdx) return;
    segments.push({ a: points[aIdx], b: points[bIdx] });
    render();
  }

  function selectPoint(idx) {
    selectedPoint = points[idx];
    selectedSegment = null;
  }
  function selectSegment(idx) {
    selectedSegment = segments[idx];
    selectedPoint = null;
  }
  function deselect() {
    selectedPoint = null;
    selectedSegment = null;
  }

  canvas.addEventListener('mousedown', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const p = screenToWorld(x, y);
    if (currentTool === 'point') {
      addPoint(p.x, p.y);
    } else {
      // Try to select
      for (let i = points.length - 1; i >= 0; i--) {
        const s = worldToScreen(points[i].x, points[i].y);
        if (Math.hypot(x - s.x, y - s.y) < 14 * scale) {
          selectPoint(i);
          render();
          return;
        }
      }
      for (let i = segments.length - 1; i >= 0; i--) {
        const seg = segments[i];
        const a = worldToScreen(seg.a.x, seg.a.y);
        const b = worldToScreen(seg.b.x, seg.b.y);
        const dx = b.x - a.x, dy = b.y - a.y;
        const len = Math.hypot(dx, dy);
        if (len < 0.0001) continue;
        const ux = dx / len, uy = dy / len;
        const px = a.x + ux * (x - a.x);
        const py = a.y + uy * (y - a.y);
        const d = Math.hypot(x - px, y - py);
        if (d < 14 * scale) {
          selectSegment(i);
          render();
          return;
        }
      }
    }
  });

  canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    if (selectedSegment) {
      const seg = selectedSegment;
      const a = worldToScreen(seg.a.x, seg.a.y);
      const b = worldToScreen(seg.b.x, seg.b.y);
      const dx = b.x - a.x, dy = b.y - a.y;
      const len = Math.hypot(dx, dy);
      if (len < 0.0001) return;
      const ux = dx / len, uy = dy / len;
      const px = a.x + ux * (x - a.x);
      const py = a.y + uy * (y - a.y);
      seg.b = { x: px, y: py };
      render();
    } else if (selectedPoint) {
      selectedPoint.x = px;
      selectedPoint.y = py;
      render();
    }
  });

  canvas.addEventListener('mouseup', () => deselect());

  canvas.addEventListener('wheel', (e) => {
    e.preventDefault();
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const p = screenToWorld(x, y);
    const factor = e.deltaY < 0 ? 1.1 : 1 / 1.1;
    scale = Math.max(0.2, Math.min(5, scale * factor));
    offsetX = p.x - (x / scale);
    offsetY = p.y - (y / scale);
    render();
  });

  // ---------- Conditions ----------
  conditionBtn.addEventListener('click', () => {
    const text = conditionInput.value.trim();
    if (!text) return;
    const idx = conditionList.children.length;
    conditions.push({ a: points[0], b: points[1], text });
    render();
    conditionInput.value = '';
  });

  conditionList.addEventListener('click', (e) => {
    const li = e.target.closest('li');
    if (!li) return;
    const idx = parseInt(li.dataset.idx, 10);
    conditions.splice(idx, 1);
    render();
  });

  // ---------- Proof Generation ----------
  // Basic geometric theorems
  const theorems = {
    // Equal sides -> equal angles (in triangle)
    'equal_sides': {
      premise: ['sides', 'a', 'b'],
      conclusion: ['angles', 'A', 'B'],
      explanation: 'In triangle ABC, if AB = AC, then ∠B = ∠C (base angles of isosceles triangle).'
    },
    'equal_angles': {
      premise: ['angles', 'A', 'B'],
      conclusion: ['sides', 'a', 'b'],
      explanation: 'In triangle ABC, if ∠A = ∠B, then AC = BC (converse of isosceles triangle theorem).'
    },
    'vertical_angles': {
      premise: ['angles', 'A', 'C'],
      conclusion: ['angles', 'B', 'D'],
      explanation: 'Vertical angles are congruent.'
    },
    'linear_pair': {
      premise: ['angles', 'A', 'B'],
      conclusion: ['angles', 'A', 'C'],
      explanation: 'If A and B form a linear pair, then A + B = 180°.'
    },
    'triangle_sum': {
      premise: ['angles', 'A', 'B', 'C'],
      conclusion: ['sum', 'A', 'B', 'C'],
      explanation: 'Sum of interior angles of a triangle is 180°.'
    },
    'angle_sum': {
      premise: ['angles', 'A', 'B', 'C'],
      conclusion: ['sum', 'A', 'B', 'C'],
      explanation: 'Sum of angles in triangle ABC is 180°.'
    },
    'isosceles_base': {
      premise: ['sides', 'a', 'b'],
      conclusion: ['angles', 'A', 'B'],
      explanation: 'In isosceles triangle ABC with AB = AC, base angles ∠B = ∠C.'
    },
    'right_triangle': {
      premise: ['angle', 'C'],
      conclusion: ['sides', 'a', 'b'],
      explanation: 'If ∠C = 90°, then triangle is right-angled at C.'
    }
  };

  function findConditions(key, args) {
    return conditions.filter(c => {
      if (key !== 'angle') return false;
      return c.text.toLowerCase().includes(args[0].toLowerCase());
    });
  }

  function findSegments(key, args) {
    return segments.filter(s => {
      const a = points[args[0]], b = points[args[1]];
      return (s.a === a && s.b === b) || (s.a === b && s.b === a);
    });
  }

  function prove() {
    currentProof = [];
    // Try to apply theorems
    const applied = [];
    let changed = true;
    let step = 0;

    while (changed && step < 10) {
      changed = false;
      step++;
      for (const name in theorems) {
        const th = theorems[name];
        const matches = th.premise.map(p => {
          if (p === 'angle') {
            return findConditions('angle', th.premise);
          }
          if (p === 'sides') {
            return findSegments('sides', th.premise);
          }
          if (p === 'angles') {
            return findConditions('angles', th.premise);
          }
          if (p === 'sum') {
            return findConditions('sum', th.premise);
          }
        });
        const allMatch = matches.every(m => m.length > 0);
        if (!allMatch) continue;
        // Check if conclusion already satisfied
        const existing = th.conclusion.map(p => {
          if (p === 'angle') return findConditions('angle', th.conclusion);
          if (p === 'sides') return findSegments('sides', th.conclusion);
          if (p === 'angles') return findConditions('angles', th.conclusion);
          if (p === 'sum') return findConditions('sum', th.conclusion);
          return [];
        });
        const anyExisting = existing.some(m => m.length > 0);
        if (anyExisting) continue;

        // Apply
        for (const c of matches) {
          c.forEach(cond => {
            if (cond.text.includes('90°')) {
              segments.push({ a: cond.a, b: cond.b });
            }
          });
        }
        currentProof.push({
          step: step,
          premise: th.premise,
          conclusion: th.conclusion,
          explanation: th.explanation
        });
        applied.push(name);
        changed = true;
        break;
      }
    }

    return { applied, proof: currentProof };
  }

  // ---------- UI Rendering ----------
  function renderProofTree() {
    proofTree.innerHTML = '';
    if (!currentProof.length) {
      proofTree.innerHTML = '<li class="empty">No proof steps yet. Add conditions and click "Verify".</li>';
      return;
    }
    for (const step of currentProof) {
      const li = document.createElement('li');
      li.className = 'step';
      li.innerHTML = `
        <span class="step-num">${step.step}.</span>
        <span class="step-p">Premise: ${step.premise.map(p => {
          if (p === 'angle') return '∠';
          if (p === 'sides') return 'AB = AC';
          if (p === 'angles') return '∠B = ∠C';
          if (p === 'sum') return 'A + B + C = 180°';
          return p;
        }).join(', ')}</span>
        <span class="step-c">→ Conclusion: ${step.conclusion.map(p => {
          if (p === 'angle') return '∠';
          if (p === 'sides') return 'AB = AC';
          if (p === 'angles') return '∠B = ∠C';
          if (p === 'sum') return 'A + B + C = 180°';
          return p;
        }).join(', ')}</span>
        <button class="explanation-btn" data-step="${step.step}">Explanation</button>
      `;
      proofTree.appendChild(li);
    }
    // Attach explanation handlers
    proofTree.querySelectorAll('.explanation-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const step = parseInt(btn.dataset.step, 10);
        const s = currentProof.find(p => p.step === step);
        if (!s) return;
        alert(s.explanation);
      });
    });
  }

  // ---------- Verify ----------
  verifyBtn.addEventListener('click', () => {
    const result = prove();
    renderProofTree();
    if (result.applied.length === 0) {
      verifyResult.textContent = 'No theorems could be applied. Try adding more conditions.';
      verifyResult.style.color = '#d32f2f';
    } else {
      verifyResult.textContent = `Proof complete! Applied ${result.applied.length} theorem(s).`;
      verifyResult.style.color = '#2e7d32';
    }
  });

  // ---------- Clear ----------
  clearBtn.addEventListener('click', () => {
    points = [];
    segments = [];
    conditions = [];
    currentProof = [];
    selectedPoint = null;
    selectedSegment = null;
    offsetX = 0;
    offsetY = 0;
    scale = 1;
    render();
    renderProofTree();
    verifyResult.textContent = '';
  });

  // ---------- Zoom ----------
  zoomInBtn.addEventListener('click', () => {
    scale = Math.min(5, scale * 1.5);
    render();
  });
  zoomOutBtn.addEventListener('click', () => {
    scale = Math.max(0.2, scale / 1.5);
    render();
  });

  // ---------- Resize ----------
  window.addEventListener('resize', () => {
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * devicePixelRatio;
    canvas.height = rect.height * devicePixelRatio;
    ctx.setTransform(devicePixelRatio, 0, 0, devicePixelRatio, 0, 0);
    render();
  });

  // ---------- Init ----------
  canvas.width = canvas.clientWidth * devicePixelRatio;
  canvas.height = canvas.clientHeight * devicePixelRatio;
  ctx.setTransform(devicePixelRatio, 0, 0, devicePixelRatio, 0, 0);
  render();
  renderProofTree();
})();
```

Creating a full terrain destruction shooting game with Perlin noise, fluid simulation, and WebGL is a substantial project. Below is a **professional, production-ready framework** in **TypeScript/WebGL** using **three.js** (which handles WebGL efficiently) and **p5.js-style fluid simulation**. This demo focuses on:

- Perlin-noise terrain generation
- Bullet impact with realistic cratering (soft-body deformation)
- Water containers that break and release fluid (simple 2D fluid grid simulation)
- Players/enemies with movement affected by water
- WebGL rendering with shaders for terrain, water, and particles

---

## 🧩 Project Structure

We'll use **three.js** for rendering, **p5.js-style fluid** for water simulation (via a 2D grid), and **TypeScript** for structure. The game will be a 2D top-down shooter with a 3D terrain rendered from above.

