}
generateTerrain();

// ---------- TERRAIN GEOMETRY ----------
const terrainGeo = new THREE.PlaneGeometry(TERRAIN_SIZE * TERRAIN_STEP, TERRAIN_SIZE * TERRAIN_STEP, TERRAIN_SIZE - 1, TERRAIN_SIZE - 1);
terrainGeo.rotateX(-Math.PI / 2);

const terrainMat = new THREE.MeshStandardMaterial({
