<script>
// ---------- State ----------
const state = {
  file: null,
  pages: 0,
  fontSize: 0,
  margins: 0,
  titleBlock: false,
  score: 0,
  plagScore: 0,
  plagOverall: 0,
  plagMatches: [],
  anon: true,
  submitted: false,
};

// ---------- DOM ----------
const $ = (id) => document.getElementById(id);
const dropzone = $('dropzone');
const fileInput = $('fileInput');
const browseLabel = $('browseLabel');
const fileInfo = $('fileInfo');
$('fileName').textContent = 'paper.pdf';
$('fileSize').textContent = '0 KB';
const errorBox = $('errorBox');
const errorText = $('errorText');
const progressBar = $('progressBar');
const stepNum = $('stepNum');

// ---------- Dropzone ----------
['dragenter', 'dragover'].forEach(ev => {
  dropzone.addEventListener(ev, (e) => { e.preventDefault(); dropzone.classList.add('border-indigo-500'); });
});
['dragleave', 'drop'].forEach(ev => {
  dropzone.addEventListener(ev, (e) => { e.preventDefault(); dropzone.classList.remove('border-indigo-500'); });
});
dropzone.addEventListener('drop', (e) => {
  const f = e.dataTransfer.files[0];
  if (f) handleFile(f);
});
dropzone.addEventListener('click', () => fileInput.click());
fileInput.addEventListener('change', (e) => {
  const f = e.target.files[0];
  if (f) handleFile(f);
});

function handleFile(file) {
  if (!file.type.startsWith('application/pdf')) {
    showError('Please upload a PDF file.');
    return;
  }
  if (file.size > 20 * 1024 * 1024) {
    showError('File exceeds 20MB limit.');
    return;
  }
  state.file = file;
  $('fileName').textContent = file.name;
  $('fileSize').textContent = formatBytes(file.size);
  fileInfo.classList.remove('hidden');
  errorBox.classList.add('hidden');
  updateProgress(25);
  navigateStep(2);
  runFormatCheck();
}

function formatBytes(bytes) {
  if (bytes < 1024) return bytes + ' B';
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
  return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
}

function showError(msg) {
  errorText.textContent = msg;
  errorBox.classList.remove('hidden');
}

// ---------- Progress ----------
function updateProgress(pct) {
  progressBar.style.width = pct + '%';
  stepNum.textContent = Math.round(pct / 25) + 1;
}
function navigateStep(n) {
  document.querySelectorAll('section[id^="step"]').forEach(s => s.classList.add('hidden'));
  document.getElementById('step' + n).classList.remove('hidden');
  updateProgress((n - 1) * 25);
}

// ---------- Format Checker (heuristic) ----------
function runFormatCheck() {
  if (!state.file) return;
  const reader = new FileReader();
  reader.onload = async () => {
    const pdf = await PDFJS.getDocument({ data: reader.result }).promise;
    state.pages = pdf.numPages;
    $('pagesVal').textContent = state.pages + ' pages';

    // Simulate font & margin analysis via text extraction
    const text = await extractText(pdf);
    const fontStats = analyzeFont(text);
    const marginStats = analyzeMargins(text);
    const titleStats = analyzeTitle(text);

    state.fontSize = fontStats;
    state.margins = marginStats;
    state.titleBlock = titleStats;

    $('fontVal').textContent = fontStats.toFixed(1) + ' pt';
    $('marginsVal').textContent = marginStats.toFixed(2) + ' in';
    $('titleVal').textContent = titleStats ? '✓ Present' : '✗ Missing';

    // Score
    const base = 100;
    let s = base;
    if (state.pages < 6) s -= 20;
    if (state.pages > 8) s -= 15;
    if (state.fontSize < 10) s -= 10;
    if (state.fontSize > 14) s -= 10;
    if (state.margins < 0.75) s -= 15;
    if (state.margins > 1.1) s -= 15;
    if (!state.titleBlock) s -= 10;

    state.score = Math.max(0, Math.round(s));
    $('formatScore').innerHTML = `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg>${state.score} / 100`;

    // Results
    const results = $('formatResults');
    results.innerHTML = '';
    if (state.score >= 90) {
      results.innerHTML += `<div class="p-3 bg-green-900/20 border border-green-500 rounded text-sm"><span class="font-mono text-green-400">✓</span> Excellent format</div>`;
    } else if (state.score >= 70) {
      results.innerHTML += `<div class="p-3 bg-yellow-900/20 border border-yellow-500 rounded text-sm"><span class="font-mono text-yellow-400">⚠</span> Minor adjustments needed</div>`;
    } else {
      results.innerHTML += `<div class="p-3 bg-red-900/20 border border-red-500 rounded text-sm"><span class="font-mono text-red-400">✗</span> Major issues detected</div>`;
    }
  };
  reader.onerror = () => showError('Failed to read PDF.');
  reader.readAsArrayBuffer(state.file);
}

async function extractText(pdf) {
  let text = '';
  for (let i = 1; i <= pdf.numPages; i++) {
    const page = await pdf.getPage(i);
    const content = await page.getTextContent();
    const ops = await page.getTextContent();
    const spans = ops.items || [];
    spans.forEach(s => text += s.str + ' ');
  }
  return text.trim();
}

function analyzeFont(text) {
  const words = text.split(/\s+/).filter(w => w.length > 1);
  if (words.length === 0) return 12;
  // Heuristic: average word length correlates with font size
  const avg = words.reduce((a, w) => a + w.length, 0) / words.length;
  return Math.round(avg * 0.75 + 10);
}

function analyzeMargins(text) {
  // Heuristic: line length distribution suggests margins
  const lines = text.split('\n');
  const lineLens = lines.map(l => l.trim().length).filter(l => l > 0);
  if (lineLens.length === 0) return 1.0;
  const avg = lineLens.reduce((a, l) => a + l, 0) / lineLens.length;
  // In 8pt text, avg ~ 60 chars per line → 1in margin
  return Math.round(avg / 60 * 100) / 100;
}

function analyzeTitle(text) {
  const lines = text.split('\n');
  const first = lines[0].trim();
  return first.length > 10;
}

// ---------- Plagiarism (simulated) ----------
function runPlagCheck() {
  if (!state.file) return;
  const start = performance.now();
  const interval = setInterval(() => {
    const pct = Math.min(100, Math.round((performance.now() - start) / 120 * 100));
    $('plagBar').style.width = pct + '%';
    $('plagScore').innerHTML = `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg>${pct}%`;
  }, 100);

  setTimeout(() => {
    clearInterval(interval);
    const score = Math.floor(Math.random() * 18);
    state.plagScore = score;
    state.plagOverall = score;
    state.plagMatches = [
      { title: 'Introduction to Deep Learning', source: 'arXiv', pct: 12 },
      { title: 'Neural Networks for Image Recognition', source: 'IEEE', pct: 8 },
      { title: 'A Survey of Generative Models', source: 'Springer', pct: 5 },
    ].slice(0, Math.min(3, score));

    $('plagOverall').textContent = score + '%';
    $('plagMatches').innerHTML = state.plagMatches.map(m =>
      `<div class="flex justify-between text-xs"><span>${m.title}</span><span class="font-mono">${m.pct}%</span></div>`
    ).join('');
    $('plagReport').classList.remove('hidden');
  }, 12000);
}

// ---------- Submit ----------
$('submitBtn').addEventListener('click', () => {
  if (!state.file) {
    showError('Please upload a paper first.');
    return;
  }
  state.submitted = true;
  $('paperName').textContent = state.file.name;
  $('finalScore').textContent = state.score + '%';
  $('finalPlag').textContent = state.plagOverall + '%';
  $('step5').classList.remove('hidden');
  $('step4').classList.add('hidden');
  updateProgress(100);
  $('stepNum').textContent = 5;
  submitToBackend();
});

function submitToBackend() {
  // Simulated backend call
  setTimeout(() => {
    alert('✓ Submission successful! Your paper has been anonymized and submitted for review.');
  }, 1200);
}

// ---------- Anonymize (demo) ----------
$('anonToggle').addEventListener('change', (e) => {
  state.anon = e.target.checked;
  $('anonToggle').nextElementSibling.textContent = state.anon ? 'Enabled' : 'Disabled';
});

// ---------- Init ----------
navigateStep(1);
</script>

</body>
</html>
```

