    const captureBtn = document.getElementById('captureBtn');
    const statusEl = document.getElementById('status');
    const canvas = document.getElementById('screenshot');
    const img = document.getElementById('screenshotImg');

    captureBtn.addEventListener('click', async () => {
      const url = urlInput.value.trim();
      if (!url) {
        setStatus('error', 'Please enter a URL first.');
        return;
      }

      // Disable button while capturing
      captureBtn.disabled = true;
      setStatus('info', 'Capturing screenshot…');

      try {
        const { width, height } = getViewport();
        const options = {
          backgroundColor: '#ffffff',
          scale: 2,
          useCORS: true,
          windowWidth: width,
          windowHeight: height,
          scrollX: 0,
          scrollY: 0,
          logging: false
        };

        const result = await html2canvas(document.body, options);
        const dataUrl = result.toDataURL('image/png');

        // Display
        img.src = dataUrl;
        img.style.display = 'block';
        canvas.style.display = 'none';

        // Download
        const link = document.createElement('a');
        link.download = `${new Date().toISOString().replace(/[:.]/g, '-')}_screenshot.png`;
        link.href = dataUrl;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);

        setStatus('success', `Screenshot saved. ${result.width} × ${result.height} pixels.`);
      } catch (err) {
        console.error(err);
        setStatus('error', `Capture failed: ${err.message}`);
      } finally {
        captureBtn.disabled = false;
      }
    });

    function getViewport() {
      const dpr = window.devicePixelRatio || 1;
      const w = window.innerWidth * dpr;
      const h = window.innerHeight * dpr;
      return { width: w, height: h };
    }

    function setStatus(type, message) {
      statusEl.className = 'status ' + type;
      statusEl.textContent = message;
    }

    // Auto-enable button if URL is present
    urlInput.addEventListener('input', () => {
      captureBtn.disabled = urlInput.value.trim().length === 0;
    });
  </script>
