### 2. Backend (`server.js`)

```javascript
const express = require('express');
const mongoose = require('mongoose');
const cors = require('cors');
const helmet = require('helmet');
const morgan = require('morgan');
const path = require('path');
const fs = require('fs');
const { v4: uuidv4 } = require('uuid');

const app = express();
const PORT = process.env.PORT || 3001;

app.use(helmet());
app.use(morgan('combined'));
app.use(cors());
app.use(express.json({ limit: '50mb' }));
app.use(express.urlencoded({ extended: true }));

// Mock data
const users = [
  { id: 'u1', name: 'Admin User', email: 'admin@example.com', role: 'admin' },
  { id: 'u2', name: 'Editor', email: 'editor@example.com', role: 'editor' },
];

const projects = [
  { id: 'p1', name: 'Auth Service', slug: 'auth-service', owner: 'u1' },
  { id: 'p2', name: 'Payment Gateway', slug: 'payment-gateway', owner: 'u1' },
];

const documents = [
  {
    id: 'd1',
    title: 'User Authentication API',
    slug: 'user-authentication-api',
    type: 'api',
    content: '# User Authentication\n\n## Endpoints\n\n| Method | Endpoint | Description |\n|--------|----------|-------------|\n| POST   | `/login` | Authenticate user |\n| GET    | `/me`    | Get current user |\n',
    tags: ['auth', 'security'],
    status: 'published',
    versions: [
      { version: 'v1.0', content: '# User Authentication\n\n## Endpoints\n\n| Method | Endpoint | Description |\n|--------|----------|-------------|\n| POST   | `/login` | Authenticate user |\n| GET    | `/me`    | Get current user |\n', author: 'u1' },
    ],
    createdAt: Date.now(),
  },
];

// In-memory storage (replace with MongoDB)
const db = {
  users,
  projects,
  documents,
};

// Auth middleware
function requireAuth(req, res, next) {
  const token = req.headers.authorization?.replace('Bearer ', '');
  if (!token) return res.status(401).json({ error: 'Unauthorized' });
  req.user = users.find(u => u.id === token);
  if (!req.user) return res.status(401).json({ error: 'Invalid token' });
  next();
}

// Routes

// --- Auth ---
app.post('/api/auth/login', (req, res) => {
  const { email } = req.body;
  const user = users.find(u => u.email === email);
  if (!user) return res.status(400).json({ error: 'User not found' });
  res.json({ token: user.id, user });
});

// --- Projects ---
app.get('/api/projects', requireAuth, (req, res) => {
  const user = req.user;
  const projects = db.projects.filter(p => user.role === 'admin' || user.id === p.owner);
  res.json(projects);
});

app.post('/api/projects', requireAuth, (req, res) => {
  const p = { id: 'p' + Date.now(), ...req.body, owner: req.user.id, members: [{ role: 'owner', user: req.user.id }] };
  db.projects.push(p);
  res.status(201).json(p);
});

// --- Documents ---
app.get('/api/documents', requireAuth, (req, res) => {
  const { q, type, project } = req.query;
  let docs = db.documents.filter(d => {
    if (req.user.role !== 'admin' && req.user.id !== d._owner) return false;
    if (project) return d.project === project;
    return true;
  });
  if (q) docs = docs.filter(d => d.title.toLowerCase().includes(q.toLowerCase()));
  if (type) docs = docs.filter(d => d.type === type);
  res.json(docs);
});

app.post('/api/documents', requireAuth, (req, res) => {
  const doc = {
    id: 'd' + Date.now(),
    title: req.body.title,
    slug: req.body.slug || slugify(req.body.title),
    type: req.body.type || 'doc',
    content: req.body.content || '# New Document',
    tags: req.body.tags || [],
    status: 'draft',
    versions: [{ version: 'v1.0', content: req.body.content || '# New Document', author: req.user.id }],
    createdAt: Date.now(),
  };
  db.documents.push(doc);
  res.status(201).json(doc);
});

app.put('/api/documents/:id', requireAuth, (req, res) => {
  const doc = db.documents.find(d => d.id === req.params.id);
  if (!doc) return res.status(404).json({ error: 'Document not found' });
  const user = req.user;
  if (user.role !== 'admin' && user.id !== doc._owner) return res.status(403).json({ error: 'Forbidden' });
  doc.content = req.body.content;
  doc.title = req.body.title;
  doc.slug = req.body.slug || slugify(req.body.title);
  doc.tags = req.body.tags || [];
  doc.status = req.body.status || 'draft';
  doc.updatedAt = Date.now();
  const version = {
    version: 'v' + (doc.versions.length + 1) + '.0',
    content: req.body.content,
    author: user.id,
    createdAt: Date.now(),
    changes: ['Updated content'],
  };
  doc.versions.push(version);
  res.json(doc);
});

app.delete('/api/documents/:id', requireAuth, (req, res) => {
  const doc = db.documents.find(d => d.id === req.params.id);
  if (!doc) return res.status(404).json({ error: 'Document not found' });
  if (req.user.role !== 'admin' && req.user.id !== doc._owner) return res.status(403).json({ error: 'Forbidden' });
  db.documents = db.documents.filter(d => d.id !== req.params.id);
  res.json({ success: true });
});

// --- Versions ---
app.get('/api/documents/:id/versions', requireAuth, (req, res) => {
  const doc = db.documents.find(d => d.id === req.params.id);
  if (!doc) return res.status(404).json({ error: 'Document not found' });
  res.json(doc.versions);
});

app.get('/api/documents/:id/versions/:version', requireAuth, (req, res) => {
  const doc = db.documents.find(d => d.id === req.params.id);
  if (!doc) return res.status(404).json({ error: 'Document not found' });
  const v = doc.versions.find(v => v.version === req.params.version);
  if (!v) return res.status(404).json({ error: 'Version not found' });
  res.json(v);
});

app.post('/api/documents/:id/versions/:version', requireAuth, (req, res) => {
  const doc = db.documents.find(d => d.id === req.params.id);
  if (!doc) return res.status(404).json({ error: 'Document not found' });
  const v = doc.versions.find(v => v.version === req.params.version);
  if (!v) return res.status(404).json({ error: 'Version not found' });
  const changes = req.body.changes || [];
  v.changes = [...v.changes, ...changes];
  res.json(v);
});

// --- API Spec Upload ---
app.post('/api/api-specs', requireAuth, (req, res) => {
  const spec = req.body.spec;
  const doc = db.documents.find(d => d.id === req.body.documentId);
  if (!doc) return res.status(404).json({ error: 'Document not found' });
  const parsed = parseOpenAPI(spec);
  const version = {
    version: 'v' + (doc.versions.length + 1) + '.0',
    content: generateMarkdownFromSpec(parsed),
    author: req.user.id,
    createdAt: Date.now(),
    changes: ['Generated from OpenAPI spec'],
  };
  doc.versions.push(version);
  res.json({ version: version.version, spec: parsed });
});

function parseOpenAPI(spec) {
  // Simplistic parser
  const endpoints = [];
  spec.paths.forEach((path, p) => {
    Object.entries(path).forEach(([method, ops]) => {
      Object.entries(ops).forEach(([opName, op]) => {
        endpoints.push({
          method,
          path: p,
          operation: opName,
          summary: op.summary || '',
          description: op.description || '',
          parameters: op.parameters || [],
          responses: op.responses || {},
        });
      });
    });
  });
  return { spec, endpoints };
}

function generateMarkdownFromSpec({ endpoints }) {
  let md = '# API Documentation\n\n';
  md += `| Method | Path | Operation | Summary |\n|--------|------|-----------|---------|\n`;
  endpoints.forEach(e => {
    md += `| ${e.method} | ${e.path} | ${e.operation} | ${e.summary} |\n`;
  });
  return md;
}

// --- Helpers ---
function slugify(str) {
  return str.toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9-]/g, '');
}

// --- Serve static files (Monaco, docs) ---
app.use('/editor', express.static(path.join(__dirname, 'editor')));
app.use('/docs', express.static(path.join(__dirname, 'docs')));

// --- Health ---
app.get('/health', (req, res) => res.json({ status: 'ok' }));

app.listen(PORT, () => {
  console.log(`DMS server running on http://localhost:${PORT}`);
});
```

