## 🖥️ Frontend (React + Monaco)

### `src/App.js`

```javascript
import React, { useState, useEffect } from 'react';
import MonacoEditor from 'react-monaco-editor';
import marked from 'marked';

function App() {
  const [docs, setDocs] = useState([]);
  const [currentDoc, setCurrentDoc] = useState(null);
  const [version, setVersion] = useState(null);
  const [versions, setVersions] = useState([]);

  useEffect(() => {
    fetchDocs();
  }, []);

  const fetchDocs = () => {
    // Simulated API call
    setTimeout(() => {
      setDocs([
        { id: 'd1', title: 'User Authentication API', content: '# User Authentication\n\n## Endpoints\n\n| Method | Endpoint | Description |\n|--------|----------|-------------|\n| POST   | `/login` | Authenticate user |\n| GET    | `/me`    | Get current user |\n' },
      ]);
      setCurrentDoc(docs[0]);
    }, 500);
  };

  const handleEditorChange = (value) => {
    if (!currentDoc) return;
    const doc = docs.find(d => d.id === currentDoc.id);
    if (!doc) return;
    doc.content = value;
    setDocs([...docs]);
    // Auto-save version
    const newVersion = {
      version: 'v' + (doc.versions.length + 1) + '.0',
      content: value,
      author: 'u1',
      createdAt: Date.now(),
      changes: ['Updated content'],
    };
    doc.versions.push(newVersion);
    setVersions([...doc.versions]);
  };

  const handleVersionSelect = (v) => {
    setVersion(v);
  };

  const renderVersion = () => {
    if (!version) return <div>No version selected</div>;
    return (
      <div className="version-preview">
        <h3>Version {version.version}</h3>
        <div dangerouslySetInnerHTML={{ __html: marked(version.content) }} />
      </div>
    );
  };

  const renderVersionsList = () => {
    return (
      <div className="versions-list">
        <h3>Versions</h3>
        <ul>
          {versions.map((v, i) => (
            <li key={i}>
              <button onClick={() => handleVersionSelect(v)}>{v.version}</button>
            </li>
          ))}
        </ul>
      </div>
    );
  };

  return (
    <div className="app">
      <header className="app-header">
        <h1>Documentation Management System</h1>
        <p>Manage API, specs, and system design docs</p>
      </header>
      <div className="workspace">
        <div className="editor-panel">
          <div className="editor-toolbar">
            <label>Document</label>
            <select value={currentDoc?.id || ''} onChange={(e) => {
              const doc = docs.find(d => d.id === e.target.value);
              setCurrentDoc(doc);
              setVersion(null);
            }}>
              {docs.map(d => <option key={d.id} value={d.id}>{d.title}</option>)}
            </select>
          </div>
          <div className="editor-wrapper">
            <MonacoEditor
              width="100%"
              height="600px"
              language="markdown"
              theme="vs-dark"
              value={currentDoc?.content || '# New Document'}
              options={{
                automaticLayout: true,
                minimap: { enabled: false },
                lineNumbers: 'off',
              }}
              onChange={handleEditorChange}
            />
          </div>
        </div>
        <div className="preview-panel">
          {currentDoc ? (
            <>
              <div className="preview-toolbar">
                <h2>{currentDoc.title}</h2>
                <span className="doc-type">{currentDoc.type}</span>
              </div>
              <div className="preview-body" dangerouslySetInnerHTML={{ __html: marked(currentDoc.content) }} />
            </>
          ) : (
            <div className="empty-state">Select a document to edit</div>
          )}
        </div>
      </div>
      <aside className="sidebar">
        <div className="sidebar-section">
          <h3>Versions</h3>
          {renderVersionsList()}
        </div>
        <div className="sidebar-section">
          <h3>Preview</h3>
          {renderVersion()}
        </div>
      </aside>
    </div>
  );
}

export default App;
```

