/* =========================================================
   Video Timeline Bookmark Tool
   ========================================================= */
(function () {
  'use strict';

  // ---------- State ----------
  const state = {
    bookmarks: [],
    currentId: null,
    videoEl: null,
    videoBgEl: null,
    videoPlayEl: null,
    videoSeekEl: null,
    videoTimeCurrentEl: null,
    videoTimeTotalEl: null,
    videoProgressFillEl: null,
    videoProgressEl: null,
    thumbInputEl: null,
    editorBodyEl: null,
    bookmarksListEl: null,
    badgeCountEl: null,
    videoBgImg: null,
    videoBgLoaded: false,
  };

  // ---------- DOM ----------
  function $id(id) { return document.getElementById(id); }

  function initDOM() {
    state.videoEl = $id('videoBg');
    state.videoPlayEl = $id('videoPlay');
    state.videoSeekEl = $id('videoSeek');
    state.videoTimeCurrentEl = $id('videoTimeCurrent');
    state.videoTimeTotalEl = $id('videoTimeTotal');
    state.videoProgressFillEl = $id('videoProgressFill');
    state.videoProgressEl = $id('videoProgress');
    state.thumbInputEl = $id('thumbInput');
    state.editorBodyEl = $id('editorBody');
    state.bookmarksListEl = $id('bookmarksList');
    state.badgeCountEl = $id('badgeCount');
    state.videoBgImg = state.videoEl.style.backgroundImage;
    state.videoBgLoaded = false;
  }

  // ---------- Storage ----------
  const STORAGE_KEY = 'tlb.bookmarks.v1';

  function loadBookmarks() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return [];
      const parsed = JSON.parse(raw);
      if (!Array.isArray(parsed)) return [];
      return parsed;
    } catch (e) {
      return [];
    }
  }

  function saveBookmarks() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state.bookmarks));
    } catch (e) { /* ignore */ }
  }

  // ---------- Helpers ----------
  function formatTime(sec) {
    if (!isFinite(sec) || sec < 0) sec = 0;
    const m = Math.floor(sec / 60);
    const s = Math.floor(sec % 60);
    return `${m}:${s.toString().padStart(2, '0')}`;
  }

  function uid() {
    return 'b_' + Math.random().toString(36).slice(2, 10) + Date.now().toString(36).slice(-4);
  }

  function findBookmark(id) {
    return state.bookmarks.find(b => b.id === id);
  }

  // ---------- Video control ----------
  function playVideo() {
    if (state.videoEl) state.videoEl.play();
  }
  function pauseVideo() {
    if (state.videoEl) state.videoEl.pause();
  }
  function togglePlay() {
    if (state.videoEl) {
      if (state.videoEl.paused) playVideo(); else pauseVideo();
    }
  }

  function updateVideoUI() {
    if (!state.videoEl) return;
    const t = state.videoEl.currentTime;
    const d = state.videoEl.duration || 0;
    const pct = d > 0 ? (t / d) * 100 : 0;
    state.videoTimeCurrentEl.textContent = formatTime(t);
    state.videoTimeTotalEl.textContent = formatTime(d);
    state.videoSeekEl.value = pct;
    state.videoProgressFillEl.style.width = pct + '%';
    state.videoProgressEl.style.width = pct + '%';
  }

  function seekFromEvent(e) {
    if (!state.videoEl) return;
    const rect = state.videoEl.getBoundingClientRect();
    const clientX = e.touches ? e.touches[0].clientX : e.clientX;
    const pct = (clientX - rect.left) / rect.width;
    const duration = state.videoEl.duration || 0;
    const t = Math.max(0, Math.min(duration, pct * duration));
    state.videoEl.currentTime = t;
  }

  function onVideoSeek(e) {
    if (!state.videoEl) return;
    const pct = e.target.value / 100;
    const duration = state.videoEl.duration || 0;
    state.videoEl.currentTime = pct * duration;
  }

  function onVideoTimeupdate() {
    if (!state.videoEl) return;
    updateVideoUI();
  }

  function onVideoSeekend() {
    if (!state.videoEl) return;
    updateVideoUI();
  }

  // ---------- Render ----------
  function renderBookmarks() {
    const list = state.bookmarksListEl;
    const items = state.bookmarks;

    if (items.length === 0) {
      list.innerHTML = `
        <div class="empty-state">
          <svg viewBox="0 0 24 24" width="40" height="40" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">
            <circle cx="12" cy="12" r="10"></circle>
            <line x1="12" y1="8" x2="12" y2="12"></line>
            <line x1="12" y1="16" x2="12.01" y2="16"></line>
          </svg>
          <p>No bookmarks yet. Click the timeline or press <kbd>Add Bookmark</kbd> to get started.</p>
        </div>`;
      state.badgeCountEl.textContent = '0';
      state.badgeCountEl.style.background = '';
      return;
    }

    const frag = document.createDocumentFragment();
    items.forEach(b => {
      const el = document.createElement('div');
      el.className = 'bookmark' + (b.id === state.currentId ? ' active' : '');
      el.dataset.id = b.id;
      el.innerHTML = `
        <div class="thumb">
          ${b.thumbnail ? `<img src="${b.thumbnail}" alt="" loading="lazy" />` : ''}
        </div>
        <div class="meta">
          <div class="title">${escapeHtml(b.title)}</div>
          <div class="time">${formatTime(b.time)}</div>
        </div>
        <div class="actions">
          <button class="icon edit" title="Edit" aria-label="Edit" data-action="edit">
            <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path></svg>
          </button>
          <button class="icon del" title="Delete" aria-label="Delete" data-action="delete">
            <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"></polyline><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"></path><path d="M10 11v6"></path><path d="M14 11v6"></path><path d="M9 6V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2"></path></svg>
          </button>
        </div>`;
      el.addEventListener('click', e => {
        const btn = e.target.closest('[data-action]');
        if (btn) {
          const action = btn.dataset.action;
          if (action === 'edit') openEditor(b.id);
          else if (action === 'delete') deleteBookmark(b.id);
          return;
        }
        openEditor(b.id);
      });
      frag.appendChild(el);
    });
    list.innerHTML = '';
    list.appendChild(frag);
    state.badgeCountEl.textContent = items.length;
    state.badgeCountEl.style.background = items.length > 0 ? 'var(--primary-soft)' : '';
  }

  function renderEditor() {
    const card = state.editorBodyEl;
    const b = findBookmark(state.currentId);
    if (!b) {
      card.innerHTML = `
        <div class="editor-empty">
          <p>Select a bookmark to edit its note or thumbnail.</p>
        </div>`;
      return;
    }
    card.innerHTML = `
      <div class="editor-card">
        <div class="card-head">
          <h3>Edit Bookmark</h3>
          <div class="time">${formatTime(b.time)}</div>
        </div>
        <textarea id="editorNote" placeholder="Write a note about this bookmark...">${escapeHtml(b.note || '')}</textarea>
        <div class="thumb-preview">
          <label>Thumbnail</label>
          <div class="thumb">
            ${b.thumbnail ? `<img src="${b.thumbnail}" alt="" />` : ''}
          </div>
          <input type="file" id="editorThumb" accept="image/*" />
        </div>
        <div class="editor-card-actions">
          <button id="saveBtn" class="btn btn-primary" type="button">Save</button>
          <button id="cancelBtn" class="btn btn-ghost" type="button">Cancel</button>
        </div>
      </div>`;
    const note = card.querySelector('#editorNote');
    const thumb = card.querySelector('#editorThumb');
    const save = card.querySelector('#saveBtn');
    const cancel = card.querySelector('#cancelBtn');
    note.value = b.note || '';
    thumb.value = '';
    save.addEventListener('click', () => saveBookmark(b.id));
    cancel.addEventListener('click', () => {
      state.currentId = null;
      renderEditor();
    });
    thumb.addEventListener('change', e => {
      const file = e.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = ev => {
        b.thumbnail = ev.target.result;
        renderBookmarks();
      };
      reader.readAsDataURL(file);
    });
  }

  function escapeHtml(s) {
    return String(s ?? '').replace(/[&<>"']/g, c => ({
      '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    }[c]));
  }

  // ---------- Actions ----------
  function addBookmark() {
    const time = state.videoEl.currentTime;
    const b = {
      id: uid(),
      title: `Bookmark ${state.bookmarks.length + 1}`,
      time,
      note: '',
      thumbnail: '',
    };
    state.bookmarks.push(b);
    saveBookmarks();
    renderBookmarks();
    renderEditor();
    state.currentId = b.id;
    openEditor(b.id);
  }

  function deleteBookmark(id) {
    const idx = state.bookmarks.findIndex(b => b.id === id);
    if (idx < 0) return;
    state.bookmarks.splice(idx, 1);
    saveBookmarks();
    renderBookmarks();
    if (state.currentId === id) {
      state.currentId = null;
      renderEditor();
    }
  }

  function openEditor(id) {
    state.currentId = id;
    renderEditor();
  }

  function saveBookmark(id) {
    const b = findBookmark(id);
    if (!b) return;
    b.title = (state.editorBodyEl.querySelector('#editorNote')?.value || '').trim();
    b.note = state.editorBodyEl.querySelector('#editorNote')?.value || '';
    saveBookmarks();
    renderBookmarks();
    renderEditor();
  }

  // ---------- Events ----------
  function bindEvents() {
    $id('addBtn').addEventListener('click', addBookmark);
    $id('exportBtn').addEventListener('click', exportProject);
    $id('importBtn').addEventListener('click', () => {
      const input = document.createElement('input');
      input.type = 'file';
      input.accept = '.json';
      input.onchange = e => {
        const file = e.target.files[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = ev => {
          try {
            const data = JSON.parse(ev.target.result);
            if (!Array.isArray(data) || !data.every(isBookmark)) {
              alert('Invalid import file. Expected an array of bookmark objects.');
              return;
            }
            state.bookmarks = data;
            saveBookmarks();
            renderBookmarks();
            renderEditor();
          } catch (err) {
            alert('Failed to parse import file.');
          }
        };
        reader.readAsText(file);
      };
      input.click();
    });

    // Video events
    state.videoEl.addEventListener('play', () => { state.videoPlayEl.style.background = 'rgba(255,255,255,.35)'; });
    state.videoEl.addEventListener('pause', () => { state.videoPlayEl.style.background = 'rgba(255,255,255,.18)'; });
    state.videoEl.addEventListener('timeupdate', onVideoTimeupdate);
    state.videoEl.addEventListener('seeked', onVideoSeekend);
    state.videoEl.addEventListener('ended', () => {
      if (state.bookmarks.length) {
        state.videoEl.currentTime = state.bookmarks[0].time;
        state.videoEl.play();
      }
    });

    // Seek
    state.videoSeekEl.addEventListener('input', onVideoSeek);
    state.videoSeekEl.addEventListener('change', onVideoSeek);
    state.videoSeekEl.addEventListener('click', seekFromEvent);
    state.videoSeekEl.addEventListener('mousedown', e => { e.preventDefault(); });
    state.videoSeekEl.addEventListener('touchstart', e => { e.preventDefault(); });

    // Timeline click
    state.videoEl.addEventListener('click', e => {
      const rect = state.videoEl.getBoundingClientRect();
      const x = (e.clientX - rect.left) / rect.width;
      const duration = state.videoEl.duration || 0;
      const t = Math.max(0, Math.min(duration, x * duration));
      state.videoEl.currentTime = t;
    });

    // Keyboard
    document.addEventListener('keydown', e => {
      if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;
      if (e.key === 'Enter') {
        e.preventDefault();
        togglePlay();
      } else if (e.key === ' ') {
        e.preventDefault();
        togglePlay();
      } else if (e.key === 'Escape') {
        state.currentId = null;
        renderEditor();
      } else if (e.key === 'Delete' || e.key === 'Backspace') {
        if (state.currentId) {
          deleteBookmark(state.currentId);
        }
      }
    });
  }

  function isBookmark(obj) {
    return obj && typeof obj === 'object' &&
      'id' in obj && typeof obj.id === 'string' &&
      'title' in obj && typeof obj.title === 'string' &&
      'time' in obj && typeof obj.time === 'number' &&
      'note' in obj && typeof obj.note === 'string' &&
      'thumbnail' in obj && typeof obj.thumbnail === 'string';
  }

  // ---------- Export ----------
  function exportProject() {
    const data = state.bookmarks.map(b => ({
      id: b.id,
      title: b.title,
      time: b.time,
      note: b.note,
      thumbnail: b.thumbnail,
      createdAt: b.createdAt || Date.now(),
    }));
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `bookmarks-${Date.now()}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  }

  // ---------- Init ----------
  function init() {
    initDOM();
    state.bookmarks = loadBookmarks();
    state.bookmarks.forEach(b => {
      b.createdAt = b.createdAt || Date.now();
    });
    renderBookmarks();
    renderEditor();
    bindEvents();
    if (state.videoEl) {
      state.videoEl.addEventListener('loadedmetadata', () => {
        state.videoBgLoaded = true;
      });
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
```

