const express = require('express');
const cors = require('cors');
const helmet = require('helmet');
const morgan = require('morgan');
const sqlite3 = require('sqlite3').verbose();
const bcrypt = require('bcrypt');
const { v4: uuidv4 } = require('uuid');

const app = express();
const PORT = process.env.PORT || 3001;

// Helmet + CORS
app.use(helmet());
app.use(cors({
  origin: 'http://localhost:5173',
  credentials: true
}));
app.use(morgan('combined'));
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ extended: true }));

// Database
const db = new sqlite3.Database('drone.db', (err) => {
  if (err) console.error(err);
  else initDB();
});

function initDB() {
  db.exec(`
    CREATE TABLE IF NOT EXISTS drones (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL UNIQUE,
      serial TEXT NOT NULL UNIQUE,
      status TEXT NOT NULL DEFAULT 'idle',
      battery INTEGER NOT NULL DEFAULT 100,
      latitude REAL,
      longitude REAL,
      altitude REAL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT NOT NULL UNIQUE,
      password TEXT NOT NULL,
      role TEXT NOT NULL DEFAULT 'employee',
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
    CREATE TABLE IF NOT EXISTS sessions (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      sid TEXT NOT NULL,
      uid INTEGER NOT NULL,
      expires_at DATETIME NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
  `);
}

// Seed admin
db.get('SELECT COUNT(*) FROM users WHERE username = ?', ['uavadmin'], (err, row) => {
  if (err) throw err;
  if (row.count === 0) {
    const salt = bcrypt.genSaltSync(10);
    const hash = bcrypt.hashSync('321321', salt);
    db.run('INSERT INTO users (username, password, role) VALUES (?, ?, ?)', ['uavadmin', hash, 'admin']);
  }
});

// Auth helpers
const hashPassword = (pw) => bcrypt.hashSync(pw, 10);
const comparePassword = (pw, hash) => bcrypt.compareSync(pw, hash);

function authenticateUser(username, password) {
  return new Promise((resolve, reject) => {
    db.get('SELECT * FROM users WHERE username = ?', [username], (err, user) => {
      if (err) return reject(err);
      if (!user) return resolve(null);
      if (comparePassword(password, user.password)) resolve(user);
      else resolve(null);
    });
  });
}

function createSession(user) {
  return new Promise((resolve, reject) => {
    const sid = uuidv4();
    const expiresAt = new Date(Date.now() + 3600000); // 1 hour
    db.run('INSERT INTO sessions (sid, uid, expires_at) VALUES (?, ?, ?)', [sid, user.id, expiresAt], (err) => {
      if (err) return reject(err);
      resolve({ sid, user });
    });
  });
}

function getSession(sid) {
  return new Promise((resolve, reject) => {
    db.get('SELECT s.sid, u.username, u.role, s.expires_at FROM sessions s JOIN users u ON s.uid = u.id WHERE s.sid = ? AND s.expires_at > CURRENT_TIMESTAMP', [sid], (err, row) => {
      if (err) return reject(err);
      if (!row) return resolve(null);
      resolve({ sid: row.sid, user: { username: row.username, role: row.role }, expiresAt: row.expires_at });
    });
  });
}

function destroySession(sid) {
  return new Promise((resolve, reject) => {
    db.run('DELETE FROM sessions WHERE sid = ?', [sid], (err) => {
      if (err) return reject(err);
      resolve();
    });
  });
}

// Middleware
const requireAuth = async (req, res, next) => {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  const token = authHeader.split(' ')[1];
  const session = await getSession(token);
  if (!session) return res.status(401).json({ error: 'Session expired or invalid' });
  req.session = session;
  next();
};

// Routes
app.post('/api/auth/login', async (req, res) => {
  const { username, password } = req.body;
  const user = await authenticateUser(username, password);
  if (!user) return res.status(401).json({ error: 'Invalid credentials' });
  const session = await createSession(user);
  res.json({ user: { username: user.username, role: user.role }, session: { sid: session.sid } });
});

app.post('/api/auth/logout', requireAuth, async (req, res) => {
  const { sid } = req.session;
  await destroySession(sid);
  res.json({ message: 'Logged out' });
});

app.post('/api/drones', requireAuth, async (req, res) => {
  if (req.session.user.role !== 'admin') return res.status(403).json({ error: 'Admin only' });
  const { name, serial, status = 'idle', battery = 100, latitude, longitude, altitude } = req.body;
  const stmt = db.prepare('INSERT INTO drones (name, serial, status, battery, latitude, longitude, altitude) VALUES (?, ?, ?, ?, ?, ?, ?)');
  try {
    const result = stmt.run(name, serial, status, battery, latitude, longitude, altitude);
    stmt.finalize();
    res.json({ id: result.lastID, ...req.body });
  } catch (err) {
    stmt.finalize();
    if (err.message.includes('UNIQUE constraint failed')) {
      res.status(409).json({ error: 'Drone with this name or serial already exists' });
    } else {
      res.status(500).json({ error: err.message });
    }
  }
});

app.get('/api/drones', requireAuth, async (req, res) => {
  const stmt = db.prepare('SELECT * FROM drones ORDER BY created_at DESC');
  const rows = await new Promise((resolve, reject) => {
    stmt.all((err, rows) => {
      stmt.finalize();
      if (err) return reject(err);
      resolve(rows);
    });
  });
  res.json(rows);
});

app.get('/api/drones/:id', requireAuth, async (req, res) => {
  const { id } = req.params;
  const stmt = db.prepare('SELECT * FROM drones WHERE id = ?');
  const row = await new Promise((resolve, reject) => {
    stmt.get(id, (err, row) => {
      stmt.finalize();
      if (err) return reject(err);
      resolve(row);
    });
  });
  if (!row) return res.status(404).json({ error: 'Drone not found' });
  res.json(row);
});

app.put('/api/drones/:id', requireAuth, async (req, res) => {
  if (req.session.user.role !== 'admin') return res.status(403).json({ error: 'Admin only' });
  const { id } = req.params;
  const { status, battery, latitude, longitude, altitude } = req.body;
  const stmt = db.prepare('UPDATE drones SET status = ?, battery = ?, latitude = ?, longitude = ?, altitude = ? WHERE id = ?');
  const result = await new Promise((resolve, reject) => {
    stmt.run(status, battery, latitude, longitude, altitude, id, (err) => {
      stmt.finalize();
      if (err) return reject(err);
      resolve();
    });
  });
  if (result.changes === 0) return res.status(404).json({ error: 'Drone not found' });
  res.json({ message: 'Drone updated' });
});

app.delete('/api/drones/:id', requireAuth, async (req, res) => {
  if (req.session.user.role !== 'admin') return res.status(403).json({ error: 'Admin only' });
  const { id } = req.params;
  const stmt = db.prepare('DELETE FROM drones WHERE id = ?');
  const result = await new Promise((resolve, reject) => {
    stmt.run(id, (err) => {
      stmt.finalize();
      if (err) return reject(err);
      resolve();
    });
  });
  if (result.changes === 0) return res.status(404).json({ error: 'Drone not found' });
  res.json({ message: 'Drone deleted' });
});

app.get('/api/me', requireAuth, (req, res) => {
  res.json({ user: req.session.user });
});

// Simulated flight control endpoints (accessible to everyone)
app.post('/api/drones/:id/takeoff', async (req, res) => {
  const { id } = req.params;
  const stmt = db.prepare('UPDATE drones SET status = "in-flight", battery = battery - 5, altitude = 50, latitude = latitude + 0.0001, longitude = longitude + 0.0001 WHERE id = ?');
  const result = await new Promise((resolve, reject) => {
    stmt.run(id, (err) => {
      stmt.finalize();
      if (err) return reject(err);
      resolve();
    });
  });
  if (result.changes === 0) return res.status(404).json({ error: 'Drone not found' });
  res.json({ message: 'Drone takeoff simulated' });
});

app.post('/api/drones/:id/land', async (req, res) => {
  const { id } = req.params;
  const stmt = db.prepare('UPDATE drones SET status = "landing", battery = battery - 10, altitude = 0, latitude = latitude - 0.0001, longitude = longitude - 0.0001 WHERE id = ?');
  const result = await new Promise((resolve, reject) => {
    stmt.run(id, (err) => {
      stmt.finalize();
      if (err) return reject(err);
      resolve();
    });
  });
  if (result.changes === 0) return res.status(404).json({ error: 'Drone not found' });
  res.json({ message: 'Drone landing simulated' });
});

app.post('/api/drones/:id/malfunction', async (req, res) => {
  const { id } = req.params;
  const stmt = db.prepare('UPDATE drones SET status = "malfunction", battery = battery - 20, altitude = 0 WHERE id = ?');
  const result = await new Promise((resolve, reject) => {
    stmt.run(id, (err) => {
      stmt.finalize();
      if (err) return reject(err);
      resolve();
    });
  });
  if (result.changes === 0) return res.status(404).json({ error: 'Drone not found' });
  res.json({ message: 'Drone malfunction simulated' });
});

app.post('/api/drones/:id/repair', async (req, res) => {
  const { id } = req.params;
  const stmt = db.prepare('UPDATE drones SET status = "idle", battery = 100 WHERE id = ?');
  const result = await new Promise((resolve, reject) => {
    stmt.run(id, (err) => {
      stmt.finalize();
      if (err) return reject(err);
      resolve();
    });
  });
  if (result.changes === 0) return res.status(404).json({ error: 'Drone not found' });
  res.json({ message: 'Drone repaired' });
});

// Health check
app.get('/health', (req, res) => res.status(200).json({ status: 'ok' }));

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
