<script>
import axios from 'axios';

export default {
  name: 'Admin',
  data() {
    return {
      drones: [],
      newDrone: {
        name: '',
        serial: '',
        status: 'idle',
        battery: 100,
        latitude: 0,
        longitude: 0,
        altitude: 0,
      },
      editingId: null,
    };
  },
  async mounted() {
    await this.fetchDrones();
  },
  methods: {
    async fetchDrones() {
      try {
        const res = await axios.get('http://localhost:3001/api/drones');
        this.drones = res.data;
      } catch (err) {
        console.error(err);
      }
    },
    async addDrone() {
      try {
        await axios.post('http://localhost:3001/api/drones', this.newDrone);
        this.$toast.success('Drone added');
        this.newDrone = { name: '', serial: '', status: 'idle', battery: 100, latitude: 0, longitude: 0, altitude: 0 };
        await this.fetchDrones();
      } catch (err) {
        this.$toast.error(err.response?.data?.error || 'Failed to add drone');
      }
    },
    async editDrone(id) {
      const drone = this.drones.find((d) => d.id === id);
      if (!drone) return;
      this.editingId = id;
      this.newDrone = { ...drone };
    },
    async saveEdit() {
      try {
        await axios.put(`http://localhost:3001/api/drones/${this.editingId}`, this.newDrone);
        this.$toast.success('Drone updated');
        this.editingId = null;
        await this.fetchDrones();
      } catch (err) {
        this.$toast.error(err.response?.data?.error || 'Failed to update drone');
      }
    },
    async deleteDrone(id) {
      try {
        await axios.delete(`http://localhost:3001/api/drones/${id}`);
        this.$toast.success('Drone deleted');
        await this.fetchDrones();
      } catch (err) {
        this.$toast.error(err.response?.data?.error || 'Failed to delete drone');
      }
    },
    async repairDrone(id) {
      try {
        await axios.post(`http://localhost:3001/api/drones/${id}/repair`);
        this.$toast.success('Drone repaired');
        await this.fetchDrones();
      } catch (err) {
        this.$toast.error(err.response?.data?.error || 'Failed to repair');
      }
    },
    logout() {
      localStorage.removeItem('session_sid');
      localStorage.removeItem('username');
      localStorage.removeItem('role');
      this.$router.push('/login');
    },
  },
};
</script>

