    background: var(--surface-2);
    color: var(--text);
    font-family: 'SF Mono', Menlo, monospace;
    font-size: 13px;
    resize: vertical;
    transition: border-color var(--transition);
  }
  textarea.subtitle-text:focus {
    outline: none;
    border-color: var(--accent);
  }

  .subtitle-controls .btn { flex: 1; min-width: 80px; }

  .settings-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 12px;
  }
  .setting {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius-sm);
    padding: 12px;
  }
  .setting label {
    display: block;
    font-size: 12px;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--text-dim);
    margin-bottom: 6px;
  }
  .setting select, .setting input[type="color"], .setting input[type="number"] {
    width: 100%;
    padding: 8px 10px;
    border: 1px solid var(--border);
    border-radius: var(--radius-sm);
    background: var(--surface-2);
    color: var(--text);
    font-family: inherit;
    font-size: 13px;
  }
  .setting input[type="color"] {
    padding: 6px;
  }
  .setting input[type="number"] { font-family: 'SF Mono', monospace; }

  .empty-state {
    text-align: center;
    padding: 40px 20px;
    color: var(--text-dim);
    background: var(--surface);
    border: 1px dashed var(--border);
    border-radius: var(--radius);
  }

  .toast {
    position: fixed;
    bottom: 24px;
    left: 50%;
    transform: translateX(-50%) translateY(20px);
    background: var(--surface-2);
    border: 1px solid var(--accent);
    color: var(--text);
    padding: 12px 20px;
    border-radius: var(--radius-sm);
    box-shadow: var(--shadow);
    opacity: 0;
    pointer-events: none;
    transition: all var(--transition);
    z-index: 1000;
  }
  .toast.show {
    opacity: 1;
    transform: translateX(-50%) translateY(0);
  }

  .progress {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 12px;
  }
  .progress-bar {
    flex: 1;
    height: 6px;
    background: var(--surface-2);
    border-radius: 3px;
    overflow: hidden;
    cursor: pointer;
  }
  .progress-fill {
    height: 100%;
    background: var(--accent);
    width: 0%;
    transition: width 0.1s linear;
  }
  .progress-time {
    font-family: 'SF Mono', monospace;
    font-size: 12px;
    color: var(--text-dim);
  }

  .export-section {
    display: flex;
    gap: 12px;
    flex-wrap: wrap;
  }
  .export-section .btn { flex: 1; min-width: 140px; }

  .legend {
    display: flex;
    gap: 16px;
    margin-top: 12px;
    padding: 12px;
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius-sm);
  }
  .legend-item {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 13px;
  }
  .legend-item span {
    display: inline-block;
    width: 12px;
    height: 12px;
    border-radius: 3px;
    background: currentColor;
  }

  .drag-area {
    border: 2px dashed var(--border);
    border-radius: var(--radius-sm);
    padding: 20px;
    text-align: center;
    color: var(--text-dim);
    background: var(--surface);
    transition: all var(--transition);
  }
  .drag-area:hover, .drag-area.drag {
    border-color: var(--accent);
    background: var(--surface-2);
    color: var(--text);
  }

  .spinner {
    width: 20px;
    height: 20px;
    border: 3px solid var(--surface-2);
    border-top-color: var(--accent);
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
  }
  @keyframes spin { to { transform: rotate(360deg); } }

  .modal-backdrop {
    position: fixed;
    inset: 0;
    background: rgba(0,0,0,0.6);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 2000;
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--transition);
  }
  .modal-backdrop.show {
    opacity: 1;
    pointer-events: auto;
  }
  .modal {
    background: var(--surface);
    border-radius: var(--radius);
    padding: 24px;
    max-width: 480px;
    width: 100%;
    box-shadow: var(--shadow);
    transform: scale(0.95);
    transition: transform var(--transition);
  }
  .modal.show { transform: scale(1); }
  .modal h3 { margin-bottom: 12px; }
  .modal textarea {
    width: 100%;
    margin-bottom: 12px;
  }
  .modal .btn { margin-top: 8px; }

  .video-error {
    color: var(--danger);
    font-size: 14px;
    margin-top: 8px;
  }

  .hint {
    font-size: 12px;
    color: var(--text-dim);
    margin-top: 8px;
  }

  .btn-group {
    display: flex;
    gap: 8px;
  }
</style>
</head>
<body>

<div class="app">

  <div class="card">
    <div class="card-header">
      <h1><i class="fa-solid fa-subtitles"></i> Subtitle Generator</h1>
      <span id="subtitleCount">0 subtitles</span>
    </div>
    <div class="drag-area" id="dropZone">
      <i class="fa-solid fa-cloud-arrow-up fa-3x" style="color: var(--accent); margin-bottom: 12px;"></i>
      <h2>Drop your video here</h2>
      <p>or click to browse</p>
      <input type="file" id="videoInput" accept="video/*" hidden />
    </div>
    <div class="hint">Tip: Use the <strong>Start</strong> and <strong>End</strong> time inputs to mark subtitle segments.</div>
  </div>

  <div id="videoContainer" style="display:none;">
    <div class="card">
      <div class="card-header">
        <h2><i class="fa-solid fa-play"></i> Video Player</h2>
        <div class="progress">
          <div class="progress-bar"><div class="progress-fill" id="progressFill"></div></div>
          <span class="progress-time" id="currentTime">0:00</span>
          <span class="progress-time" id="duration">0:00</span>
        </div>
      </div>
      <div class="video-wrap">
        <video id="video" preload="metadata" controls crossorigin="anonymous"></video>
        <div class="video-overlay">
          <div class="subtitle" id="liveSubtitle"></div>
        </div>
      </div>
      <div class="subtitle-controls">
        <button class="btn" id="addSubtitle"><i class="fa-solid fa-plus"></i> Add Subtitle</button>
        <button class="btn danger" id="clearSubtitles"><i class="fa-solid fa-trash"></i> Clear All</button>
      </div>
    </div>

    <div class="card">
      <div class="card-header">
        <h2><i class="fa-solid fa-list"></i> Subtitles</h2>
        <button class="btn primary" id="exportVTT"><i class="fa-solid fa-file-lines"></i> Export .vtt</button>
      </div>
      <div id="subtitleList" class="subtitle-list">
        <div class="empty-state">
          <i class="fa-solid fa-film"></i>
          <p>No subtitles yet. Click <strong>Add Subtitle</strong> to get started.</p>
        </div>
      </div>
    </div>

    <div class="card">
      <div class="card-header">
        <h2><i class="fa-solid fa-palette"></i> Settings</h2>
      </div>
      <div class="settings-grid">
        <div class="setting">
          <label for="fontFamily">Font Family</label>
          <select id="fontFamily">
            <option value="Georgia, serif">Georgia</option>
            <option value="'Times New Roman', serif">Times New Roman</option>
            <option value="'Courier New', monospace">Courier New</option>
            <option value="'SF Mono', monospace">SF Mono</option>
            <option value="'Arial Black', sans-serif">Arial Black</option>
            <option value="'Comic Sans MS', cursive">Comic Sans</option>
            <option value="system-ui, sans-serif">System UI</option>
            <option value="serif">Serif</option>
            <option value="monospace">Monospace</option>
          </select>
        </div>
        <div class="setting">
          <label for="fontSize">Font Size (px)</label>
          <input type="number" id="fontSize" min="12" max="72" value="24" />
        </div>
        <div class="setting">
          <label for="fontColor">Font Color</label>
          <input type="color" id="fontColor" value="#ffffff" />
        </div>
        <div class="setting">
          <label for="backgroundColor">Background</label>
          <input type="color" id="backgroundColor" value="#000000" />
        </div>
        <div class="setting">
          <label for="borderColor">Border Color</label>
          <input type="color" id="borderColor" value="#7c5cff" />
        </div>
        <div class="setting">
          <label for="shadowColor">Shadow Color</label>
          <input type="color" id="shadowColor" value="#000000" />
        </div>
        <div class="setting">
          <label for="lineHeight">Line Height</label>
          <input type="number" id="lineHeight" min="1" max="3" step="0.1" value="1.2" />
        </div>
        <div class="setting">
          <label for="padding">Padding (px)</label>
          <input type="number" id="padding" min="0" max="40" value="10" />
        </div>
      </div>
    </div>

    <div class="card">
      <div class="card-header">
        <h2><i class="fa-solid fa-code"></i> Export Video with Subtitles</h2>
        <p class="hint">Requires server-side FFmpeg. Demo gives instructions.</p>
      </div>
      <div class="export-section">
        <button class="btn primary" id="exportVideo"><i class="fa-solid fa-download"></i> Export Video</button>
        <button class="btn" id="downloadVTT"><i class="fa-solid fa-download"></i> Download .vtt</button>
      </div>
    </div>
  </div>

</div>

<div class="toast" id="toast" role="status" aria-live="polite"></div>

<div class="modal-backdrop" id="modalBackdrop" hidden>
  <div class="modal">
    <h3 id="modalTitle">Add Subtitle</h3>
    <div class="subtitle-controls">
      <label for="modalStart">Start</label>
      <input class="time-input" id="modalStart" type="time" />
      <label for="modalEnd">End</label>
      <input class="time-input" id="modalEnd" type="time" />
    </div>
    <textarea id="modalText" rows="3" placeholder="Type your subtitle text..."></textarea>
