    <div class="legend-item"><span style="background:#000000"></span> Shadow</div>
  </div>

</div>

<script>
// ---------- State ----------
const state = {
  subtitles: [],
  currentVideo: null,
  videoDuration: 0,
  settings: {
    fontFamily: 'Georgia, serif',
    fontSize: 24,
    fontColor: '#ffffff',
    backgroundColor: '#000000',
    borderColor: '#7c5cff',
    shadowColor: '#000000',
    lineHeight: 1.2,
    padding: 10,
    shadowBlur: 4,
    shadowSpread: 0
  },
  liveSubtitle: null
};

// ---------- DOM ----------
const $ = (id) => document.getElementById(id);
const dropZone = $('dropZone');
const videoContainer = $('videoContainer');
const video = $('video');
const progressFill = $('progressFill');
const currentTimeEl = $('currentTime');
const durationEl = $('duration');
const liveSubtitle = $('liveSubtitle');
const subtitleList = $('subtitleList');
const toast = $('toast');
const modalBackdrop = $('modalBackdrop');
const modalTitle = $('modalTitle');
const modalStart = $('modalStart');
const modalEnd = $('modalEnd');
const modalText = $('modalText');

// ---------- Toast ----------
function toastMsg(msg) {
  toast.textContent = msg;
  toast.classList.add('show');
  clearTimeout(toast._t);
  toast._t = setTimeout(() => toast.classList.remove('show'), 2500);
}

// ---------- Drop Zone ----------
['dragenter', 'dragover'].forEach(ev => {
  dropZone.addEventListener(ev, (e) => {
    e.preventDefault(); e.stopPropagation();
    dropZone.classList.add('drag');
  });
});
['dragleave', 'drop'].forEach(ev => {
  dropZone.addEventListener(ev, (e) => {
    e.preventDefault(); e.stopPropagation();
    dropZone.classList.remove('drag');
  });
});
dropZone.addEventListener('drop', (e) => {
  const file = e.dataTransfer.files[0];
  if (file) handleFile(file);
});
$('videoInput').addEventListener('change', (e) => {
  const file = e.target.files[0];
  if (file) handleFile(file);
});

function handleFile(file) {
  if (!file.type.startsWith('video/')) {
    toastMsg('Please upload a video file.');
    return;
  }
  const url = URL.createObjectURL(file);
  video.src = url;
  state.currentVideo = url;
  videoContainer.style.display = 'block';
  video.play().catch(() => {});
  toastMsg('Video loaded.');
  // Clear subtitles on new video
  state.subtitles = [];
  updateSubtitleList();
}

// ---------- Subtitle Row ----------
function createSubtitleRow(idx, sub) {
  const row = document.createElement('div');
  row.className = 'subtitle-row';
  row.dataset.idx = idx;
  row.innerHTML = `
    <span class="idx">${idx + 1}</span>
    <input type="time" class="time-input" data-start="${idx}" value="${formatTime(sub.start)}" />
    <input type="time" class="time-input" data-end="${idx}" value="${formatTime(sub.end)}" />
    <textarea class="subtitle-text" data-text="${idx}">${escapeHtml(sub.text || '')}</textarea>
    <button class="btn danger" data-del="${idx}"><i class="fa-solid fa-trash"></i></button>
  `;
  row.querySelectorAll('input, textarea').forEach(el => el.addEventListener('change', onSubtitleChange));
  row.querySelector('button[data-del]').addEventListener('click', () => removeSubtitle(idx));
  return row;
}

function updateSubtitleList() {
  subtitleList.innerHTML = '';
  if (state.subtitles.length === 0) {
    const empty = document.createElement('div');
    empty.className = 'empty-state';
    empty.innerHTML = `
      <i class="fa-solid fa-film"></i>
      <p>No subtitles yet. Click <strong>Add Subtitle</strong> to get started.</p>
    `;
    subtitleList.appendChild(empty);
    return;
  }
  state.subtitles.forEach((sub, i) => subtitleList.appendChild(createSubtitleRow(i, sub)));
  $('subtitleCount').textContent = `${state.subtitles.length} subtitle${state.subtitles.length === 1 ? '' : 's'}`;
}

function onSubtitleChange(e) {
  const idx = parseInt(e.target.dataset.idx || e.target.dataset.text);
  const sub = state.subtitles[idx];
  if (!sub) return;
  if (e.target.matches('[data-start]')) sub.start = parseTime(e.target.value);
  else if (e.target.matches('[data-end]')) sub.end = parseTime(e.target.value);
  else if (e.target.matches('[data-text]')) sub.text = e.target.value;
  // Keep sorted
  state.subtitles.sort((a, b) => a.start - b.start);
  updateSubtitleList();
  // Sync live subtitle
  if (video.currentTime >= sub.start && video.currentTime < sub.end) {
    state.liveSubtitle = sub;
  }
}

function removeSubtitle(idx) {
  state.subtitles.splice(idx, 1);
  state.subtitles.sort((a, b) => a.start - b.start);
  updateSubtitleList();
  if (state.liveSubtitle && state.liveSubtitle.idx === idx) {
    state.liveSubtitle = state.subtitles.find(s => s.idx === state.liveSubtitle.idx);
  }
}

// ---------- Add Subtitle Modal ----------
function openModal(mode) {
  modalTitle.textContent = mode === 'edit' ? 'Edit Subtitle' : 'Add Subtitle';
  modalStart.value = formatTime(0);
  modalEnd.value = formatTime(state.videoDuration || 30);
  modalText.value = '';
  modalBackdrop.hidden = false;
  modalBackdrop.classList.add('show');
  setTimeout(() => modalText.focus(), 50);
}

function closeModal() {
  modalBackdrop.classList.remove('show');
  setTimeout(() => { modalBackdrop.hidden = true; }, 250);
}

modalBackdrop.addEventListener('click', (e) => {
  if (e.target === modalBackdrop) closeModal();
});

// ---------- Export VTT ----------
function exportVTT() {
  if (state.subtitles.length === 0) {
    toastMsg('No subtitles to export.');
    return;
  }
  const header = 'WEBVTT\n\n';
  const lines = state.subtitles.map((sub, i) => {
    const s = sub.start.toFixed(3);
    const e = sub.end.toFixed(3);
    const text = sub.text.split('\n').map(l => l.trim()).filter(Boolean).join('\n');
    return `${i + 1}\n${s} --> ${e}\n${text}`;
  }).join('\n\n');
  const blob = new Blob([header + lines], { type: 'text/vtt;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'subtitles.vtt';
  a.click();
  URL.revokeObjectURL(url);
  toastMsg('Subtitles exported as subtitles.vtt');
}

// ---------- Export Video with Subtitles ----------
function exportVideoWithSubtitles() {
  if (!state.currentVideo || state.subtitles.length === 0) {
    toastMsg('No video or subtitles to export.');
    return;
  }
  toastMsg('Preparing video export... (requires server-side FFmpeg)');
  setTimeout(() => {
    toastMsg('FFmpeg is required on the server. Demo instructions:');
    setTimeout(() => {
      toastMsg(`
        1. Install FFmpeg: https://ffmpeg.org/download.html
        2. Run: ffmpeg -i ${encodeURIComponent(state.currentVideo)} -vf "subtitles=subtitles.vtt" output.mp4
        3. Or use a cloud service like CloudConvert, HandBrake, or FFmpeg Online.
      `);
    }, 1500);
  }, 800);
}

// ---------- Live Subtitle Display ----------
function updateLiveSubtitle() {
  if (!state.liveSubtitle) {
    liveSubtitle.classList.remove('show');
    return;
  }
  liveSubtitle.textContent = state.liveSubtitle.text;
  liveSubtitle.classList.add('show');
}

// ---------- Format Helpers ----------
function formatTime(sec) {
  if (!isFinite(sec) || sec < 0) sec = 0;
  const h = Math.floor(sec / 3600);
  const m = Math.floor((sec % 3600) / 60);
  const s = Math.floor(sec % 60);
  const ms = Math.floor((sec - Math.floor(sec)) * 100);
  const pad = (n) => String(n).padStart(2, '0');
  return `${h ? h + ':' : ''}${pad(m)}:${pad(s)}.${ms}`;
}

function parseTime(str) {
  if (!str) return 0;
  const [h, m, s] = str.split(':').map(Number);
  const total = (h || 0) * 3600 + (m || 0) * 60 + (s || 0);
  const ms = parseFloat(str.split('.').pop() || '0');
  return total + ms / 100;
}

function escapeHtml(str) {
  return String(str).replace(/[&<>"']/g, c => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  }[c]));
}

// ---------- Video Events ----------
video.addEventListener('loadedmetadata', () => {
  state.videoDuration = video.duration;
  durationEl.textContent = formatTime(state.videoDuration);
  updateLiveSubtitle();
});
video.addEventListener('timeupdate', () => {
  const t = video.currentTime;
  currentTimeEl.textContent = formatTime(t);
  progressFill.style.width = (t / state.videoDuration * 100) + '%';
  const active = state.subtitles.find(s => t >= s.start && t < s.end);
  if (active) state.liveSubtitle = active;
  else state.liveSubtitle = null;
  updateLiveSubtitle();
});
video.addEventListener('ended', () => {
  state.liveSubtitle = null;
  updateLiveSubtitle();
});

// ---------- Settings ----------
['fontFamily', 'fontSize', 'fontColor', 'backgroundColor', 'borderColor', 'shadowColor', 'lineHeight', 'padding'].forEach(id => {
  $('video').style.setProperty('--' + id, $('video').getAttribute('data-' + id));
  $('video').addEventListener('change', (e) => {
    if (e.target.id === id) {
      $('video').setAttribute('data-' + id, e.target.value);
      $('video').style.setProperty('--' + id, e.target.value);
    }
  });
});

// ---------- Buttons ----------
$('addSubtitle').addEventListener('click', () => {
  if (!state.videoDuration) {
    toastMsg('Upload a video first.');
    return;
  }
  state.subtitles.push({
    start: 0,
    end: state.videoDuration,
    text: '',
    idx: state.subtitles.length
  });
  updateSubtitleList();
  openModal('add');
});

$('clearSubtitles').addEventListener('click', () => {
  if (state.subtitles.length === 0) return;
  if (!confirm('Clear all subtitles?')) return;
  state.subtitles = [];
  updateSubtitleList();
  state.liveSubtitle = null;
  updateLiveSubtitle();
  toastMsg('All subtitles cleared.');
});

$('exportVTT').addEventListener('click', exportVTT);
$('downloadVTT').addEventListener('click', () => {
  if (state.subtitles.length === 0) {
    toastMsg('No subtitles to download.');
    return;
  }
  exportVTT();
  toastMsg('Subtitles downloaded.');
});

$('exportVideo').addEventListener('click', exportVideoWithSubtitles);

// ---------- Keyboard ----------
document.addEventListener('keydown', (e) => {
  if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
    if (modalBackdrop.classList.contains('show')) {
      e.preventDefault();
      closeModal();
      openModal('add');
    }
  }
});

// ---------- Init ----------
updateSubtitleList();
</script>
</body>
</html>
```

---

## ✅ How to Use

1. **Upload a video** — drag and drop or click the drop zone.
2. **Add subtitles** — click "Add Subtitle", set start/end times, type text, then click "Add".
3. **Customize** — use the settings panel to change font, size, color, padding, etc.
4. **Sync playback** — subtitles display live as you play the video.
5. **Export** — export subtitles as a `.vtt` file or export the video with embedded subtitles (requires server-side FFmpeg).

---

## ⚠️ Limitations

- **Embedded subtitles** require server-side FFmpeg (not supported in browser).
- **Video duration** is read from the video element; subtitles must fit within it.
- **Time inputs** are in `hh:mm:ss.sss` format (HH is optional).
- **Mobile** may require touch adjustments.

---

## 🎬 Export Instructions (Server-side)

After generating `subtitles.vtt`, run:

```bash
ffmpeg -i input.mp4 -vf "subtitles=subtitles.vtt" output.mp4
```

Or use cloud services like [CloudConvert](https://cloudconvert.com/ffmpeg) or [HandBrake](https://handbrake.fr/).

