<script>
// ---------- State ----------
const state = {
  blocks: [],
  variables: {},
  templateId: 't_' + Math.random().toString(36).slice(2, 8),
  analytics: []
};

// ---------- Blocks ----------
const BLOCK_TYPES = [
  { id: 'h1', label: 'Headline', icon: 'H1' },
  { id: 'h2', label: 'Subheading', icon: 'H2' },
  { id: 'p', label: 'Paragraph', icon: 'P' },
  { id: 'link', label: 'Button', icon: 'Link' },
  { id: 'image', label: 'Image', icon: 'Image' },
  { id: 'divider', label: 'Divider', icon: 'Divider' },
  { id: 'social', label: 'Social Proof', icon: 'Heart' },
  { id: 'test', label: 'Testimonial', icon: 'Quote' },
  { id: 'footer', label: 'Footer', icon: 'Footer' }
];

function createBlock(type) {
  const block = document.createElement('div');
  block.className = 'editor-block';
  block.draggable = true;
  block.dataset.type = type;
  block.innerHTML = `
    <div class="block-preview"></div>
    <input type="text" placeholder="Title" data-field="title" />
    <textarea placeholder="Content (supports {name}, {product}, etc.)" data-field="content"></textarea>
    <button data-action="remove-block">Remove</button>
  `;
  block.addEventListener('dragstart', (e) => {
    block.classList.add('dragging');
    e.dataTransfer.setData('text/plain', block.dataset.type);
  });
  block.addEventListener('dragend', () => block.classList.remove('dragging'));
  block.querySelector('[data-action="remove-block"]').addEventListener('click', () => {
    block.remove();
    state.blocks = state.blocks.filter(b => b.id !== block.dataset.id);
    render();
  });
  return block;
}

function insertBlock(type, index) {
  const block = createBlock(type);
  const id = 'b_' + Date.now();
  block.dataset.id = id;
  block.querySelector('[data-field="title"]').value = type === 'divider' ? 'Divider' : '';
  block.querySelector('[data-field="content"]').value = type === 'divider' ? '<hr/>' : '';
  if (state.blocks.length === 0) {
    state.blocks.push(block);
  } else {
    state.blocks.splice(index, 0, block);
  }
  render();
}

// ---------- Rendering ----------
function render() {
  const canvas = document.getElementById('canvas');
  canvas.innerHTML = '';
  state.blocks.forEach(block => canvas.appendChild(block));
  renderVariables();
  renderAnalytics();
}

function renderVariables() {
  const list = document.getElementById('var-list');
  list.innerHTML = '';
  Object.entries(state.variables).forEach(([key, value]) => {
    const item = document.createElement('div');
    item.className = 'var-item';
    item.innerHTML = `
      <input type="text" value="${escapeHtml(value)}" data-var="${key}" />
      <button class="remove" data-remove="${key}">✕</button>
    `;
    item.querySelector('[data-remove]').addEventListener('click', () => {
      delete state.variables[key];
      render();
    });
    list.appendChild(item);
  });
}

function renderAnalytics() {
  const total = state.analytics.length;
  const opens = state.analytics.filter(a => a.status === 'opened').length;
  const clicks = state.analytics.filter(a => a.status === 'clicked').length;
  const unsub = state.analytics.filter(a => a.status === 'unsubscribed').length;
  document.getElementById('stat-total').textContent = total;
  document.getElementById('stat-open').textContent = total ? Math.round((opens / total) * 100) + '%' : '0%';
  document.getElementById('stat-click').textContent = total ? Math.round((clicks / total) * 100) + '%' : '0%';
  document.getElementById('stat-unsub').textContent = unsub;
  renderCharts();
}

function renderCharts() {
  const openChart = new Chart(document.getElementById('chart-open'), {
    type: 'line',
    data: {
      labels: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'],
      datasets: [{
        label: 'Open Rate',
        data: [12, 18, 22, 25, 28, 30, 32],
        borderColor: '#4e79a7',
        fill: false,
        tension: 0.3
      }]
    }
  });

  const statusChart = new Chart(document.getElementById('chart-status'), {
    type: 'pie',
    data: {
      labels: ['Sent', 'Delivered', 'Opened', 'Clicked', 'Bounced', 'Unsubscribed'],
      datasets: [{
        data: [400, 380, 280, 180, 20, 10],
        backgroundColor: ['#4e79a7', '#f6c23e', '#e16462', '#59a14f', '#965f91', '#d48265']
      }]
    }
  });

  const sentOpenChart = new Chart(document.getElementById('chart-sent-open'), {
    type: 'bar',
    data: {
      labels: ['Template A', 'Template B'],
      datasets: [{
        label: 'Sent',
        data: [250, 220],
        backgroundColor: '#4e79a7'
      }, {
        label: 'Opened',
        data: [200, 170],
        backgroundColor: '#f6c23e'
      }]
    }
  });
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, c => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  }[c]));
}

// ---------- Actions ----------
document.addEventListener('click', (e) => {
  const action = e.target.closest('[data-action]');
  if (!action) return;
  const actionName = action.dataset.action;
  const canvas = document.getElementById('canvas');
  const blocks = Array.from(canvas.querySelectorAll('.editor-block'));
  const activeBlock = blocks.find(b => b === canvas.activeElement);

  if (actionName === 'bold') {
    document.execCommand('bold', false, null);
  } else if (actionName === 'italic') {
    document.execCommand('italic', false, null);
  } else if (actionName === 'underline') {
    document.execCommand('underline', false, null);
  } else if (actionName === 'insert-block') {
    insertBlock(BLOCK_TYPES[0].id, activeBlock ? blocks.indexOf(activeBlock) : blocks.length);
  } else if (actionName === 'preview') {
    previewEmail();
  } else if (actionName === 'generate-ab') {
    generateABVariants();
  } else if (actionName === 'send-test') {
    sendTestEmail();
  }
});

// Block contenteditable
document.getElementById('canvas').addEventListener('input', (e) => {
  if (e.target.matches('.editor-block')) {
    const preview = e.target.querySelector('.block-preview');
    if (preview) {
      const content = e.target.querySelector('[data-field="content"]').value;
      const title = e.target.querySelector('[data-field="title"]').value;
      if (title) preview.textContent = title;
      else if (content) preview.textContent = content;
    }
  }
});

// ---------- Preview ----------
function previewEmail() {
  const content = document.getElementById('canvas').innerHTML;
  const vars = state.variables;
  const preview = document.querySelector('.preview-box');
  preview.innerHTML = '';
  const title = document.querySelector('.editor-block input[data-field="title"]').value;
  const body = document.querySelector('.editor-block textarea[data-field="content"]').value;
  if (title) preview.innerHTML = `<h1>${title}</h1>`;
  if (body) {
    const rendered = interpolate(body, vars);
    preview.innerHTML += `<p>${rendered}</p>`;
  }
  showToast('Preview ready');
}

// ---------- A/B Variants ----------
function generateABVariants() {
  const blocks = Array.from(document.getElementById('canvas').querySelectorAll('.editor-block'));
  const titles = blocks.map(b => b.querySelector('[data-field="title"]').value);
  const contents = blocks.map(b => b.querySelector('[data-field="content"]').value);

  // Build variants A and B
  const variants = [
    { name: 'A', blocks: blocks },
    { name: 'B', blocks: blocks }
  ];

  variants.forEach(v => {
    v.blocks.forEach(block => {
      const content = block.querySelector('[data-field="content"]').value;
      const parsed = parseConditions(content, state.variables);
      block.querySelector('[data-field="content"]').value = parsed;
    });
  });

  showToast(`Generated ${variants.length} variants`);
}

function parseConditions(html, vars) {
  // Replace <!-- if: condition --> ... <!-- end --> blocks
  return html.replace(/<!--\s*if:\s*(.+?)\s*-->([\s\S]*?)<!--\s*end\s*-->/g, (m, cond, body) => {
    try {
      if (eval(cond)) return body;
      return '';
    } catch { return body; }
  });
}

// ---------- Send Test ----------
function sendTestEmail() {
  const vars = state.variables;
  const subject = document.querySelector('.editor-block input[data-field="title"]').value || 'No Subject';
  const result = sendEmail(vars, subject, state.templateId);
  state.analytics.push(...result);
  renderAnalytics();
  showToast(`Sent ${result.length} test emails`);
}

function sendEmail(vars, subject, templateId) {
  const recipients = ['user1@example.com', 'user2@example.com', 'user3@example.com'];
  const statuses = ['sent', 'delivered', 'opened', 'clicked', 'bounced', 'unsubscribed'];
  const result = [];
  recipients.forEach(r => {
    const status = statuses[Math.floor(Math.random() * statuses.length)];
    result.push({
      timestamp: new Date().toISOString(),
      recipient: r,
      status,
      variant: 'v_A',
      subject,
      template_id: templateId
    });
  });
  return result;
}

// ---------- Toast ----------
function showToast(msg) {
  const t = document.getElementById('toast');
  t.textContent = msg;
  t.hidden = false;
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => { t.hidden = true; }, 2500);
}

// ---------- Init ----------
function init() {
  state.blocks = [
    { type: 'h1', title: 'Welcome', content: 'Hello {name}!' },
    { type: 'p', title: '', content: 'This is a sample email template.' }
  ];
  state.variables = {
    name: 'Alex',
    company: 'Acme Inc.',
    date: new Date().getFullYear(),
    discount: 15,
    product: 'Pro Plan',
    price: '$29',
    link: 'https://example.com'
  };

  BLOCK_TYPES.forEach((t, i) => {
    const btn = document.createElement('button');
    btn.innerHTML = `<span>${t.icon}</span><span>${t.label}</span>`;
    btn.title = 'Add ' + t.label;
    btn.addEventListener('click', () => insertBlock(t.id, state.blocks.length));
    document.querySelector('.editor-toolbar').appendChild(btn);
  });

  render();
}

init();
</script>
</body>
</html>
