## 2. Create `server.js`

```javascript
// server.js
const express = require('express');
const multer = require('multer');
const path = require('path');
const fs = require('fs').promises;
const app = express();
const PORT = process.env.PORT || 3000;

// Configure upload directory
const UPLOAD_DIR = path.join(__dirname, 'file');
if (!fs.existsSync(UPLOAD_DIR)) {
  fs.mkdir(UPLOAD_DIR, { recursive: true });
}

// Multer storage
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, UPLOAD_DIR);
  },
  filename: (req, file, cb) => {
    // Use a unique filename based on original name + chunk index
    const ext = path.extname(file.originalname);
    const name = path.basename(file.originalname, ext);
    cb(null, `${name}-${req.params.chunkIndex || 0}${ext}`);
  }
});

// File filter: only allow certain types
const fileFilter = (req, file, cb) => {
  const allowed = ['image/jpeg', 'image/png', 'image/gif', 'application/pdf', 'text/plain'];
  if (allowed.includes(file.mimetype)) {
    cb(null, true);
  } else {
    cb(new Error('Invalid file type'), false);
  }
};

const upload = multer({
  storage,
  fileFilter,
  limits: { fileSize: 100 * 1024 * 1024 } // 100MB per chunk
});

// Serve static files (index.html, chunks)
app.use(express.static(path.join(__dirname, 'file')));

// API endpoint for uploading a chunk
app.post('/api/upload/:chunkIndex', upload.single('file'), (req, res) => {
  try {
    // Validate required params
    if (!req.params.chunkIndex) {
      return res.status(400).json({ error: 'Missing chunkIndex' });
    }
    const chunkIndex = parseInt(req.params.chunkIndex, 10);
    if (isNaN(chunkIndex) || chunkIndex < 0) {
      return res.status(400).json({ error: 'Invalid chunkIndex' });
    }

    const filename = req.file ? req.file.filename : null;
    const size = req.file ? req.file.size : 0;

    res.json({
      success: true,
      chunkIndex,
      filename,
      size,
      totalChunks: req.body.totalChunks || 1
    });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: err.message });
  }
});

// API endpoint to check if all chunks are uploaded
app.get('/api/status/:filename', async (req, res) => {
  const filename = req.params.filename;
  if (!filename) return res.status(400).json({ error: 'Missing filename' });

  try {
    const files = await fs.readdir(UPLOAD_DIR);
    const chunks = files.filter(f => f.startsWith(filename.split('.')[0]) && f.endsWith('.png') || f.endsWith('.jpg') || f.endsWith('.jpeg') || f.endsWith('.gif') || f.endsWith('.pdf') || f.endsWith('.txt'));
    const total = chunks.length;
    const uploaded = chunks.length;

    res.json({
      filename,
      total,
      uploaded,
      complete: total === uploaded
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// API endpoint to merge chunks into a single file
app.post('/api/merge/:filename', async (req, res) => {
  const filename = req.params.filename;
  if (!filename) return res.status(400).json({ error: 'Missing filename' });

  try {
    const files = await fs.readdir(UPLOAD_DIR);
    const chunks = files.filter(f => f.startsWith(filename.split('.')[0]) && f.endsWith('.png') || f.endsWith('.jpg') || f.endsWith('.jpeg') || f.endsWith('.gif') || f.endsWith('.pdf') || f.endsWith('.txt'));
    if (!chunks.length) {
      return res.status(404).json({ error: 'No chunks found' });
    }

    const totalChunks = chunks.length;
    const totalSize = chunks.reduce((sum, f) => sum + fs.statSync(path.join(UPLOAD_DIR, f)).size, 0);

    // Sort chunks by index
    const sorted = chunks.map(f => {
      const match = f.match(/-(\d+)\.(\w+)$/);
      return { name: f, index: parseInt(match[1], 10), ext: match[2] };
    }).sort((a, b) => a.index - b.index);

    const outPath = path.join(UPLOAD_DIR, `${filename}`);
    const outStream = fs.createWriteStream(outPath);

    for (const chunk of sorted) {
      const chunkPath = path.join(UPLOAD_DIR, chunk.name);
      const chunkStream = fs.createReadStream(chunkPath);
      chunkStream.pipe(outStream);
      await fs.unlink(chunkPath);
    }

    outStream.on('finish', () => {
      res.json({
        success: true,
        filename,
        totalChunks,
        totalSize,
        merged: true
      });
    });
    outStream.on('error', (err) => {
      res.status(500).json({ error: err.message });
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Health check
app.get('/api/health', (req, res) => {
  res.json({ status: 'ok', port: PORT });
});

// Serve index.html
app.get('/', (req, res) => {
  res.sendFile(path.join(__dirname, 'index.html'));
});

// Catch-all for unknown routes
app.use('*', (req, res) => {
  res.status(404).json({ error: 'Not found' });
});

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
